	val A = scala.io.StdIn.readLine.split(" ").map(_.toLong).reverse

	var N = List[Long](2L)

	def test(x: Long, y: List[Long]): List[Long] = {
		var list = y
		for(i<-1L until x){
			list = list ::: y.map(_ + i)
		}
		list
	}

