//区間[a,b]におけるcの倍数の最小値、最大値
ll minc(ll a, ll b, ll c) {
	if (a %c == 0) return a;
	else {
		ll ans = (a / c)*c + c;
		if (ans <= b) return ans;
		else return -1;
	}
}
ll maxc(ll a, ll b, ll c) {
	if (b%c == 0) return b;
	else {
		ll ans = (b / c)*c;
		if (ans >= a) return ans;
		else return -1;
	}
}
