pair <int64_t, int64_t> solve() {
    if (a[K - 1] != 2)
        return {-1, -1};

    int64_t l = 2;
    int64_t r = 3;
    for (int i = K - 2; i >= 0; i--) {
        // a[i] * dl >= l
        int64_t dl = (l + a[i] - 1) / a[i];
        // a[i] * dr <= r
        int64_t dr = r / a[i];
        if (dl > dr || dr == 0)
            return {-1, -1};
        l = max(dl * a[i], 1LL);
        r = dr * a[i] + a[i] - 1;
    }
    return {l, r};
}

