ll find(int end) {
    ll lo = 0;
    ll hi = 1e10;
    while (lo < hi) { 
        ll mid = lo + (hi - lo + 1) / 2;
        if (rem(mid) <= end)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}
