const int N = 100010;
int n;
int a[N];

inline void gg() { puts("-1"); exit(0); }
int main()
{
	scanf("%d", &n);
	for(int i = 1; i <= n; i ++) scanf("%d", &a[i]);
	if(a[n] > 2) gg();
	int mx = 2, mi = 2;
	for(int i = n; i >= 1; i --) {
		if(mx%a[i]) mx = mx/a[i]*a[i];
		if(mi%a[i]) mi = (mi/a[i]+1)*a[i];
		if(mi > mx) gg();
		mi = mi/a[i]*a[i];
		mx = mx/a[i]*a[i]+a[i]-1;
	}
	printf("%d %d\n", mi, mx);
	return 0;
}

