void solve() {
  int k;
  cin >> k;
  vector<int> a(k);
  for (int i = 0; i < k; ++i) {
    cin >> a[i];
  }
  if (a[k - 1] != 2) {
    cout << "-1\n";
    return;
  }
  ll l = 2, r = 3;
  for (int i = k - 2; i >= 0; --i) {
    ll s = ((l + a[i] - 1) / a[i]) * a[i];
    if (s > r) {
      cout << "-1\n";
      return;
    }
    l = s;
    r = s + a[i] - 1;
  }
  cout << l << " " << r << "\n";
}

int main() {
  ios_base :: sync_with_stdio(false);
  cin.tie(nullptr);
  int t;
  t = 1;
  while(t--) {
    solve();
  }
  return 0;
}

