#include <bits/stdc++.h>
using namespace std;

long long n, l = 2, r = 2;
long long a[100010];

int main()
{
	scanf("%lld", &n);
	for(register int i = 1; i <= n; ++i){
		scanf("%lld", &a[i]);
	}
	for(register int i = n; i >= 1; --i){
		if(l % a[i] != 0) l = l / a[i] * a[i] + a[i];
		r = r / a[i] * a[i] + a[i] - 1;
		if(l > r) break;
	}
	if(l > r) puts("-1");
	else printf("%lld %lld\n", l, r);
	return 0;
}

