#include <bits/stdc++.h>
using namespace std;

using ll = long long;

template <typename Pusher>
ll solve(vector<ll> const &A, Pusher pusher) {
    stack<pair<ll, size_t>> s;
    s.push(make_pair(2, 0));
    while (!s.empty()) {
        auto p = move(s.top());
        ll x = p.first;
        size_t g = p.second;
        if (g == A.size()) { return x; }
        s.pop();
        // wants x;
        ll a = A[g];
        if (x % a != 0) continue;
        ll q = x / a;
        pusher(s, a, q, g);
    }
    return -1;
}

void push_max(stack<pair<ll, size_t>> &s, ll a, ll q, size_t g) {
    for (ll j = a * (q+1) - 1, end = a * (q); j >= end; j--) {
        s.push(make_pair(j, g+1));
    }
}

void push_min(stack<pair<ll, size_t>> &s, ll a, ll q, size_t g) {
    for (ll j = a * (q), end = a * (q+1); j < end; j++) {
        s.push(make_pair(j, g+1));
    }
}

