int solve(int n, const vector<int> & a){
  int now = 2;
  for(int i = n-2;i >= 0;i--){
    if (a[i] >= 2 * a[i+1])return -1;
    if (a[i] > now){
      now = a[i];
    } else if (now % a[i] == 0){
      // do nothing
    } else {
      now = now + (a[i] - now % a[i]);
    }
  }
  return now;
}

