  for (int i = 0; i < K - 1; i++) {
    ans_max = chi_baisu(ans_max + A[i] - 1, A[i + 1]);
    ans_min = oki_baisu(ans_min, A[i + 1]);
  }

  // 元に戻す
  reverse(A.begin(), A.end());

  // 実際にシミュレートする
  ll kakunin = ans_min;
