using namespace std;

int N, x[100005];

int ok(ll val){
    ll rem = val;
    FOR(i,N){
        if(rem < x[i]) return 0;
        rem -= rem%x[i];
    }
    return rem;
}

int main(){

    ios :: sync_with_stdio(false);
    cin >> N;
    FOR(i,N) cin >> x[i];

    ll lo=1, hi=1e15, lwr=-1, upr=-1;
    while(lo <= hi){
        ll mid = (lo+hi)/2;
        ll rem = ok(mid);

        if(rem == 0){
            lo = mid+1;
        }
        else{
            hi = mid-1;
            if(rem == 2) lwr = mid;
        }
    }

    if(lwr == -1){
        cout << -1 << endl;
        return 0;
    }

    lo = 1, hi = 1000000000;
    while(lo <= hi){
        ll mid = (lo+hi)/2;
        ll rem = ok(mid);

        if(rem > 2){
            hi = mid-1;
        }
        else{
            lo = mid+1;
            if(rem == 2) upr = mid;
        }
    }

    cout << lwr << " " << upr << endl;

    return 0;
}

