const int N = 1e5 + 5;

typedef long long ll;

const ll mod = 1e9 + 7;

ll n, a[N];

ll check(ll x) {
    for (int i = 1; i <= n; i++) {
        x -= (x % a[i]);
    }
    return x;
}

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cin >> n;
    for (int i = 1; i <= n; i++) {
        cin >> a[i];
    }
    ll l = 1, r = 1e18;
    while (r - l > 1) {
        ll md = (l + r) >> 1;
        if (check(md) > 2) {
            r = md;
        } else {
            l = md;
        }
    }
    ll L = 0, R = 1e18;
    while (R - L > 1) {
        ll md = (L + R) >> 1;
        if (check(md) >= 2)
            R = md;
        else
            L = md;
    }
    if (check(R) != 2) {
        cout << -1;
        return 0;
    }
    cout << R << " " << l;
}

