void solve(ostringstream& aout, long long K, std::vector<long long> A){
	int bimax = 2;

	// 最大値
	vector<int> B;

	RREP(i, K) {
		B.push_back(bimax);
		if (A[i] > bimax) {
			cout << -1 << "\n";
			return;
		}

		bimax = intfloor(bimax, A[i]) * A[i] + (A[i] - 1);

	}
	B.push_back(bimax);
	reverse(ALLOF(B));

	// 最小値
	vector<int> C;
	int cimin = 2;
	RREP(i, K) {
		C.push_back(cimin);

		cimin = intceil(cimin, A[i]) * A[i];
	}

	C.push_back(cimin);
	reverse(ALLOF(C));

	rep(i, K + 1) {
		// すべてのiについて、Ci <= x <= Bi なる x が存在すればOK
		if (C[i] > B[i]) {
			cout << -1 << "\n";
			return;
		}
	}

	cout << C[0] << " " << B[0] << "\n";
}

