typedef long long int LONGLONG;

LONGLONG a[100005];
LONGLONG low[100005], up[100005];
int k;

inline LONGLONG upper_round(LONGLONG num, LONGLONG step) {
    return (num + step - 1) / step * step;
}

inline LONGLONG lower_round(LONGLONG num, LONGLONG step) {
    return num / step * step;
}

bool solve() {
    if (a[k] != 2LL && a[k] != 1LL)
        return false;

    low[k] = up[k] = 2LL;
    for (int i = k - 1; i >= 1; --i) {
        low[i] = upper_round(low[i + 1], a[i]);
        up[i] = lower_round(up[i + 1] + a[i + 1] - 1, a[i]);

        if (low[i] > up[i])
            return false;
    }

    return true;
}

int main(int argc, char* argv[]) {
    scanf("%d", &k);
    for (int i = 1; i <= k; ++i)
        scanf("%lld", &a[i]);

    if (solve()) {
        LONGLONG minans = low[1];
        LONGLONG maxans = up[1] + a[1] - 1;
        printf("%lld %lld\n", minans, maxans);
    } else
        puts("-1");

    return 0;
}

