int reverse_game_max(int i, const vector<int>& as, int n_i) {
  i-= 1;
//  if (n_i % as[i] != 0 || n_i == 0) {
//    return -1;
//  }
  if (i == 0) {
    int num = n_i + as[0] - 1;
    return num;
  } else {
    for (int j=as[i]-1; j>=0; j--) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_max(i, as, n_i + j + as[i-1] - 1);
      }
    }
    return -1;
  }
}

int reverse_game_min(int i, const vector<int>& as, int n_i) {
  i-= 1;
  if (n_i % as[i] != 0 || n_i == 0) {
    return -1;
  }
  if (i == 0) {
    int num = n_i;
    return num;
  } else {
    for (int j=0; j<as[i]; j++) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_min(i, as, n_i + j);
      }
    }
    return -1;
  }
}

