int main()
{
  cin >> N;
  for(int i = 0; i < N; i++) {
    cin >> A[i];
  }

  LL minAns = 2;
  for(int i = N-1; 1 <= i; i--) {
    if(A[i-1] == minAns) {
      continue;
    } else if(A[i-1] < minAns) {
      minAns = ((minAns/A[i-1]) + 1) * A[i-1];
    } else {
      if(A[i-1]/A[i] * A[i] > minAns) {
        cout << -1 << endl;
        return 0;
      }
      minAns = A[i-1];
    }
  }

  cout << minAns << " " << minAns + A[0]-1 << endl;

  return 0;
}

