typedef long long ll;

pair<ll, ll> solve(vector<int> a) {
    int n = a.size();
    if (a[n - 1] != 2) return {-1, -1};

    ll mn = 2, mx = 2;
    for (int i = n - 1; i >= 0; i--) {
        // x%a[i]=0
        // x-x%a[i+1]=old
        mn = (mn + a[i] - 1) / a[i] * a[i];
        mx = (mx + a[i]) / a[i] * a[i] - 1;
        if (mn > mx) return {-1, -1};
    }

    return {mn, mx};
};

int main() {
#ifdef HOME
    freopen("in", "r", stdin);
#endif

    int n;
    while (cin >> n) {
        vector<int> a(n);
        for (int i = 0; i < n; i++) cin >> a[i];

        auto o = solve(a);
        if (o.first == -1) cout << -1 << endl;
        else cout << o.first << " " << o.second << endl;
    }

    return 0;
}

