ll get(ll val, pair<ll, ll> range, int d){

    ll lft = 0;
    ll rgt = 1e18;

    ll res = -1;
    while(lft <= rgt){
        ll mid = (lft + rgt) >> 1;
        ll pass = mid - mid%val;
        if(pass >= range.first && pass <= range.second){
            res = mid;
            if(d) lft = mid + 1;
