			flag = false;
			break;
		}

		ma = (ma/s[i]+1)*s[i]-1;

		if (s[i] >= mi)
			mi = s[i];
		else if (mi%s[i] != 0)
		{
			mi = (mi/s[i]+1)*s[i];
			if (i>1)
				mi -- ;
		}
	}
	if (flag)
		printf ("%d %d\n",mi,ma);
	else
		printf ("-1\n");
	return 0;
}

