int N;
vector<long long> arr;
vector<long long> dp_max;
vector<long long> dp_min;

int solv(vector<long long> &dp, bool is_max) {
  dp[N] = 2;
  int max_boarder, min_bound;
  for (int i = arr.size() - 1; i > 0; i--) {
    max_boarder = dp[i+1] + arr[i];
    if (arr[i-1] >= max_boarder) {
      return 0;
    }

    if (dp[i+1] % arr[i-1] != 0) {
      min_bound = ((dp[i+1] / arr[i-1]) + 1) * arr[i-1];
    } else {
      min_bound = dp[i+1];
    }

    if (min_bound >= max_boarder) {
      return 0;
    }

    if (is_max) {
      dp[i] = ((max_boarder-1) / arr[i-1]) * arr[i-1];
    } else {
      dp[i] = min_bound;
    }

  }

  return 1;
}

