  dp_min.resize(N+1);

  int exist = solv(dp_max, true);
  if (!exist) {
    cout << -1 << endl;
    return 0;
  }

  solv(dp_min, false);

  int min_res, max_res;
  if (dp_min[1] % arr[0] == 0) {
    min_res = dp_min[1];
  } else {
    min_res = ((dp_min[1] % arr[0]) + 1) * arr[0];
  }


