bool judge(ll n, bool lower){
    REP(i,K){
        n -= n%A[i];    
    }
    if(lower && n <= 2) return true;
    if(!lower && n >= 2) return true;
    return false;
}

int main(){
    cin >> K;
    ll amax = -1;
    REP(i,K){
        ll a;
        cin >> a;
        A[i] = a;
        amax = max(amax, a);
    }

    ll N = 2 + K*amax;
    ll low = -1;
    ll high = -1;

    ll left, right;
    left = 2;
    right = N;
    while(right - left > 0){
        ll mid = (left+right)/2; 
        bool ok = judge(mid, true);
        if(ok) left = mid + 1, high = mid;
        else right = mid - 1;
    }

    left = 2;
    right = N;
    while(right - left > 0){
        ll mid = (left+right)/2; 
        bool ok = judge(mid, false);
        if(ok) right = mid - 1, low = mid - 1;
        else left = mid + 1;
    }

    if(high < low)
        cout << -1 << endl;
    else
        printf("%lld %lld\n", low, high);
    return 0;
}

