i64 arr[100005];

int main()
{
    int k;
    cin >> k;
    For(i,k)
    {
        cin >> arr[i];
    }

    i64 mn = arr[k-1];

    for(int i = k-2; i>=0; i--)
    {
        if(arr[i]>=mn)
            mn = arr[i];
        else
            mn += (arr[i] - mn%arr[i]);
    }

    i64 ans = mn;

    For(i,k)
        ans -= ans%arr[i];
    if(ans!=2)
    {
        cout << -1;
        return 0;
    }

    i64 lo = mn, hi = 100000000000000000;
    i64 mx;
    while(lo<hi)
    {
        i64 mid = lo + (hi-lo+1)/2;
        //cout << lo << " " << hi << endl;
        i64 tmp = mid;
        For(i,k)
            tmp -= tmp%arr[i];
        if(tmp!=2)
            hi = mid-1;
        else
        {
            mx = mid;
            lo = mid;
        }
    }

    cout << mn << " " << mx << endl;

    return 0;
}

