        ll mid = (left+right)/2; 
        bool ok = judge(mid, true);
        if(ok) left = mid;
        else right = mid;// - 1;
    }
    ll high = left;

    left = 2;
    right = N;
    //while(right - left > 1){
    for(int i = 0; i < 10000; i++){
        ll mid = (left+right)/2; 
        bool ok = judge(mid, false);
        if(ok) right = mid;
