ll N;
ll Nums[1234567];
ll buf = 0;
ll min;
ll max;

int main() {

	IN >> N;
	REP(a, N)
	{
		IN >> Nums[a];
	}

	if (Nums[N - 1] != 2)
	{
		puts("-1");
		return 0;
	}

	buf = 1;

	for (int a = N - 2; 0 - 1 <= a; --a)
	{
		if (a == -1)
		{
			max = Nums[a + 1] * 2 - 1;
			min = Nums[a + 1];
			break;
		}

		if (Nums[a + 1] * 2 - 1 >= Nums[a]
			&& Nums[a + 1] <= Nums[a])
		{
			buf++;
		}
		else if (Nums[a + 1] > Nums[a])
		{
			max = Nums[a + 1] * 2 - 1;
			min = Nums[a + 1];
			break;
		}
		else if (Nums[a + 1] * 2 - 1 < Nums[a])
		{
			puts("-1");
			return 0;
		}
	}

	for (int a = N - buf - 1; 0 <= a; --a)
	{

		if (max * 2 - 1 >= Nums[a])
		{
			if (min < Nums[a]) min = Nums[a];
			if (min >= Nums[a])
			{
				min = ((min - 1 + Nums[a]) / Nums[a]) * Nums[a];
			}
			max = ((max + Nums[a] - 1) / Nums[a]) * Nums[a] - 1;
		}
		else
		{
			puts("-1");
			return 0;
		}

	}

	OUT << min << " " << max << std::endl;

	return 0;

}

