            ll x = (l+r) / 2;
            ll sum = x;
            for(int i=0; i<k; i++){
                sum -= sum % a[i];
            }
            if(sum < 2) l = x;
            else r = x;
            chmin(mi, r);
        }

	    if(mi > mx) {
	        out << -1 << endl;
	        return;
	    }

	    out << mi sp mx << endl;
	}
};


