ll solve(ll left, ll right, function<ll(ll)> pred) {
	while (right - left > 1) {
		ll middle = left + right;
		middle /= 2;
		if (pred(middle)) {
			right = middle;
		}
		else {
			left = middle;
		}
	}
	return right;
}


