using namespace std;

int func(ll n, vector<int> &a, int level, int k){
	if(level == k){
		if(n > 2) return 1;
		else if(n == 2) return 0;
		else return -1;
	}else{
		n /= (ll)a.at(level);
		n *= (ll)a.at(level);
		return func(n, a, level+1, k);
	}
}

ll b_serch(ll l, ll r, vector<int> &a, int k){
	while(r - l > 1){
		ll mid = (l+r)/2;
		if(func(mid, a, 0, k) >= 0){
			r = mid;
		}else{
			l = mid;
		}
	}
	return r;
}

ll b_serch2(ll l, ll r, vector<int> &a, int k){
	while(r - l > 1){
		ll mid = (l+r)/2;
		if(func(mid, a, 0, k) <= 0){
			l = mid;
		}else{
			r = mid;
		}
	}
	return l;
}

