		L = (L + A[i] - 1) / A[i] * A[i];
		if (R < L) {
			cout << -1 << endl;
			return 0;
		}
		R = (R / A[i] + 1)*A[i] - 1;
	}
	cout << L << " " << R << endl;
	return 0;
}

