int binary_search_left(vector<int> &vec, long long left, long long right){
    if(right-left<2){
        return right;
    }
    long long mid=(left+right)/2;
    for(int i=0; i<vec.size(); i++){
        mid-=mid%vec[i];
    }
    if(mid==2){
        return binary_search_left(vec, left, mid);
    }else{
        return binary_search_left(vec, mid, right);
    }
}

int binary_search_right(vector<int> &vec, long long left, long long right){
    if(right-left<2){
        return left;
    }
    long long mid=(left+right)/2;
    for(int i=0; i<vec.size(); i++){
        mid-=mid%vec[i];
    }
    if(mid==2){
        return binary_search_right(vec, mid, right);
    }else{
        return binary_search_right(vec, left, mid);
    }
}

