ll rec1(vi & v , int k , ll n){
	ll mn = ((n + v[k] - 1) / v[k]) * v[k];
	if(k == 0) return mn;
	return rec1(v , k - 1 , mn);
}

ll rec2(vi & v , int k , ll n){
	ll mx = ((n + v[k] - 1) / v[k]) * v[k] + + v[k] - 1;
	if(k == 0) return mx;
	return rec2(v , k - 1 , mx);
}

bool ck(vi & v , ll n){
	rep(i , sz(v)){
		n = (n / v[i]) * v[i];
	}
	return n == 2ll;
}

