		cin >> A[i];
	}

	auto f = [&]( long long n ) -> long long
	{
		long long res = n;
		for( int i = 0; i < K; i++ ) {
			res -= res % A[i];
			if( res < 0 ) return -1;
		}
		return res;
	};

