		long long x = f( m );
		if( x == 2 ) {
			mi = min( mi, m );
			ma = max( ma, m );
		}
		if( x < 2 ) l = m;
		else r = m;
	}
	if( mi == ma ) {
		long long x = f( mi + 1 );
		if( x == 2 ) ma = max( ma, mi + 1 );
	}

	if( mi == INF && ma == 0 ) cout << -1 << endl;
	else cout << mi << " " << ma << endl;
}

