using ull = unsigned long long;

unordered_set<ull> next(unordered_set<ull> const &curr, ull A_i) {
    unordered_set<ull> res;
    for (auto x: curr) {
        // wants x;
        if (x % A_i != 0) continue;
        ull q = x / A_i;
        for (ull j = A_i * q, end = A_i * (q+1); j < end; j++) {
            res.insert(j);
        }
    }
    return res;
}

