const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll k, as[MAX_N];

bool judge(ll val){
    rep(i, k){
        val -= val % as[i];
        if (val < 2) return false;
    }

    return val == 2;
}

void solve(){
    rep(i, k) in1(as[i]);
    if (as[k - 1] != 2){
        prl(-1); return;
    }

    ll right = INF, left = 1;
    while(right > left){
        // when seeking upper bound
        ll mid = (right + left + 1) / 2;
        if (judge(mid)) left = mid;
        else right = mid - 1;
    }

    if (right > 1) prl2(right - right % as[0], right);
    else prl(-1);
}

int main(void){
    in1(k);
    // assert(k <= 100000);
    solve();
    return 0;
}

