const LL Inf=1e18;

LL high(int T, int A) {
  LL good=-1,bad=Inf;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx<=T?good:bad)=mid;
  }
  return good;
}

LL low(int T, int A) {
  LL good=Inf,bad=-1;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx>=T?good:bad)=mid;
  }
  return good;
}

// $ g++ -std=c++11 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
vector<LL> solve(int N, vector<LL> A) {
  if(A.back()!=2) return {};

  LL l=2,r=2;
  for(int i=N-1; i>=0; --i) {
    l=low(l,A[i]);
    r=high(r,A[i]);
    dump4(i,A[i],l,r);
    if(l>r) return {};
//    if(l<=-1||l>Inf) return {};
//    if(h<=-1||h>Inf) return {};
  }
  return {l,r};
}

vector<LL> solve_linear(int N, vector<LL> A) {
  if(A.back()!=2) return {};

  LL l=2,r=2;
  for(int i=N-1; i>=0; --i) {
    LL a=A[i];
    LL k1=(l+a-1)/a,k2=r/a;
    //    if(k1==0&&k2==0) return {};
    l=a*k1;
    r=a*(k2+1)-1;
    //    dump4(i,A[i],l,r);
    if(l>r) return {};
    //    if(l>h) return {};
    //    if(l<=-1||l>Inf) return {};
    //    if(h<=-1||h>Inf) return {};
  }
  return {l,r};
}

