using namespace std;

int calc(const int start, const vector<int> &a) {
        if (start < 0) return 0;
        int n = a.size();
        int val = start;
        for (int i = 0; i < n; i ++) {
                val = (int) (val / a[i]) * a[i];
        }
        if (val < 2) return 0;
        else if (val == 2) return 1;
        else return 2;
}

int main() {
        int n;
        scanf("%d", &n);
        vector<int> a(n);
        for (int i = 0; i < n; i ++) {
                scanf("%d", &a[i]);
        }
        int lb = 0, ub = 1e9;
        int ok = -1;
        int cnt = 100;
        while (cnt --) {
                int mid = (lb + ub) / 2;
                int get = calc(mid, a);
                if (get == 0) {
                        lb = mid;
                } else if (get == 2) {
                        ub = mid;
                } else {
                        ok = mid;
                        break;
                }
        }
        if (!~ok) {
                return !printf("-1\n");
        }
        int milb = 0, miub = ok + 1;
        while (miub - milb > 1) {
                int mid = (milb + miub) / 2;
                //printf("%d %d %d\n", milb, mid, miub);
                int get = calc(mid, a);
                assert(get != 2);
                if (get == 0) {
                        milb = mid;
                } else {
                        miub = mid;
                }
        }
        int malb = ok, maub = 1e9 + 10;
        while (maub - malb > 1) {
                int mid = (malb + maub) / 2;
                int get = calc(mid, a);
                assert(get != 0);
                if (get == 1) {
                        malb = mid;
                } else {
                        maub = mid;
                }
        }
        for (int mi = miub - 5; mi <= miub + 5; mi ++) {
                if (calc(mi, a) == 1) {
                        printf("%d ", mi);
                        break;
                }
        }
        for (int ma = malb + 5; ma >= malb - 5; ma --) {
                if (calc(ma, a) == 1) {
                        printf("%d\n", ma);
                        break;
                }
        }
        return 0;
}

