    while (r - l > 1) {
        int md = (l + r) >> 1;
        if (check(md) > 2) {
            r = md;
        } else {
            l = md;
        }
    }
    int ll = 0, rr = 1e9 + 1e9;
    while (rr - ll > 1) {
        int md = (ll + rr) >> 1;
        if (check(md) >= 2)
            rr = md;
        else
            ll = md;
    }
    if (check(rr) != 2) {
        cout << -1;
        return 0;
    }
    cout << rr << " " << l;
}

