int main()
{
    int K; cin >> K;
    vector<int> As(K); for (auto &Ai : As) cin >> Ai;
    // 試合を逆順に辿る：O(K)
    int min = 2, max = 2;
    for (int i = K - 1; i >= 0; --i)
    {
        int Ai = As[i];
        // [min, max]に含まれるAiの倍数のうち，最小値Xiおよび最大値Yiを計算
        int Xi = (min + Ai - 1) / Ai * Ai;
        int Yi = max / Ai * Ai;
        // 大きすぎるAiに対して，Xi > Yi = 0 となる場合は失敗
        if (Xi > Yi)
        {
            cout << -1 << endl;
            return 0;
        }
        // 組を作る前の最小人数はXi
        min = Xi;
        // 組を作る前の最大人数はYi＋Ai-1
        max = Yi + Ai - 1;
    }
    cout << min << ' ' << max << endl;
}

