{
	std::vector<int> ret;
	for(int i=1 ; i*i<=n ; ++i)
	{
		if(n%i == 0)
		{
			ret.push_back(i);
			if(i!=1 && i*i!=n)
			{
				ret.push_back(n/i);
			}
		}
	}
  ret.push_back(n);
	return ret;
}

void Ssort(int no, char *month[]){
    int i, j;
    char *temp;
    for(i=0; i<no; i++){
        for(j=i+1; j<no; j++){
            if(strcmp((month[i]),(month[j]))>0){
                temp = *(month+i);
                *(month+i) = *(month+j);
                *(month+j) = temp;
            }
        }    
    }
}

