typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)

ll discrete_binary_search(
    ll lo, ll hi, function<ll(ll)> f, bool maximize){
    while(lo < hi){
        const ll fhi = f(hi);
        const ll mid = (lo + hi + maximize) / 2;
        const ll fmid = f(mid);
        if(fmid > 0){
            if(fmid <= fhi){
                hi = mid - 1;
            }else{
                lo = mid + 1;
            }
        }else if(fmid == 0){
            if(maximize){
                lo = mid;
            }else{
                hi = mid;
            }
        }else{ // fmid < 0
            if(fmid <= fhi){
                lo = mid + 1;
            }else{
                hi = mid - 1;
            }
        }
    }
    return lo;
}

long long K;
std::vector<long long> A;

ll f(ll mid){
    REP(i, K){
        mid -= mid % A.at(i);
    }
    return mid;
}

void solve(){
    ll ans_max = discrete_binary_search(
        2, accumulate(A.begin(), A.end(), 2),
        [&](ll mid) -> ll {
            return f(mid) - 2;
        },
        true
    );

    if(f(ans_max) != 2){
        cout << -1 << endl;
        return;
    }

    ll ans_min = discrete_binary_search(
        2, ans_max,
        [&](ll mid) -> ll {
            return f(mid) - 2;
        },
        false
    );

    cout << ans_min << ' ' << ans_max << endl;
}

