vector<set<int>> dp;//dp[i]: ラウンドi開始時の残り人数の可能性

void search(int n){
	if(dp[n + 1].empty()){
		return;
	}
	for(auto&& c : dp[n + 1]){
		//ラウンドn終了時に残りc人である可能性があるなら開始時の人数を全てdp[n]に
		if(c >= a[n] && c%a[n] == 0){
			int num = c;
			int div = c / a[n];
			while(num < a[n] * (div + 1)){
				dp[n].insert(num++);
			}
		}
	}
}

