long long left(long long x,long long y){
    long long l=0;
    long long r=1e9;
    while(l<r){
        long long m=(l+r)/2;
        if(x*m<y)l=m+1;
        else r=m;
    }
    return x*l;
}
long long right(long long x,long long y){
    long long l=0;
    long long r=1e9;
    while(l<r){
        long long m=(l+r)/2;
        if(x*m<=y)l=m+1;
        else r=m;
    }
    return x*(l-1);
}
