ll ter1() {
	ll l = 0, r = 1e13 + 10, l1, r1, l2, r2, ans = -1;
	while(l <= r) {
		l1 = (2 * l + r) / 3;
		l2 = (l + 2 * r) / 3;
		r1 = calc(l1);
		r2 = calc(l2);
		if(r2 == 2)
			ans = l2;
		if(r1 == 2)
			ans = l1;
		if(r1 < 2)
			l = l1 + 1;
		else
			r = l2 - 1;
	}
	return ans;
}

ll ter2() {
	ll l = 0, r = 1e13 + 10, l1, r1, l2, r2, ans = -1;
	while(l <= r) {
		l1 = (2 * l + r) / 3;
		l2 = (l + 2 * r) / 3;
		r1 = calc(l1);
		r2 = calc(l2);
		if(r1 == 2)
			ans = l1;
		if(r2 == 2)
			ans = l2;
		if(r1 > 2)
			r = l2 - 1;
		else
			l = l1 + 1;
	}
	return ans;
}

