ll rec1(vi & v , int k , ll n){
	ll mn = (1ll * n / v[k]) * v[k];
	if(mn < n) mn += v[k];
	if(k == 0) return mn;
	return rec1(v , k - 1 , mn);
}

ll rec2(vi & v , int k , ll n){
	ll mx = (1ll * n / v[k]) * v[k];
	if(mx < n) mx += v[k];
	if(k == 0) return mx + v[k] - 1;
	return rec2(v , k - 1 , mx);
}

