ll get_high(ll high, ll target) {
  ll high_times = high / target;

  for (ll i = high_times + 1; i >= high_times - 1; --i) {
    ll cur = i * target;
    if (cur <= high) {
      return cur;
    }
  }

  return target;
}

ll get_low(ll low, ll target) {

  ll low_times = low / target;

  // printf("DO: %lld %lld %lld\n", low, target, low_times);

  for (ll i = low_times - 1; i <= low_times + 1; ++i) {
    ll cur = i * target;
    // printf("fuck: %lld\n", cur);
    if (cur >= low) {
      return cur;
    }
  }

  // printf("?? %lld %lld\n", low, target);

  return target;
}

bool check_include(ll low, ll high, ll target) {

  // printf("%lld %lld %lld\n", low, high, target);

  if (high < target) {
    // printf("too big\n");
    return false;
  }

  if (low <= target && target <= high) {
    return true;
  }

  ll t_high = get_high(high, target);

  if (low <= t_high && t_high <= high) {
    return true;
  } else {
    // printf("can not help\n");
    return false;
  }
}

