namespace arc078b {
	void arc078b()
	{
		cin >> N;
		vector<edge> es((N - 1) * 2);
		REP(i, N-1) {
			int a, b; cin >> a >> b;
			a--; b--;
			es[i].from = a; es[i].to = b; es[i].cost = 1;
			es[N - 1 + i].from = b; es[N - 1 + i].to = a;
			es[N - 1 + i].cost = 1;
		}
		vector<ll> ds(N);

		bellmanFord(es, ds, 0);
		REP(i, N) {
			cout << ds[i] << endl;
		}
		cout << ds[N - 1] << endl;
	}
}

