const int N = 2e5+23;
int a[N];

void solve() {
  int n; scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%d", a+i);
  }
  if (a[n-1] != 2) {
    printf("-1");
    return;
  }
  long long cur = 2;
  for (int i = n-2; i >= 0; --i) {
    if (a[i]-a[i+1] > a[i+1]-1) {
      printf("-1");
      return;
    }
    if (a[i] >= a[i+1]) {
      cur += cur%a[i];
    } else {
      cur += a[i]-cur%a[i];
    }
  }
  printf("%lld %lld", cur, cur+a[0]-1);
}

int main() {
