void solve(long long K, std::vector<long long> A){
    // min
    ll ans_min = 2;
    for(ll i = K - 1; i >= 0; --i){
        if(ans_min % A.at(i) != 0){
            cout << -1 << endl;
            return;
        }
        if(i > 0 && ans_min % A.at(i - 1) != 0){
            ll diff = A.at(i - 1) - (ans_min % A.at(i - 1));
            if(diff >= A.at(i)){
                cout << -1 << endl;
                return;
            }else{
                ans_min += diff;
            }
        }
    }

    // max
    ll ans_max = 2;
    for(ll i = K - 1; i >= 0; --i){
        if(ans_max % A.at(i) != 0){
            cout << -1 << endl;
            return;
        }
        ll nxt_max = ans_max + A.at(i) - 1;
        if(i > 0){
            nxt_max -= nxt_max % A.at(i - 1);
            if(nxt_max < ans_max){
                cout << -1 << endl;
                return;
            }
        }
        ans_max = nxt_max;
    }

    cout << ans_min << ' ' << ans_max << endl;
}

