	ll k;
	cin >> k;
	vll a(k);
	REP(i, k) cin >> a[i];

	ll mi = search_min(a);
	ll ma = search_max(a);

	if(mi > ma){
		cout << -1 << endl;
		return 0;
	}

	cout << mi << " " << ma << endl;
    return 0;
}

