	{
		if (x < 0) putchar('-'), x = -x;

		char num[20]; int len = 0;
		while (x > 9) { num[++len] = char(x % 10 + '0'); x /= 10; }

		num[++len] = char(x + '0');

		while (len) putchar(num[len--]);
	}
