void solve(ostringstream& aout, long long K, std::vector<long long> A){
	int bimax = 2;

	// 最大値
	vector<int> B;

	RREP(i, K) {
		B.push_back(bimax);
		if (A[i] > bimax) {
			cout << -1 << "\n";
			return;
		}

		bimax = intfloor(bimax, A[i]) * A[i] + (A[i] - 1);
	}
	B.push_back(bimax);
	reverse(ALLOF(B));

	int ok = B[0];

	auto isOk = [&](int num) -> bool{
		int cal = num;

		rep(i, K) {
			cal -= cal % A[i];
		}
		if (cal == 2) {
			return true;
		}
		else {
			return false;
		}
	};

	int mini = binary_search(isOk, 1, ok);

	cout << mini << " " << ok << "\n";
}

