  for (int i = 1; i < k; ++i) {
    long long nl = inf, nr = -1;
    if (a[i] <= l) {
      long long m = (a[i] - l % a[i]) % a[i];
      if (l + m < l + a[i - 1]) {
        nl = min(nl, l + m);
        nr = max(nr, l + m);
      }
      m = (l + a[i - 1] - 1) % a[i];
      if (l + a[i - 1] - 1 - m >= l) {
        nl = min(nl, l + a[i - 1] - 1 - m);
        nr = max(nr, l + a[i - 1] - 1 - m);
      }
    } else if (l + a[i - 1] > a[i]) {
      nl = min(nl, a[i]);
      nr = max(nr, a[i]);
    }
    if (a[i] <= r) {
      long long m = (a[i] - r % a[i]) % a[i];
      if (r + m < r + a[i - 1]) {
        nl = min(nl, r + m);
        nr = max(nr, r + m);
      }
      m = (r + a[i - 1] - 1) % a[i];
      if (r + a[i - 1] - 1 - m >= r) {
        nl = min(nl, r + a[i - 1] - 1 - m);
        nr = max(nr, r + a[i - 1] - 1 - m);
      }
    } else if (r + a[i - 1] > a[i]) {
