const int Mod = 1e9 + 7;

ll bpow(ll x, ll y){
    if (y == 0)
        return 1;
    ll ret = bpow(x, y >> 1);
    ret = (ret * ret) % Mod;
    if (y & 1)
        ret = (ret * x) % Mod;
    return ret;
}

ll bdiv(ll x, ll y){
    return (x * bpow(y, Mod - 2)) % Mod;
}

