int main(){
	ll N;
	scll(N);
	ll data[N];
	for (ll i = 0; i < N; ++i){
		scll(data[i]);
	}
	if (data[N-1] != 2) {
		cout << -1 << endl;
	} else {
		ll MIN = 2;
		ll MAX = 3;
		for (ll i = N-2; i >= 0; --i) {
			if (MIN < data[i]) {
				if ((data[i]-MIN)/MIN >= 1) {
					cout << -1 << endl;
					return 0;
				}
			}			
			if (MIN > data[i]) {
				ll MIN_NOW = 0;
				if (MIN % data[i]) {
					ll tmp = MIN/data[i];
					MIN_NOW = data[i]*(tmp+1);
				}
				if (MIN_NOW > 0 && (MIN_NOW-MIN)/data[i+1] >= 1) {
					cout << -1 << endl;
					return 0;
				}
				MIN = max(MIN_NOW,MIN);
			} else {
				MIN = data[i];
			}
			MAX = max(MAX,MIN+data[i]-1);
		}
		cout << MIN << " " << MAX << endl;
	}
	return 0;
}

