int main() {
    std::ios::sync_with_stdio(false);
    LLI K;
    std::cin >> K;

    VI A(K);
    rep(i,K) std::cin >> A[(K-1) - i];

    if(A[0] != 2) {
        std::cout << "-1" << std::endl;
        return 0;
    }

    LLI min = 2, max = 3;
    for( int i = 1 ; i < K ; ++i ) {
        // min を min以上でA[i]の倍数となる最小の値にアップデート
        // max 以下で A[i]の倍数となる最大の値をXとする
        // max を X + A[i] - 1 にアップデート
        if( min % A[i] )
            min = (min/A[i]+1) * A[i];

        LLI X = max;
        if( X % A[i] )
            X = (max/A[i]) * A[i];
        max = X + A[i] - 1;

        if( min > X ) {
            std::cout << "-1" << std::endl;
            return 0;
        }
    }
    std::cout << min << " " << max << std::endl;
    return 0;
}

