int reverse_game_max(int i, const vector<int>& as, int n_i) {
  i-= 1;
  if (n_i % as[i] != 0 || n_i != 0) {
    return -1;
  }
  if (i == 0) {
    int num = n_i + as[0] - 1;
    return num;
  } else {
    for (int j=as[i]-1; j>=0; j--) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_max(i, as, n_i + j);
      }
    }
    return -1;
  }
}

int reverse_game_min(int i, const vector<int>& as, int n_i) {
  i-= 1;
  if (n_i % as[i] != 0 || n_i != 0) {
    return -1;
  }
  if (i == 0) {
    return n_i;
  } else {
    for (int j=0; j<as[i]-1; j++) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_min(i, as, n_i + j);
      }
    }
    return -1;
  }
}

int main() {
  int k;
  cin >> k;
  if (k < 1 || pow(10, 5) < k) {
    cout << "-1";
    return 0;
  }
  vector<int> a(k);
  for (auto & z : a) {
    cin >> z;
  }
  for (auto & z : a) {
    if (z < 2 || pow(10, 9) < z || k < z) {
      cout << "-1";
      return 0;
    }
  }

  int mini = reverse_game_min(k, a, 2);
  auto maxi = reverse_game_max(k, a, 2);
  if (mini < 0 || maxi < 0)
    cout << "-1";
  else
    cout << reverse_game_min(k, a, 2) << " " << reverse_game_max(k, a, 2);

  return 0;
}

