int left = 2, right = 2;

for (int i = n - 1; i >= 0; --i) {
 int size = a[i];
 int nearestLeft = left + (size - left % size) % size;
 int nearestRight = right - right % size;

 if (nearestLeft > nearestRight) {
  left = -1;
  right = -1;
  break;
 }

 left = nearestLeft;
 right = nearestRight + size - 1;
}

return make_pair(left, right);
}

