struct Range {
  int l, r;
  Range() {}
  Range(int l, int r): l(l), r(r) {}
};

int main() {
  int k;
  cin >> k;
  vector<int> la(k);
  for (int &a: la) { cin >> a; }
  Range range = Range(2, 2);
  for (int i = k-1; i >= 0; --i) {
    int nl = ((range.l-1)/la[i]+1)*la[i];
    int nr = (range.r/la[i])*la[i]+la[i]-1;
    // cerr << nl << " " << nr << endl;
    if (nl > range.r || nr < range.l) {
      cout << -1 << endl;
      return 0;
    }
    assert(nl < nr);
    range = Range(nl, nr);
  }
  cout << range.l << " " << range.r << endl;
}

