long long check(long long n, vector<int> &v) {
  for (auto &x : v) {
    n = x * (n / x);
  }

  return n;
}

long long get_min(vector<int> &v) {
  long long lo = 0, hi = inf;
  while (hi - lo > 1) {
    long long x = (lo + hi) / 2;
    long long target = check(x, v);

    if (target >= 2) {
      hi = x;
    } else {
      lo = x;
    }
  }

  return hi;
}

long long get_max(long long n, vector<int> &v) {
  long long lo = n, hi = inf;
  while (hi - lo > 1) {
    long long x = (lo + hi) / 2;
    long long target = check(x, v);

    if (target == 2) {
      lo = x;
    } else {
      hi = x;
    }
  }

  return lo;
}

