bool solve(ll a, t2 &range)
{
    ll rmin = get<0>(range);
    ll rmax = get<1>(range);

    if ((rmin % a) && (rmax % a) && (rmin / a == rmax / a)) {
        return false;
    }

    ll next_rmin = ((rmin % a) ? ((rmin / a + 1LL) * a) : rmin);
    ll next_rmax = ((rmax % a) ? ((rmax / a) * a) : rmax) + (a - 1LL);
    if (next_rmin > next_rmax) {
        return false;
    }

    range = t2(next_rmin, next_rmax);
    return true;
}

