  while (ub-lb > 1) {
    intmax_t mid=(lb+ub)>>1;
    //fprintf(stderr, "[%jd, %jd]\n", lb, ub);
    (valid(A, mid)? ub:lb) = mid;
  }

  intmax_t min=ub;
  if (min > max)
    return !printf("-1\n");

