long long lower (long long a, long long b, long long c, long long d) {
	long long l = 1, r = 1.5E9, ans = -1;
	while (l <= r) {
		long long m = (l + r) / 2;
		if (a * m / b < c) {
			l = m + 1;
		} else {
			if (c <= a * m / b && a * m / b <= d) ans = m;
			r = m - 1;
		}
	}
	return ans;
}

long long upper (long long a, long long b, long long c, long long d) {
	long long l = 1, r = 1.5E9, ans = -1;
	while (l <= r) {
		long long m = (l + r) / 2;
		if (a * m / b <= d) {
			if (c <= a * m / b && a * m / b <= d) ans = m;
			l = m + 1;
		} else {
			r = m - 1;
		}
	}
	return ans;
}

