bool game(vector<int> A) {
	if (A.back() != 2) return false;
	long long a = 2;
	long long b = 2;
	for (int i = A.size() - 1; i >= 0; i --) {
		int g = A[i];
		long long x = (a + g - 1) / g;
		long long y = b / g;
		if (x > y) return false;
		a = x * g;
		b = y * g + g - 1;
	}
	cout << a << " " << b << "\n";
	return true;
}

int main() {
	ios_base::sync_with_stdio(false);
	int k;
	cin >> k;
	vector<int> A;
	for (int i = 0; i < k; i ++) {
		int a;
		cin >> a;
		A.push_back(a);
	}
	if (not (game(A))) {
		cout << "-1\n";
	}
}

