        }

        if (num == 2)
        {
            l = mid;
        }
        else if (num > 2)
        {
            r = mid - 1;
        }
        else
        {
            l = mid + 1;
        }
    }

    ma = l;

    if (ma < mi)
        cout << -1 << endl;
    else
        cout << mi << " " << ma << endl;
