signed main()
{
  cin >> N;
  for(int i = 0; i < N; i++) {
    cin >> A[i];
  }

  if(A[N-1] != 2) {
    cout << -1 << endl;
    return 0;
  }

  LL minAns = 2;
  LL X = 1;
  for(int i = N-1; 0 <= i; i--) {
    LL l = 0, r = 1014514191981036436;
    while(r-l>1) {
      LL mid = (l+r)/2;
      if((mid/A[i])*A[i] >= minAns) {
        r = mid;
      } else {
        l = mid;
      }
    }
    LL tmp = (r / A[i]) * A[i];
    if(!(minAns <= tmp && tmp <= minAns + X - 1)) {
      cout << -1 << endl;
      return 0;
    }
    minAns = r;
    X = A[i];
  }

  LL maxAns = 2;
  X = 1;
  for(int i = N-1; 0 <= i; i--) {
    LL l = 0, r = 1014514191981036436;
    while(r-l>1) {
      LL mid = (r+l)/2;
      if((mid/A[i])*A[i] <= maxAns + X - 1) {
        l = mid;
      } else {
        r = mid;
      }
    }

    if(i != 0) {
      l = (l/A[i])*A[i];
    }

    LL tmp = l/A[i]*A[i];
    if(!(maxAns <= tmp && tmp <= maxAns + X-1)) {
      cout << -1 << endl;
      return 0;
    }

    maxAns = l;
    X = A[i];
  }

  cout << minAns << " " << maxAns << endl;

  return 0;
}

