int main() {

	cin.tie(nullptr);
	ios::sync_with_stdio(false);

	int K;
	cin >> K;
	vector<int> A(K);
	for (int i = 0; i < K; i++) cin >> A[i];


	auto judge1 = [&](auto x) {
		auto res = x;
		for (int i = 0; i < K; i++) {
			x -= x % A[i];
		}
		return x >= 2;
	};

	auto judge2 = [&](auto x) {
		auto res = x;
		for (int i = 0; i < K; i++) {
			x -= x % A[i];
		}
		return x == 2;
	};

	auto binary_search = [&](auto f, auto min, auto max) {

		auto ng = min;
		auto ok = max;

		while (abs(ok - ng) > 1) {
			auto mid = (ok + ng) / 2;

			if (f(mid)) ok = mid;
			else ng = mid;
		}

		return ok;
	};

	auto mid = binary_search(judge1, 0LL, LINF);
	if (!judge2(mid)) {
		cout << -1 << "\n";
		return 0;
	}

	cout << binary_search(judge2, 0LL, mid) << endl;
	cout << binary_search(judge2, LINF, mid) << endl;

	return 0;
}

