void solve(long long int num,long long int box) {
	if (num == 1) {
		for (int i = 0; i < A[num]; i++) {
			smallest = min(smallest, box + i);
			largest = max(largest, box + i);
		}
	}
	else {
		long long int buf;
		if (box < A[num - 1]) {
			buf = A[num - 1] - box;
		}
		else {
			buf = (A[num - 1] - (box - A[num - 1]) % A[num - 1]) % A[num - 1];
		}
		for (int i = 0; buf + i*A[num - 1] < A[num]; i++)solve(num - 1, box + buf + i*A[num - 1]);
	}
}

