int K;
vector<int>A(100001);
bool more2(int p){
    int ret;
    ret=p;

    for(int i=0; i<K; i++){
        ret=(ret/A[i])*A[i];
    }
    return (ret>=2);
}

bool less2(int p){
    int ret;
    ret=p;

    for(int i=0; i<K; i++){
        ret=(ret/A[i])*A[i];
    }
    return (ret<=2);
}
int main() {
    cin >>K;

    rep(i,K){
        cin >> A[i];
    }

    int u=1000000000,b=-1,m;

    int minimum=0;
    while(u>b+1){
        m=(u+b)/2;
        if(more2(m)){
            u=m;
        }else{
            b=m;
        }
    }
    minimum=u;


    u=1000000000,b=-1;
    int maximum=0;
    while(u>b+1){
        m=(u+b)/2;
        if(less2(m)){
            b=m;
        }else{
            u=m;
        }
    }
    maximum=b;

    if(maximum<minimum){
        cout << -1 << endl;
    }else{
        cout << minimum << " " <<maximum << endl;
    }
    return 0;
}

