pair<ll, ll> nil = make_pair(-1, -1);

pair<ll, ll> get(ll cur, int modNow, int modPre) {
    ll low = cur, high = cur + modNow - 1;
    ll t = high / modPre;
    if (modPre * t < low) return nil;

    return make_pair(((low + modPre - 1) / modPre) * modPre, (high / modPre) * modPre);
}

void solve() {
    cin >> n;
    rep(i, 1, n + 1) {
        scanf("%d", a + i);
    }

    if (a[n] != 2) {
        puts("-1");
        return;
    }
    ll curLow = 2, curHigh = 2;
    for (int i = n; i > 1; --i) {
        // a[i] -> 2 * a[i] - 1
        auto low = get(curLow, a[i], a[i - 1]);
        auto high = get(curHigh, a[i], a[i - 1]);

        if (low == nil && high == nil) {
            puts("-1");
            return;
        } else if (low == nil) {
            curLow = high.first;
            curHigh = high.second;
        } else if (high == nil) {
            curLow = low.first;
            curHigh = low.second;
        } else {
            curLow = min(low.first, high.first);
            curHigh = max(low.second, high.second);
        }
    }

    cout << curLow << ' ' << curHigh + a[1] - 1 << '\n';

}

