using namespace std;
typedef long long ll;

int K, A[100001];

int nmax() {
    int n = 2;
    for (int i = K - 1; i >= 0; i --) {
        n = n + A[i] - 1;
    }
    return n;
}

bool ok(int N) {
    int n = N;
    for (int i = 0; i < K; i ++) {
        n = n / A[i] * A[i];
    }
    return n == 2;
}

int find_min() {
    int n = 2;
    for (int i = K - 1; i >= 0; i --) {
        int a = i > 0 ? A[i - 1] : 1;
        int q = n / a + (n % a ? 1 : 0);
        int nn = a * q;
        int r = nn - n;
        if (r >= A[i]) return -1;
        n = nn;
    }
    return n;
}

int find_max() {
    int n = 2;
    for (int i = K - 1; i >= 0; i --) {
        int a = i > 0 ? A[i - 1] : 1;
        int q = (A[i] + n - 1) / a;
        int nn = a * q;
        int r = nn - n;
        if (r < 0) return -1;
        n = nn;
    }
    return n;
}

// [h, t)
int bsearch(int h, int t) {
    if (t - h <= 1) return h;
    int mid = (h + t) / 2;
    if (ok(mid)) {
        return bsearch(mid, t);
    } else {
        return bsearch(h, mid);
    }
}

signed main() {
    cin >> K;
    for (int i = 0; i < K; i ++) {
        cin >> A[i];
    }
    int m = find_min();
    if (m == -1) {
        cout << -1 << endl;
    } else {
        int M = bsearch(m, nmax() + 1);
        cout << m << " " << M << endl;
    }
    return 0;
}

