ll rem (ll start) {
    for (int item : arr) {
        start = start / item * 1LL* item;
    }
    return start;
}

ll find(int end) {
    ll lo = 0;
    ll hi = 1e15;
    while (lo < hi) { 
        ll mid = lo + (hi - lo + 1) / 2;
        if (rem(mid) <= end)
            lo = mid;
        else
            hi = mid - 1;
    }
    return lo;
}
