using int64 = long long;
using Graph = std::vector<std::vector<int>>;

int64 simulate(int64 x, vector<int64>& A) {
    int K = A.size();
    x = A[0] * x;
    for (int i = 0; i < K; i++) {
        x = (x / A[i]) * A[i];
    }
    return x;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int K;
    cin >> K;

    vector<int64> A(K);
    repeat (i, K) {
        cin >> A[i];
    }
    if (A.back() != 2) {
        cout << -1 << endl;
        return 0;
    }
    /*
    int idx = K - 1;
    while (idx > 0 and A[idx - 1] == 2) idx--;
    */

    int64 ng = 0, ok = 2e9;
    while (ok - ng > 1) {
        int64 mid = (ng + ok) / 2;
        if (simulate(mid, A) >= 2) ok = mid;
        else ng = mid;
    }

    if (simulate(ok, A) != 2) {
        cout << -1 << endl;
        return 0;
    }

    int64 lb = ok, ub = ok;
    ok = 0; ng = 2e9;
    while (ng - ok > 1) {
        int64 mid = (ng + ok) / 2;
        if (simulate(mid, A) <= 2) ok = mid;
        else ng = mid;
    }

    if (simulate(ok, A) == 2) {
        lb = ok;
    }

    cout << lb * A[0] << " " << ub * A[0] + (A[0] - 1) << endl;

    return 0;
}

