int main(){
	int K;
	long long A[100000];

	scanf("%d",&K);
	int m = 0;
	for(int i=0;i<K;i++){
		scanf("%lld",&A[i]);
		if(A[m] < A[i]){
			m = i;
		}
	}
	//printf("%lld\n",A[m]);
	if(A[K-1]!=2){
		printf("-1\n");
		return 0;
	}else{
		long long n = A[m];
		for(int i=m;i<K;i++){
			n -= (n%A[i]);
		}
		if(n!=2){
			printf("-1\n");
			return 0;
		}else{
			int m2 = 0;
			for(int i=0;i<m;i++){
				if(A[m2]<A[i]) m2 = i;
			}
			n = A[m];
			long long min = n;
			long long max = A[m2]*3-1;
			if(m2==0) max = n*2;
			for(int i=0;i<m;i++){
				long long tmp = n;
				if(tmp%A[i]!=0)tmp += (A[i]-tmp%A[i]);
				if(tmp>min) min = tmp;
			}
			long long tmp2 = max;
			for(int i=0;i<m;i++){
				if(tmp2%A[i]!=0)tmp2 -= tmp2%A[i];
			}
			if(tmp2==max) max = max-1;
			printf("%lld %lld\n", min, max);
		}
	}

	return 0;
}

