void apply(long long &mn, long long &mx, long long x){
    long long rmn;
    if(mn % x == 0) rmn = mn;
    else rmn = mn - mn % x + x;
    long long rmx = mx - mx % x;
    if(rmn > mx && rmx < mn) {
        puts("-1");
        exit(0);
    }
    mn = rmn;
    mx = rmx + x - 1;
}
