    }

    long lb = 2;
    long rb = INT_MAX + 1LL;

    while (rb - lb > 1) {
        long mid = (lb + rb) / 2;
        long remain = mid;
        for (int i = 0; i < k; ++i) {
            remain = remain - remain % a[i];
