    for (int i=0; i<N; i++){ cin >> A[i]; }

    int min = 2, max = 2;
    bool res = 1;
    for (int i=(N-1); i>=0; i--){

	int now = A[i];
	int newmin = min, newmax = max;

	for (int j=0; j<now; j++){
	    if (newmin % now == 0){ min = newmin; break; }
	    newmin++;
	    if (newmin > max){ res = 0; }
	}
	if (!res){ break; }

	for (int j=0; j<now; j++){
	    if (newmax % now == 0){ max = newmax;  break; }
	    newmax--;
	    if (newmax < min){ res = 0; }
	}
	if (!res){ break; }

	max += (now-1);
    }

    if (res){ cout << min << "  " << max << endl; }
    else { cout << -1 << endl; }

    return 0;
}

