long long int lim[100005][2]={0};

long long int bs(long long int ok, long long int ng, function<bool(long long int)> check){
    while(abs(ok - ng) > 1){
        long long int mid = (ok + ng) / 2;
        if(check(mid))ok = mid;
        else ng = mid;
    }
    return ok;
}

int main(){
    int k;
    cin >> k;
    vector<long long int> a;
    for(int i=0;i<k;++i){
        long long int tmp;
        cin >> tmp;
        a.push_back(tmp);
    }
    bool ng = false;
    long long int ub = 2;
    for(int i=a.size()-1;i>=0;--i){
        if(a[i] > ub){
            ng = true;
            break;
        }
        ub = ub * 2 - 1;
    }
    if(ng){
        cout << -1 << endl;
    }else{
        lim[k-1][0] = 2;
        lim[k-1][1] = 3;
        for(int i=k-2;i>=0;--i){
            long long int x = a[i], y = lim[i+1][0], z = lim[i+1][1];
            auto f1 = [x,y](long long int w){return w*x >= y;};
            auto f2 = [x,z](long long int w){return w*x > z;};
            lim[i][0] = a[i] * bs(y, 0, f1);
            lim[i][1] = a[i] * bs(z, 0, f2) - 1;
        }
        if(lim[0][0] > lim[0][1])cout << -1 << endl;
        else cout << lim[0][0] << " " << lim[0][1] << endl;
    }

