bool checkmax(int x){
    for(int i=0;i<n;i++){
        x = x - (x % a[i]);
    }
    return x<=2 ? true : false; 
}
bool checkmin(int x){
    for(int i=0;i<n;i++){
        x = x - (x % a[i]);
    }
    return x>=2 ? true : false; 
}
int binary_search_min(bool func(int),int max,int min){

    int mid;
    while(max!=min){
        mid = (max+min)/2;
        if(func(mid)){
            max = mid;
        }else{
            min = mid+1; 
        }
    }
    return min;
}
int binary_search_max(bool func(int),int max,int min){

    int mid;
    while(max!=min){
        mid = (max+min)/2+1;
        if(func(mid)){
            min = mid;
        }else{
            max = mid-1; 
        }
      //  cout << min <<endl;
    }
    return min;
}

