    int max = binary_search_max(checkmax,ma*n+2,2);
    int min = binary_search_min(checkmin,ma*n+2,2);

    if(max < min) cout << "-1" << endl;
    else{
        cout << min << " " << max << endl;
    }
    return 0;
}

