LL K;
LL A[100001];

LL ans_min = 2,ans_max = 2;

void solve(){
	ans_min = 2;
	for(int i=K;i>=2;i--){
		{
			LL m = ans_min/A[i-1] + (ans_min%A[i-1]!=0);
			if(m*A[i-1]>ans_min+A[i]-1){
				ans_min = -1;
				return;
			}
			ans_min = A[i-1]*m;
		}
		{
			LL m = (ans_max+A[i]-1)/A[i-1];
			if(m*A[i-1]<ans_max/A[i-1] + (ans_max%A[i-1]!=0)){
				ans_min = -1;
				return;
			}
			ans_max = A[i-1]*m;
		}
	}
	ans_max += A[1]-1;
}

int main(){
    cin >> K;
    for(int i=1;i<=K;i++) cin >> A[i];

    solve();

	if(ans_min==-1){
		cout << -1 << endl;
		return 0;
	}
	cout << ans_min << " " << ans_max << endl;
    return 0;
}

