ll get(ll n) {
  for(int i = 0; i < k; i++) {
    n -= n % (a[i]);
  }
  return n;
}

ll bb1(ll b, ll e) {
  if(b == e) return b;
  ll mid = (b + e) / 2ll;
  ll left = get(mid);
  if(left < 2) return bb1(mid + 1ll, e);
  return bb1(b, mid);
}

ll bb2(ll b, ll e) {
  if(b == e) return b;
  ll mid = (b + e + 1ll) / 2ll;
  ll left = get(mid);
  if(left <= 2) return bb2(mid, e);
  return bb2(b, mid - 1ll);
}


