using namespace std;
static const int32_t INF = 0x3F3F3F3F;
typedef int64_t ll;
typedef vector<ll> vll;
struct Solution {
    void solve(std::istream& in, std::ostream& out) {
        ll k, lo = 0, hi = INF, mi, ma;
        in >> k;
        vll a(k);
        for (int i = 0; i < k; i++) {
            in >> a[i];
        }
        hi = INF;
        lo = 0;
        for (int j = 0; j < 128; j++) {
            mi = (hi + lo) / 2;
            ll tmp = mi;
            for (int i = 0; i < k; i++) {
                ll remain = tmp % a[i];
                tmp -= remain;
            }
            if (tmp >= 2) {
                hi = mi;
            }
            else {
                lo = mi + 1;
            }
        }
        hi = INF;
        lo = 0;
        for (int j = 0; j < 128; j++) {
            ma = (hi + lo) / 2;
            ll tmp = ma;
            for (int i = 0; i < k; i++) {
                ll remain = tmp % a[i];
                tmp -= remain;
            }
            if (tmp > 2) {
                hi = ma;
            }
            else {
                lo = ma + 1;
            }
        }
        if (mi < ma) {
            out << mi << ' ' << ma - 1 << '\n';
        }
        else {
            out << -1 << '\n';
        }
    }
};
void solve(std::istream& in, std::ostream& out) {
    out << std::setprecision(12);
    Solution solution;
    solution.solve(in, out);
}
