void solve(){
  p max_min = res(0,2);
  if(max_min.first==-1 || max_min.second==INF){
    cout << -1<<endl;
  }
  else{
  cout << max_min.second << ' ';
  cout << max_min.first << endl;
  }
}

p res(int m,ll num){
  if(num%(a.at(m))!=0 || num< a.at(m)){
    return p(-1,-1);
  }
  if(m==k-1){
    return p(num+a.at(m)-1,num);
  }
  else{
    ll ninzu_max=0;
    ll ninzu_min=INF;
    for(int i=0;i<a.at(m);i++){
      ll num_n = num + i;
      p req = res(m+1,num_n);
      if(req.first!=-1){
        if(req.first > ninzu_max){
          ninzu_max=req.first;
        }
        if(req.second < ninzu_min){
          ninzu_min=req.second;
        }
      }
    }
    p ans(ninzu_max,ninzu_min);
    return ans;
  }
}

