void max_(long long int m, int sum)
{
	//cout << m << " : " << sum << endl;

	if (m == 0)sum = K;

	if (sum == K) {
		if (max_a - i - min_ans > m && m != 0) {
			return;
		}
		if (max_ans < ma && m == 2) {
			max_ans = ma;
			return;
		}
		ma--;
		max_(ma, 0);
		return;
	}

	max_(m - m%A[sum], sum + 1);
}

void min_(long long int m, int sum)
{
	//cout << m << " : " << sum << endl;

	if (m == 0)sum = K;

	if (sum == K) {
		if (max_a < m) {
			min_ans = 0;
			return;
		}
		if (min_ans > mi && m == 2) {
			min_ans = mi;
			return;
		}
		mi++;
		min_(mi, 0);
		return;
	}

	min_(m - m%A[sum], sum + 1);
}

int max_m(long long int m, int sum)
{
	if (sum == K) {
		if (max_a < m) {
			return 0;
		}
		return 1;
	}
	max_m(m - m%A[sum], sum + 1);
}

