	vector<ll> A(K);
	rep(i,K) {
		cin >> A.at(i);
		mA = max(mA, A.at(i));
	}

	l=1, r=mA*K;
	while(r-l > 1) {
		ll m=(l+r)/2, t=m;
		rep(i,K) {
			t = t-t%A.at(i);
