int main() {
    int K;
    cin >> K;
    vector<int> A(K);
    for(int i=0; i<K; ++i) cin >> A[i];

    if(A[K - 1] > 2) {
        cout << -1 << endl;
        return 0;
    }

    int l = 2, r = 2 + A[K - 1] - 1;
    for(int i = K - 2; i>=0; --i) {
        int s = (l % A[i] == 0 ? (l / A[i]) : (l / A[i] + 1));
        int t = r / A[i];
        if(s > t) {
            cout << -1 << endl;
            return 0;
        } else {
            l = s * A[i];
            r = t * A[i] + A[i] - 1;
        }
    }

    cout << l << ' ' << r << endl;
}

