bool dfs_max(int t, ll res){
    if(t == 0) {
        maxV = max(res + a[t]-1, maxV);
        return true;
    }
    for(ll i = (res+a[t]-1)/a[t-1]*a[t-1]; i >= ((res-1)/a[t-1]+1)*a[t-1]; i-=a[t-1]){
        if(dfs_max(t-1, i)) return true;
        //cout << "v:" << i << endl;
    }
    return false;
}

bool dfs_min(int t, ll res){
    if(t == 0) {
        minV = min(res, minV);
        return true;
    }
    for(ll i = ((res-1)/a[t-1]+1)*a[t-1]; i <= (res+a[t]-1)/a[t-1]*a[t-1]; i+=a[t-1]){
        if(dfs_min(t-1, i)) return true;
        //cout << "v:" << i << endl;
    }
    return false;
}

