int main() {
	int n;
	scanf("%d", &n);
	for (int i = 1; i <= n; i++) {
		scanf("%lld", &a[i]);
	}
	if (a[n] != 2) {
		puts("-1");
		return 0;
	}
	ll ans1 = 2;
	bool flag = false;
	for (int i = n; i > 1; i--) {
		ll down = ans1, up = 2 * ans1;
		if (a[i - 1] >= up) {
			flag = true;
			break;
		}
		ans1 = (down - 1) / a[i - 1] * a[i - 1] + a[i - 1];
	}
	if (flag) {
		puts("-1");
		return 0;
	}
	printf("%lld ", ans1);
	ans1 = 2;
	for (int i = n; i > 1; i--) {
		ll down = ans1, up = 2 * ans1;
		if (a[i - 1] >= up) {
			flag = true;
			break;
		}
		ans1 = (up - 1) / a[i - 1] * a[i - 1];
	}
	ans1 += a[1] - 1;
	printf("%lld\n", ans1);
	return 0;
