int main() {
  ll k;
  Read(k);
  vector<ll> a(k);
  int maxi = 0;
  for (int i = 0; i < k; i++) {
    Read(a[i]);
    if (a[i] > a[maxi]) {
      maxi = i;
    }
  }

  ll lcm = 1;
  for (int i = 0; i < maxi; i++) {
    ll t = gcd(lcm, a[i]);
    lcm = (a[i] / t) * lcm;
  }

  ll u = ceil(a[maxi] / (double)lcm);
  ll x = lcm * u;

  ll y = x;
  for (int i = 0; i < k; i++) {
    if (y < a[i]) {
      y = 0;
    } else {
      y = y - (y % a[i]);
    }
  }

  if (y != 2) {
    Print(-1);
    return 0;
  } 

  ll max_ = x;
  for (ll m = x + a[maxi] - 1; m > x; m--) {
    ll w = m;
    for (int i = 0; i < k; i++) {
      if (w < a[i]) {
        w = 0;
      } else {
        w = w - (w % a[i]);
      }
    }
    if (w == 2) {
      max_ = m;
      break;
    }
  }
  Print(x, max_);

  return 0;
}


