}

void solve(int K, vi& a) {
    ll lo = 2, hi = 2;
    for (int i=K-1; i>=0; --i) {
        ll mod = a[i];
        // [lo, hi]
        if (hi < mod) goto impossible;
        ll nlo = lo - (lo % mod);
        if (nlo < lo) nlo += mod;
        if (nlo > hi) goto impossible;

        ll nhi = hi - (hi % mod);
        if (nhi < lo) goto impossible;

        lo = nlo; hi = nhi + (mod-1);
    }
    cout << lo << " " << hi << endl;
    return;
impossible:
    cout << -1 << endl;
}

int main() {
    vi a;
    int K = loadvec(a);
    solve(K,a);
    return 0;
}

