bool judge(ll n){
  for(int i=0;i<k;i++){
    n=n-(n%tourist[i]);
  }
  if(n==2) return true;
  else return false;
}
int main(){
  cin>>k;
  for(int i=0;i<k;i++) cin>>tourist[i];
  ll mi=2;
  //cout<<-1<<endl;
  //return 0;
  for(int i=k-1;i>0;i--){
    ll sr=tourist[i-1];
    ll ks=0;
    if(sr>mi) ks=sr-mi;
    if(sr<mi){
      ks=sr-(mi%sr);
      if(ks==sr) ks=0;
    }
    if(ks>=tourist[i]){
      cout<<-1<<endl;
      return 0;
    }
    mi+=ks;
  }
  if(judge(mi)) cout<<mi<<" ";
  else{
    cout<<-1<<endl;
    return 0;
  }
  ll lb=mi-1,rb=1e18;
  while(rb-lb>1){
    ll mid=(lb+rb)/2;
    if(judge(mid)) lb=mid;
    else rb=mid;
  }
  cout<<lb<<endl;
}

