int *A;
std::map<int, std::set<int> > invalid_memo;

long findMinCandidates(int index, long Ni) {
    if (index < 0) {
        return Ni;
    }
    if (Ni % A[index] != 0) {
        return -1;
    }
    if (invalid_memo.find(index+1) != invalid_memo.end()
     && invalid_memo[index+1].find(Ni) != invalid_memo[index+1].end()) {
        return -1;
    }

    for (int i = Ni; i < Ni+A[index]; i++) {
        long res = findMinCandidates(index-1, i);
        if (res >= 0) {
            return res;
        }
        else {
            invalid_memo[index].insert(i);
        }
    }

    return -1;
}

long findMaxCandidates(int index, long Ni) {
    if (index < 0) {
        return Ni;
    }
    if (Ni % A[index] != 0) {
        return -1;
    }
    if (invalid_memo.find(index+1) != invalid_memo.end()
     && invalid_memo[index+1].find(Ni) != invalid_memo[index+1].end()) {
        return -1;
    }

    for (int i = Ni+A[index]-1; i >= Ni; i--) {
        long res = findMaxCandidates(index-1, i);
        if (res >= 0) {
            return res;
        }
        else {
            invalid_memo[index].insert(i);
        }
    }

    return -1;
}

