//check : 条件を満たすか確認するやつ
bool check(ll x, vll &a, ll type){
	for(auto q : a){
		x -= x % q;
	}
	if(type == 1){
		if(x >= 2) return true;
		else return false;
	}
	else{
		if(x <= 2) return true;
		else return false;
	}
}

//1つめ : g(n) >= 2 となる最小の n を二分探索
ll search_min(vll &a){
	ll ng = 0;
	ll ok = 1e10;

    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        if (check(mid, a, 1)) ok = mid;
        else ng = mid;
    }
    return ok;
}

//2つめ : g(n) <= 2 となる最大の n を二分探索
ll search_max(vll &a){
	ll ng = 1e10;
	ll ok = 0;

    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        if (check(mid, a, 2)) ok = mid;
        else ng = mid;
    }
    return ok;
}

