pair<ll, ll> get_answer(int n, vector<int> & a) {
ll left = 2, right = 2;

for (int i = n - 1; i >= 0; --i) {
 int size = a[i];
 ll nearestLeft = left + (size - left % size) % size;
 ll nearestRight = right - right % size;

 if (nearestLeft > nearestRight) {
  left = -1;
  right = -1;
  break;
 }

 left = nearestLeft;
 right = nearestRight + size - 1;
}

return make_pair(left, right);
}

