#define For(i, l, r) for(register int i = (l); i <= (r); ++ i)
#define Fordown(i, r, l) for(register int i = (r); i >= (l); -- i)
using namespace std;

const int N = 100100;
long long a[N];
int n;

int main() {
	cin >> n;
	For (i, 1, n)
		scanf ("%lld", &a[i]);
	if (a[n] != 2) return printf ("-1"), 0;

	long long min_ans = 2, max_ans = 2;
	Fordown (i, n, 2) {
		long long res;
		res = a[i - 1] - min_ans % a[i - 1];
		if (res == a[i - 1]) res = 0;
		if (res >= a[i]) return printf ("-1"), 0;
		min_ans += res;

		res = a[i - 1] - max_ans % a[i - 1];
		if (res == a[i - 1]) res = 0;
		if (res >= a[i]) return printf ("-1"), 0;
		while (res < a[i] - a[i - 1]) res += a[i - 1];
		max_ans += res;
	}
	cout << min_ans << ' ' << max_ans + (long long)(a[1] - 1) << endl;
	return 0;
}

