int main(){
    int K;
    cin >> K;
    long team_member[K];
    for(int i = 0; i < K; i++){
        cin >> team_member[i];
    }
    if(team_member[K - 1] != 2){
        cout << -1 << endl;
        return 0;
    }
    long back_member_min = 2;
    long back_member_max = 2;
    for(int i = K - 2; i >= 0; i--){
        long now_member_min = back_member_min;
        back_member_min = team_member[i] * ((now_member_min + team_member[i] - 1) / team_member[i]);
        back_member_max = team_member[i] * ((team_member[i + 1] + now_member_min - 1) / team_member[i]);
        if(back_member_min > back_member_max){
            cout << -1 << endl;
            return 0;
        }
    }
    cout << back_member_min << " " << back_member_max + team_member[0] - 1 << endl;
}

