long long numGroups(long long A, long long B, long long k, bool upper)
{
    long long ans = 0;
    for (long long jump = A * k / B + 1; jump > 0; jump /= 2)
    {
        if (upper)
            while ((ans + jump) * B / A <= k)
                ans += jump;
        else
            while ((ans + jump) * B / A < k)
                ans += jump;
    }
    if (!upper)
        ans++;
    if (ans * B / A == k)
        return ans;
    return 0;
}

