int getmn()
{
    ll now=2;
    for(int i=n-1;i>=1;i--)
    {
        if(a[i]==a[i+1]) continue;
        ll ans=now/a[i]*a[i];
        if(ans<now) ans+=a[i];
        if(ans-ans%a[i+1]!=now)
        {
            printf("-1\n");exit(0);
        }
        now=ans;
    }
    return now;
}
int getmx()
{
    ll now=3;
    for(int i=n-1;i>=1;i--)
    {
        if(a[i]==a[i+1]) continue;
        ll ans=now/a[i]*a[i];
        ans+=a[i]-1;
        now=ans;
    }
    return now;
}
