const int N = 100005;
lint a[N];

bool go(lint &tl, lint &th, lint x) {
	lint a, b;
	b = th-(th%x);
	if(tl%x==0) {
		a = tl;
	}
	else {
		a = tl+x;
		a = a-(a%x);
	}
	if(tl>th)return false;
	tl = a;
	th = b+(x-1);
	assert(th<1e18);
	return true;
}

int main() {
