	}
	for(int i=0; i<k; i++) {
		lint x;
		x = a[k-1-i];
		if(!go(tl, th, x)) {
			ok = false;
			break;
		}
	}
	if(!ok) {
		printf("%lld", -1LL);
	}
	else {
		printf("%lld %lld\n", tl, th);
	}
	return 0;
}

