LL BS1( ) {
    LL lo = 1 , hi = inf;
    LL ret = -1;
    while( lo <= hi ) {
        LL mid = (lo+hi)/2;
        //cout << "MID " << mid <<endl;
        if( can(mid) >= 2 ) {
            //cout << "here " <<endl;
            ret = mid;
            hi = mid-1;
        }
        else lo = mid+1;
    }
    return ret;
}
