    n=g*A[i];
  }
  return n>=2;
}
bool ok2(LL N) {
  LL n=N;
  REP(i,K) {
    LL g=n/A[i];
    n=g*A[i];
  }
  return n<=2;
}

void solve() {
  LL good=2e18,bad=0;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2;
    bool res=ok1(mid);
    (res?good:bad)=mid;
  }
  LL lb=good;

  good=1,bad=2e18;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2;
    bool res=ok2(mid);
    (res?good:bad)=mid;
  }
  LL hb=good;
