const LL Inf=1e18;

LL high(LL T, LL A) {
  LL good=-1,bad=Inf;
  while(abs(good-bad)>1) {
    if(A==512337211) dump2(good,bad);
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx<=T?good:bad)=mid;
  }
  return good;
}

LL low(LL T, LL A) {
  LL good=Inf,bad=-1;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx>=T?good:bad)=mid;
  }
  return good;
}

