vector<LL> solve(int N, vector<LL> A) {
  if(A.back()!=2) return {};

  LL l=2,r=2;
  for(int i=N-1; i>=0; --i) {
    l=low(l,A[i]);
    r=high(r,A[i]);
    dump4(i,A[i],l,r);
    if(l>r) return {};
//    if(l<=-1||l>Inf) return {};
//    if(h<=-1||h>Inf) return {};
  }
  return {l,r};
}

vector<LL> solve_linear(int N, vector<LL> A) {
  if(A.back()!=2) return {};

  LL l=2,r=2;
  for(int i=N-1; i>=0; --i) {
    LL a=A[i];
    LL k1=(l+a-1)/a,k2=r/a;
    //    if(k1==0&&k2==0) return {};
    l=a*k1;
    r=a*(k2+1)-1;
    //    dump4(i,A[i],l,r);
    if(l>r) return {};
    //    if(l>h) return {};
    //    if(l<=-1||l>Inf) return {};
    //    if(h<=-1||h>Inf) return {};
  }
  return {l,r};
}

