int K, A[MAX_K];

ipair solve() {
    ipair res = make_pair(2, 2);
    for(int i = K - 1; i >= 0; --i) {
        //cout << res.first << ", " << res.second << endl;
        /*
            区間[res.first, res.second)でA[i]で割り切れるものをx_1, ..., x_kとする
            k = 0のとき，条件を満たすNは存在しない．
            k > 0のとき，resを[x_0, x_k + A[i])で更新する．

            (ここではresを閉区間で実装しているので，resを[x_0, x_k + A[i] - 1]で更新している．)
        */

        int x_1 = (res.first + A[i] - 1) / A[i] * A[i];
        int x_k = res.second / A[i] * A[i];

        if(x_1 > x_k)
            return make_pair(-1, -1);
        else
            res = make_pair(x_1, x_k + A[i] - 1);
    }
    return res;
}

