int C(const vec<int>& A, int n)
{
   rep(i, 0, SZ(A)) {
      n -= n % A[i];
   }
   return n;
}

int lower(const vec<int>& A)
{
   int l = 0, r = INF;
   int m;
   while (r - l > 1) {
      m = (l + r) / 2;
      if (C(A, m) >= 2) {
         r = m;
      } else {
         l = m;
      }
   }
   return r;
}
int upper(const vec<int>& A)
{
   int l = 0, r = INF;
   int m;
   while (r - l > 1) {
      m = (l + r) / 2;
      if (C(A, m) > 2) {
         r = m;
      } else {
         l = m;
      }
   }
   return l;
}

signed main()
{
   int K; cin >> K;
   vec<int> A(K);
   rep(i, 0, K) {
      cin >> A[i];
   }

   int L = lower(A);
   int U = upper(A);

   if (L < U) {
      printf("%lld %lld\n", L, U);
   } else {
      printf("%d\n", -1);
   }

   return 0;
}

