int main(){
    int k; cin >> k;
    vector<ll> a(k);
    rep(i,k) cin >> a[i];
    vector<pair<ll, ll>> res(k);

    // mを超えない，xで割るとr余る最大の数
    auto remaind = [](ll m, ll x, ll r){
        ll temp = (m / x)*x + r;
        if(m < temp)temp -= x;
        // print("remaind");
        // print(m,x,r,temp);
        assert(m >= temp);
        return temp;
    };

    // mを超える，xで割るとr余る最大の数
    auto over = [](ll m, ll x, ll r){
        ll temp = (m / x)*x + r;
        if(m > temp)temp += x;
        // print("over");
        // print(m,x,r,temp);
        assert(m <= temp);
        return temp;
    };
    bool ok = true;
    if(a[k-1] == 2){
        res[k-1] = Pll(2,3);
    }else{
        ok = false;
    }
    for(int i = k-2; 0 <= i; --i){
        ll mi,ma;
        ma = remaind(res[i+1].second + a[i]-1, a[i], a[i]-1);
        mi = over(res[i+1].first, a[i], 0);
        if(mi > ma){ok = false;break;}
        res[i] = Pll(mi,ma);
    }
    if(ok) print(res[0].first, res[0].second);
    else cout << -1 << endl;
    return 0;

}

