using ll = long long;

int K, A[101010];

int dfs1(int v, int idx) {
    if (idx == 0) return v;

    for (int x = A[idx-1]; x < 2*A[idx]; x += A[idx-1]) {
        if (x < A[idx]) continue;
        for (int i = 0; i < A[idx-1]; i++) {
            int tm = dfs1(x+i, idx-1);
            if (tm != -1) return tm;
        }
    }
    return -1;
}

int dfs2(int v, int idx) {
    if (idx == 0) return v;

    for (int x = (1+(2*A[idx])/A[idx-1])*A[idx-1]; x >= A[idx]; x -= A[idx-1]) {
        if (x >= 2*A[idx]) continue;
        for (int i = A[idx-1]-1; i >= 0; i--) {
            int tm = dfs2(x+i, idx-1);
            if (tm != -1) return tm;
        }
    }
    return -1;
}

int main() {
    cin >> K;
    for (int j = 0; j < K; ++j) cin >> A[j];

    int a11 = dfs1(2, K-1), a12 = dfs1(3, K-1);
