	while (l <= r) {
		__int128 m = (l + r) / 2;
		if (a * m / b < c) {
			l = m + 1;
		} else {
			if (c <= a * m / b && a * m / b <= d) ans = m;
			r = m - 1;
		}
	}
	return ans;
}

