ll f(vector<ll> &A, ll c) {
    for(int i = 0; i < A.size(); i++) {
        c = c / A[i] * A[i];
    }
    return c;
}

bool f1(vector<ll> &A, ll c) {
    return f(A, c) >= 2;
}
bool f2(vector<ll> &A, ll c) {
    return f(A, c) >= 3;
}

void solve() {
    int K;
    cin >> K;
    vector<ll> A(K);
    for (int i = 0; i < K; i++) {
        cin >> A[i];
    }

    // 2以上
    ll ok = 1LL << 62, ng = 0;

    while(ok - ng > 1) {
        ll c = (ok + ng) / 2;
        if (f1(A, c)) {
            ok = c;
        } else {
            ng = c;
        }
    }
    ll okmin = ok;

    // 3以上
    ok = 1LL << 62, ng = 0;
    while(ok - ng > 1) {
        ll c = (ok + ng) / 2;
        if (f2(A, c)) {
            ok = c;
        } else {
            ng = c;
        }
    }
    ll okmax = ng;
    if (okmin > okmax) {
        cout << -1 << endl;
    } else {
        cout << okmin << " " << okmax << endl;
    }
}

