const LL Inf=1e18;

LL high(int T, int A) {
  LL good=-1,bad=Inf;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx<=T?good:bad)=mid;
  }
  return good-good%A==T?good:-1;
}

LL low(int T, int A) {
  LL good=Inf,bad=-1;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx>=T?good:bad)=mid;
  }
  return good-good%A==T?good:-1;
}

// $ g++ -std=c++11 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
vector<LL> solve(int N, vector<LL> A) {
  LL l=2,h=2;
  for(int i=N-1; i>=0; --i) {
    l=low(l,A[i]);
    h=high(h,A[i]);
    dump3(i,l,h);
    if(l>h) return {};
    if(l<=-1||l>Inf) return {};
    if(h<=-1||h>Inf) return {};
  }
  return {l,h};
}

