ll bsMin(ll st, ll end, vector<int> const &a)
{
    while (st < end)
    {
        ll mid = st + (end - st) / 2;
        if (valid(mid, a) == 0)
            end = mid;
        else if (valid(mid, a) == 1)
            end = mid - 1;
        else if (valid(mid, a) == -1)
            st = mid + 1;
    }
    return st;
}

