void solve(long long K, std::vector<long long> A){
  ll now = 2;
  ll low = -1;
  ll high = -1;
  for(int i=K-1; i>0; i--) {
    if(now % A[i] != 0) {
      now = -1;
      break;
    }
    ll r;
    if(now % A[i-1] == 0)
      r = 0;
    else
      r = A[i-1]-(now % A[i-1]);
    if(r+now<now+A[i]) {
      now = r+now;
    } else {
      now = -1;
      break;
    }
  }
  low = now;
  now = 2;
  for(int i=K-1; i>0; i--) {
    if(now % A[i] != 0) {
      now = -1;
      break;
    }
    ll h = ((now+A[i]-1) % A[i-1]);
    if(now+A[i]-1-h >= now) {
      now = now+A[i]-1-h;
    } else {
      now = -1;
      break;
    }
  }
  high = now+A[0]-1;
  if(low == -1 or high == -1)
    std::cout << -1 << std::endl;
  else
    std::cout << low << ' ' << high << std::endl;
}

