ll getmi(ll l, ll r, ll m) {
    if (m == 1) {
        return l;
    }
    if ((l - 1) / m * m + m >= r) {
        cout << -1 << endl;
        exit(0);
    }
    return (l - 1) / m * m + m;
}
// l <= x < r, x % m == 0 となる最大のx
ll getma(ll l, ll r, ll m) {
    if (m == 1) {
        return r - 1;
    }
    if ((r - 1) / m * m < l) {
        cout << -1 << endl;
        exit(0);
    }
    return (r - 1) / m * m;
}

