  reverse(a.begin(), a.end());
  if (a[0] != 2) {
    cout << -1 << endl;
    return 0;
  }
  long long inf = (long long)1e10;
  for (int i = 0; i < k; ++i) {
    long long nl = inf, nr = -1;
    if (a[i] <= l) {
      long long m = (a[i] - l % a[i]) % a[i];
      if (l + m < 2 * l) {
        nl = min(nl, l + m);
        nr = max(nr, l + m);
      }
      m = (2 * l - 1) % a[i];
      if (2 * l - 1 - m >= l) {
        nl = min(nl, 2 * l - 1 - m);
        nr = max(nr, 2 * l - 1 - m);
      }
    } else if (2 * l > a[i]) {
      nl = min(nl, a[i]);
      nr = max(nr, a[i]);
    }
    if (a[i] <= r) {
      long long m = (a[i] - r % a[i]) % a[i];
      if (r + m < 2 * r) {
        nl = min(nl, r + m);
        nr = max(nr, r + m);
      }
      m = (2 * r - 1) % a[i];
      if (2 * r - 1 - m >= r) {
        nl = min(nl, 2 * r - 1 - m);
        nr = max(nr, 2 * r - 1 - m);
      }
    } else if (2 * r > a[i]) {
      nl = min(nl, a[i]);
      nr = max(nr, a[i]);
    }
    if (nl == inf) {
      cout << -1 << endl;
      return 0;
    }
    l = nl;
    r = nr;
