ll binSearchForMin(ll b, ll e) {
    ll mid = (b+e)/2;
    while (b < e) {
        mid = (b+e)/2;
        if (b +1 == e) {
            if (val(e) == 2) {
                poss1 = true;
                return e;
            } else {
                if (val(b) == 2) poss1 = true;
                return b;
            }
        }
        if(val(mid) <= 2) {
            b = mid;
        } else {
            e = mid;
        }
    }
    return b;
}

ll binSearchForMax(ll b, ll e) {
    ll mid = (b+e)/2;
    while ( b < e) {
        mid = (b+e)/2;
        // pr(b, e);
