            if (val(e) == 2) {
                poss2 = true;
                return e;
            } else {
                if (val(b)==2) poss2 = true;
                return b;
            }
        }
        if(val(mid)>=2) {
            e = mid;
        } else {
            b = mid;
        }
    } 
    return b;
}

