        ll t = (l + A[i] - 1)/A[i] * A[i];
        if(t < l || t > r){
            cout << -1 << endl; return;
        }
        l = t;
        r = (t/A[i] + 1)*A[i] - 1;
    }
    cout << l << " " << r << endl;
}
