    //入力
    long K;
    cin>>K;
    vector<long> A(K);
    for(int i=0;i<K;i++){
        cin>>A.at(i);
    }


    //計算 後ろから区間を広げてく
    long mi=2,ma=2;//今の区間(必ず区間になる←大切)
    bool possible=true;//区間が空か？
    for(int i=K-1;i>=0;i--){//後ろから確認
        if(ijo(mi,A.at(i))<=ma && ika(ma,A.at(i))>=mi){//区間にA.at(i)の倍数があるかチェック
            mi=ijo(mi,A.at(i));//一番下の更新
            ma=ika(ma,A.at(i))+A.at(i)-1;//一番上の更新
        }else{
            possible=false;//ダメならダメだと返す
            break;
        }
    }


    //出力
    if(possible){
        cout<<mi<<" "<<ma<<endl;
    }else{
        cout<<-1<<endl;
    }
}

