		//ラウンドn終了時に残りc人である可能性があるなら開始時の人数を全てdp[n]に
		if(c >= a[n] && c%a[n] == 0){
			int num = c;
			int div = c / a[n];
			while(num < a[n] * (div + 1)){
				next.insert(num++);
			}
		}
	}
	dp = next;
}

