			cout << -1 << endl;
			return 0;
		}
		search(i);
	}

	if(dp.empty()){
		cout << -1 << endl;
		return 0;
	}

	cout << *(dp.begin()) << ' ' << *(--dp.end()) << endl;

	return 0;
}

