ll nmin[125252], nmax[125252];

int main(){
  scanf("%d",&k);
  REP(i,k)scanf("%d",a+i);
  // N_K = 2 = y*a[k-1]
  // N_{K-1} = N_K + (0 <= x < a[k-1]) = y*a[k-2]
  nmin[k] = nmax[k] = 2;
  FORR(i,0,k){
    if(i==0){
      // nmin[i] = nmin[i+1] + (0<=x<a[i])
      nmin[i] = nmin[i+1];
      nmax[i] = nmax[i+1] + a[i]-1;
    }else{
      // nmin[i] = nmin[i+1] + (0<=x<a[i]) = y*a[i-1]
      // min x s.t. ((nmin[i+1] + x) % a[i-1] == 0) && (0 <= x < a[i])
      ll x = ((nmin[i+1] + a[i-1] - 1) / a[i-1]) * a[i-1] - nmin[i+1];
      if(x >= a[i]){
        puts("-1");
        return 0;
      }else{
        nmin[i] = nmin[i+1] + x;
      }
      ll y = ((nmin[i+1] + a[i] - 1) / a[i-1]) * a[i-1] - nmin[i+1];
      if(y < 0){
        puts("-1");
        return 0;
      }else{
        nmax[i] = nmax[i+1] + y;
      }
    }
  }
  printf("%lld %lld\n", nmin[0], nmax[0]);
  return 0;
}

