ll play(vi a,ll n)
{
	rep(i,a.size())
		n=n/a[i]*a[i];
	return n;
}

ll solve_min(vi a)
{
	int k=a.size();
	if(a[k-1]!=2) return -1;

	ll res=2;
	per(i,k-1){
		ll tmp=(res+a[i]-1)/a[i]*a[i];
		if(tmp/a[i+1]!=res/a[i+1])
			return -1;
		res=tmp;
	}
	return res;
}

string solve(vi a)
{
	ll mn=solve_min(a);
	if(mn==-1) return "-1";

	int k=a.size();
	ll mx=3;
	per(i,k-1)
		mx=mx/a[i]*a[i]+a[i]-1;
	assert(play(a,mn-1)!=2);
	assert(play(a,mn)==2);
	assert(play(a,mx)==2);
	assert(play(a,mx+1)!=2);
	return to_string(mn)+" "+to_string(mx);
}

