            return 0;
        }
        if(left/A[i] == right/A[i] && left%A[i] == 0 && right%A[i] == 0){
            cout << -1 << endl;
            return 0;
        }
        if(left % A[i] != 0) left = (left/A[i]+1)*A[i];
        right = (right/A[i]+1)*A[i]-1;
    }
    cout << left << ' ' << right << endl;
}

