	for(int i = 1 ; i <= k ; i++){
		cin >> a[i];
		if(a[i] < 2){
			cout << -1 << endl;
			return 0;
		}
	}
	if(a[k] != 2){
		cout << -1 << endl;
		return 0;
	}
	for(int i = k-1 ; i > 0 ; i--){
		if(a[i] >= (ans * 2)){
			cout << -1 << endl;
			return 0;
		}
		if(a[i] >= ans)ans = a[i];
		else if(ans % a[i] == 0)continue;
		else{
			ans = ((ans / a[i]) + 1) * a[i];
		}
	}
	ans2 = a[1] - 1 + ans;
	cout << ans << " " << ans2 << endl;
	return 0;
}

