			if((t / a[i] + 1) *a[i] / a[i + 1] > gp)
			{
				printf("-1\n");
				return 0;
			}
			else
				gp = t / a[i] + 1,t = (t / a[i] + 1) * a[i];
		}
		else
			gp = t / a[i];
	}
	long long tmpt = t;
	t = a[K] + (a[K] - 1);
