#include <bits/stdc++.h>
#define rep(i,a,b) for(int i=a;i<=b;i++)
#define rrep(i,a,b)	for(int i=a;i>=b;i--)
using namespace std;
typedef long long ll;
const int N=2e5+5,inf=0x3f3f3f3f;
ll k,a[N];
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	ll mn=2e15,mx=-1;
	cin>>k;
	rep(i,1,k)	cin>>a[i];
	ll x=2;
	rrep(i,k,2)
	{
		ll p=x/a[i],y=p*a[i],z=(p+1)*a[i];
		// (n[i]/a[i+1]) *a[i+1] =n[i+1]	
		// p=n[i]/a[i+1] = n[i+1]/a[i+1]
		//p为第i轮过后的人被分为多少组.
		// n[i]= p*a[i+1] +r   (0<=r<a[i+1])
		// n[i]= q*a[i]. 找到最后一个>=y的a[i]的倍数.
		ll q=z/a[i-1];
		if(z%a[i-1]==0)
			q--;
		x=q*a[i-1];
	//	cout<<x<<' ';
		if(x<y)
		{
			x=0;
			break;
		}
	}
	if(x>0)
	{
		ll p=x/a[1],y=(p+1)*a[1]-1;
		cout<<x<<' '<<y<<endl;
	}
	else
		puts("-1");

	return 0;
}

