int func(ll n, vector<int> &a, int level, int k){
	if(level == k){
		if(n > 2) return 1;
		else if(n == 2) return 0;
		else return -1;
	}else{
		n = n/a.at(level)*a.at(level);
		return func(n, a, level+1, k);
	}
}

int b_serch(ll l, ll r, vector<int> &a, int k){
	if(r <= l) return r;
	int mid = (r + l) / 2;
	if(func(mid, a, 0, k) >= 0){
		return b_serch(l, mid, a, k);
	}else{
		return b_serch(mid+1, r, a, k);
	}
}

int b_serch2(ll l, ll r, vector<int> &a, int k){
	if(r <= l) return r-1;
	int mid = (r + l) / 2;
	if(func(mid, a, 0, k) <= 0){
		return b_serch2(mid+1, r, a, k);
	}else{
		return b_serch2(l, mid, a, k);
	}
}

