#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using ull = unsigned long long;
#define INF 1000000001

int k;
ll a[1000000];
ll amax=-1;
int mind;

bool judge(ll n){
  for(int i=0;i<k;i++){
    if (n % a[i]==0){
      continue;
    }else{
      n=n-n%a[i];
    }
    if (n < 2){
      return false;
    }
  }
  if (n==2){
    return true;
  }else{
    return false;
  }
}

int main(){
  cin>>k;
  for(int i=0;i<k;i++){
    cin>>a[i];
    if (a[i]>amax){
      amax=a[i];
      mind=i;
    }
  }
  ll mi=amax;
  for(int i=mind-1;i>=0;i--){
    ll tmp=2;
    while(a[i]*tmp<mi){
      tmp++;
    }
    mi=a[i]*tmp;
  }
  if (!judge(mi)){
    cout<<-1<<endl;
    return 0;
  }
  ll ma=2+k*amax;
  while(judge(ma)){
    ma*=2;
  }
  ll ub=ma, ul=ma/2, mid=(ub+ul)/2;
  while(1){
    bool judge1=judge(mid);
    if (judge1 && !judge(mid+1)){
      ma=mid;
      break;
    }
    if (judge1){
      ul=mid;
    }else{
      ub=mid;
    }
    mid = (ub+ul)/2;
  }
  cout<<mi<<" "<<ma<<endl;
  return 0;
}

