using namespace std;
typedef long long ll;
ll tourist[100005]={0};
ll k;
bool judge(ll n){
  for(int i=0;i<k;i++){
    n=n-(n%tourist[i]);
  }
  if(n==2) return true;
  else return false;
}
int main(){
  cin>>k;
  for(int i=0;i<k;i++) cin>>tourist[i];
  ll mi=2;
  //cout<<-1<<endl;
  //return 0;
  for(int i=k-1;i>0;i--){
    ll sr=tourist[i-1];
    ll ks=0;
    if(sr>mi) ks=sr-mi;
    if(sr<mi){
      ks=sr-(mi%sr);
      if(ks==sr) ks=0;
    }
    mi+=ks;
  }
  if(!judge(mi)) {
    cout<<-1<<endl;
    return 0;
  }
  ll lb=0,rb=mi+1;
  while(rb-lb>1){
    ll mid=(lb+rb)/2;
    if(judge(mid)) rb=mid;
    else lb=mid;
  }
  cout<<rb<<" ";
  ll lb2=rb,rb2=1e18;
  while(rb2-lb2>1){
    ll mid=(lb2+rb2)/2;
    if(judge(mid)) lb2=mid;
    else rb2=mid;
  }
  cout<<lb2<<endl;
}

