        }
        return;
    }
    int d = ((n/A[step-1])*A[step-1] + (A[step-2]-1))/A[step-2];
    if((!up) && d >= 1 && A[step-2]*d < (n/A[step-1] + 1)*A[step-1]){
        solve(A[step-2]*d, step-1, false);
    }
    d = ((n/A[step-1]+1)*A[step-1] - 1)/A[step-2];
    if(up && d >= 1){
        solve(A[step-2]*d, step-1, true);
    }
