void solve() {
  rd(int, n);
  rdv(int, a, n);
  if (a.back() != 2) err(-1);
  a.erase(unique(all(a)), a.end());
  n = sz(a);
  int mn = 2, mx = 3;
  per(i, n - 2, 0) {
    int cur_mn = (mn / a[i]) * a[i] + a[i];
    if (cur_mn > mx) err(-1);
    mn = cur_mn;
    mx = (mx / a[i]) * a[i] + a[i] - 1;
  }
  wr(mn, mx);
}

