int findl(int l,int t) {
	if (t < 1)return l;
	int ans;
	if (l%a[t] == 0)
		for (int i =0; i < a[t]; ++i)
		{
			ans = findl(l+i, t - 1);
			if (ans != -1) { return ans; break; }
		}
	return -1;
}

int findr(int r, int t) {
	if (t < 1)return r;
	int ans;
	if (r%a[t] == 0)
		for (int i = a[t]-1; i >=0; --i)
		{
			ans = findr(r + i, t - 1);
			if (ans != -1) { return ans; break; }
		}
	return -1;
}

