  for (auto it = A.rbegin(); it != A.rend(); ++it) {
    if (*it > min_k)
      min_k = *it;
    if (max_k < *it) {
      OUT(-1);
      return 0;
    }
    ll q = max_k/(*it);
    max_k = (*it)*q + *it-1;
    min_k = (*it)*q;
  }
  OUT(min_k << " " << max_k);

    return 0;
}

