ll f(ll x, ll a) {
  return x - (x%a);
}

// return true if n can be result in 2 or smaller.
bool checkSmall(vector<ll>& a, ll n) {
  ll now = n;
  rep(i, a.size()) {
    now = f(now, a[i]);
  }
  return now <= 2;
}

// return true if n can be result in 2 or larger.
bool checkLarge(vector<ll>& a, ll n) {
  ll now = n;
  rep(i, a.size()) {
    now = f(now, a[i]);
  }
  return now >= 2;
}

int main(int argc, char** argv) {
  cin.tie(NULL);
  cout.tie(NULL);
  ios_base::sync_with_stdio(false);
  //cout << setprecision(10) << fixed;

  ll k;
  cin >> k;
  vector<ll> a(k);
  ll maxA = 0;
  rep(i, k) {
    cin >> a[i];
    maxA = max(maxA, a[i]);
  }
  ll largest, smallest;

  // Here, we find the result in binary search.
  {
    ll l = 2, r = k * maxA + 3;
    // find the result in [l, r). find the boundary in [t, t, .., t, f, .. , f]
    while (r - l > 1) {
      ll m = (l + r)>>1;
      if (checkSmall(a, m)) {
        l = m;
      } else {
        r = m;
      }
    }
    largest = l;
  }

  {
    ll l = 1, r = k * maxA + 2;
    // find the result in (l, r]. find the boundary in [f, f, ..., f, t, .., t]
    while (r - l > 1) {
      ll m = (l + r)>>1;
      if (checkLarge(a, m)) {
        r = m;
      } else {
        l = m;
      }
    }
    smallest = r;
  }

  // For Debug
  cout << "smallest: " << smallest << endl;
  cout << "largest: " << largest << endl;

  if (smallest <= largest) {
    cout << smallest << " " << largest << endl;
  } else { // invalid
    cout << -1 << endl;
  }
}

