                l = m;
            else
                r = m - 1;
        }

        R = l;

        if (L > R) {
            printf("-1\n");
            return ;
        }
    }

    if (!f(L) || !f(R))
        printf("-1\n");
    else
        printf("%lld %lld\n", L, R);
