using namespace std;
typedef long long LL;
typedef vector<long> VI;
typedef vector<VI> VVI;

VI A;
LL K;

LL simulate(LL N){
	LL retval = N;
	REP(i,K) retval -= (retval % A[i]);
	return retval;
}

LL binary_search_min(LL maxval){
	LL middle,minv = llINF;
	LL l = 0;
	LL r = maxval;
	LL ans;
	while (l <= r){
		middle = (l + r) / 2;
		ans = simulate(middle);
		#ifdef DEBUG
		 dump(middle);
		 dump(ans);
		#endif

		if (ans == 2) minv = min(middle,minv); 
		if(ans >= 2) r = middle-1;
		else l = middle+1;
	}

	return minv;
}

LL binary_search_max(LL maxval){
	LL middle,maxv = -1;
	LL l = 0;
	LL r = maxval;
	LL ans;
	while (l <= r){
		middle = (l + r) / 2;
		ans = simulate(middle);

		if (ans == 2) maxv = max(middle,maxv);

		if(ans <= 2) l = middle + 1;
		else r = middle-1;
	}

	return maxv;
}


