    }
    ll mi = 2, ma = 3;
    FOR(i, 1, K) {
        if ((ll)A[i] > ma||ma<mi) {
            cout << -1 << endl;
            return 0;
        } else if (A[i] < mi) {
            mi = (ll) A[i] * ((mi + A[i] - 1) / A[i]);
            ma = (ll) A[i] * (ma / A[i] + 1) - 1;
        } else {
            mi = A[i];
            ma = (ll) A[i] * (ma / A[i] + 1) - 1;
        }
    }
    cout << mi << " " << ma << endl;


    return 0;
}

