static void exec()
{
	int K;
	get(K);

	std::vector<LLONG> ai(K);
	for (int i = 0; i < K; i++) {
		get(ai[i]);
	}

	if (ai[K - 1] != 2) {
		printf("-1\n");
		return;
	}

	LLONG min = 2, max = 3;
	for (int i = K - 2; i >= 0; i--) {
		if (min < ai[i]) {
			if ((2 * ai[i + 1]) <= ai[i]) {
				printf("-1\n");
				return;
			}
			min = ai[i];
		}
		else if (min > ai[i]) {

			LLONG val = ai[i];
			while (val < (2 * ai[i + 1])) {
				if (val >= min) {
					min = val;
					break;
				}
				val += ai[i];
			}

			if (min % ai[i]) {
				printf("-1\n");
				return;
			}
		}

		if (max < ai[i]) {
			printf("-1\n");
			return;
		}
		else if (max > ai[i]) {
			max = max / ai[i] * ai[i];
			max += ai[i] - 1;

			if (ai[i + 1] > max) {
				printf("-1\n");
				return;
			}
		}
		else {
			max = 2LL * ai[i] - 1LL;
		}
	}
	printf("%lld %lld\n", min, max);
}

