i64 calc(const i64 nextValue, const i64 x, const i64 y) {
    i64 low = 0;
    i64 high = INF;
    while (high - low > 1) {
        const i64 mid = (low + high) / 2;
        if (f(x * mid, y) >= nextValue) high = mid;
        else low = mid;
    }

    return x * high;
}

