typedef long long ll;

pair<int, int> solve(vector<int> a) {
    int n = a.size();
    if (a[n - 1] != 2) return {-1, -1};

    ll mn = 2, mx = 2;
    for (int i = n - 2; i >= 0; i--) {
        // x%a[i]=0
        // x-x%a[i+1]=old
        ll nmn = (mn + a[i] - 1) / a[i] * a[i];
        if (nmn - mn >= a[i + 1]) return {-1, -1};
        mn = nmn;
    }

    return {mn, mn + a[0] - 1};
};

