pair < ll, ll > get_range( int i ){
	if( i == n+1 ){
		return mp(2,2);
	}
	pair < ll, ll > x ;
	x = get_range( i + 1 ); 
	ll smallest, largest;
	smallest = x.first;
	largest = x.second;
	if( smallest == -1 )
		return x;
	if( a[i] > largest )
		return mp( -1 ,-1 );
	ll smallest_divisor = ( smallest - 1 ) / a[i];
	ll largest_divisor = largest / a[i];
	ll min_children, max_children;
	min_children = ( smallest_divisor + 1 ) * a[i];
	max_children = ( ( largest_divisor + 1 ) * a[i] ) - 1;
	return mp( min( min_children, min_children), max( min_children, max_children));
}


