//ラウンドiの直前の時点で脱落せず残っている子供の人数をXとする。
//ラウンドiの直後には何人残るか？
//作られるグループの個数は明らかにX/AiであるためX-X mod Ai人が残ることになる
//以後　fp(X)=X- X mod pと書く
//この問題では次のようなNの値を全て求めることが要求されている
//g(N)=fAk(fAk-1(...fA1(N)...))=2
//主に二つの方針が考えられる
//解法１
//操作を逆にして更新していく
//最終的に二人が生き残るようなラウンドiの直後での最小の生存人数をLiとし同様に
//最大の生存人数をRiとする。Lk=Rk=2であることがわかっていて求めたいものはL0,R0
//Li,RiからLi-1,Ri-1を復元する
//まずラウンドiの直後での生存人数はAiで割り切れなければいけないもしLiとRiの間に
//Aiの倍数が存在しない場合答えは-1となる。
//そうでない場合、区間[Li,Ri]内のAiの倍数の内最小のものと最大の物をそれぞれXi,Yiとすると
//Li=Xi,Ri=Yi+Ai-1となる
//ここでXi=[Li/Ai]*Ai,Yi=Ri/Ai*Aiであるため結局
//L(i-1)=[Li/Ai]*Ai
//R(i-1)=Ri/Ai+Ai-1
int main() {
	int K;
	cin >> K;
	int A[100100];
	REP(i, K)cin >> A[i];
	ll L = 2, R = 2;
	for (int i = K - 1; i >= 0; --i) {
		L = (L + A[i] - 1) / A[i] * A[i];
		if (R < L) {
			cout << -1 << endl;
			return 0;
		}
		R = (R / A[i] + 1)*A[i] - 1;
	}
	cout << L << " " << R << endl;
	return 0;
}

