using namespace::std;

LL f(LL X,vector<LL>& A){
	int size = A.size();
	for(int i=0;i<size;++i){
		//X = (X/A[i])*A[i];//AC
		X -= X%A[i];
	}
	return X;
}
void solve(){
	int K;
	cin >> K;
	vector<LL> A(K);
	for(int i=0;i<K;++i){
		cin >> A[i];
	}
	//////
	//最後に2人以上残る最小値を探す
	LL NG,OK;
	NG = 0;
	OK = LINF;
	LL f_OK = f(OK,A);
	if( f_OK < 2 ){
		cout << -1 << endl;
		return;
	}
	while(OK-NG>1){
		LL mid = (NG+OK)/2;
		LL f_mid = f(mid,A);
		if( f_mid >= 2 ){
			OK = mid;
		}else{
			NG = mid;
		}
	}
	f_OK = f(OK,A);
	LL f_NG = f(NG,A);
	if( f_OK != 2 ){
		cout << -1 << endl;
		return;
	}
	LL ansMin = OK;
	//2人残る最小値が存在したので、
	//最大値は、最小値以上の値で存在する。

	//最後に2人以下残る最大値を探す
	LL L,R;
	L = ansMin;//最後に0人残る
	R = LINF;
	while(R-L>1){
		LL mid = (L+R)/2;
		LL f_mid = f(mid,A);
		if( f_mid <= 2 ){
			L = mid;
		}else{
			R = mid;
		}
	}
	LL ansMax = L;
	cout << ansMin << " " << ansMax << endl;
}
