#include <iostream>
#include <vector>
using namespace std;

int N;
vector<long long> arr;
vector<long long> dp_max;
vector<long long> dp_min;

int solv(vector<long long> &dp, bool is_max) {
  dp[N] = 2;
  long long max_boarder, min_bound;
  for (int i = arr.size() - 1; i > 0; i--) {
    max_boarder = dp[i+1] + arr[i];
    if (arr[i-1] >= max_boarder) {
      return 0;
    }

    if (dp[i+1] % arr[i-1] != 0) {
      min_bound = ((dp[i+1] / arr[i-1]) + 1) * arr[i-1];
    } else {
      min_bound = dp[i+1];
    }

    if (min_bound >= max_boarder) {
      return 0;
    }

    if (is_max) {
      dp[i] = ((max_boarder-1) / arr[i-1]) * arr[i-1];
    } else {
      dp[i] = min_bound;
    }

  }

  return 1;
}

int main() {

  cin >> N;

  long long a;
  for (int i = 0; i < N; i++) {
    cin >> a;
    arr.push_back(a);
  }

  // if (arr[arr.size() - 1] != 2) {
  //   cout << -1 << endl;
  //   return 0;
  // }

  if (N == 1) {
    if (arr[0] == 1) {
      cout << "2 2" << endl;
    } else if (arr[0] == 2) {
      cout << "2 3" << endl;
    } else {
      cout << "-1" << endl;
    }
    return 0;
  }

  dp_max.resize(N+1);
  dp_min.resize(N+1);

  int exist = solv(dp_max, true);
  if (!exist) {
    cout << -1 << endl;
    return 0;
  }

  solv(dp_min, false);

  long long min_res, max_res;
  if (dp_min[1] % arr[0] == 0) {
    min_res = dp_min[1];
  } else {
    min_res = ((dp_min[1] / arr[0]) + 1) * arr[0];
  }


  max_res = dp_max[1] + arr[0] - 1;

  cout << min_res << " " << max_res << endl;

  return 0;

}

