        ll test = ((min / A[i])) * A[i];
        if (test < min) test += A[i];
        min = test;
        test = ((max / A[i])) * A[i];
        if (test <= max) test += A[i];
        max = test - 1;
        //cerr << max << ", " << min << endl;
        if (max < min) {
            cout << -1 << endl;
            return 0;
        }
    }
    cout << min << " " << max << endl;

    return 0;
}

