/*
N -> N - N % A[i] (N以下の最大のA[i]の倍数にする)ということを繰り返して、最終的に2になった。
最初のNの最大値、最小値は？

Nに対する(最後の数字)は単調増加なので、二分探索でやればよい。
*/

long long K, A[100000];
long long maxN, minN;
long long p, q;
long long r, num;


int main() {
	scanf("%lld", &K);
	for (int i = 0; i < K; i++) {
		scanf("%lld", &A[i]);
	}

	p = 1000000000000000;
	q = 0;

	/*まず、Nの最小値を求める。
	r = (p+q)/2から初めて計算する。答えが>= 2なら、p=rとする。<1なら、q=r+1とする。*/
	while (p - q >= 1) {
		r = (p + q) / 2;
		num = r;
		for (int i = 0; i < K; i++) {
			num = num - num % A[i];
		}
		if (num >= 2) { p = r; }
		else { q = r + 1; }
	}

	num = p;
	for (int i = 0; i < K; i++) {
		num = num - num % A[i];
	}
	if (num != 2) { printf("-1"); return 0; }

	printf("%lld ", p);

	p = 1000000000000000;
	q = 0;
	/*次に、Nの最大値を求める。答えが>2なら、p=r-1とする。<=2なら、q=rとする。*/
	while (p - q >= 1) {
		r = (p + q) / 2+1;
		num = r;
		for (int i = 0; i < K; i++) {
			num = num - num % A[i];
		}
		if (num > 2) { p = r-1; }
		else { q = r; }
	}
	printf("%lld\n", p);


}

