// Antsbook p.132
// minimum x (C(x) == true)
bool C(ll d, ll x, ll i){
    return x/a[i] != d/a[i];
}

ll BinarySearchMin(ll lb, ll ub, ll i){
    ll lb_ = lb;
    // 返り値の範囲：(lb, ub]
    // 条件：
    //   (lb, ub]で検証できること
    //   C(lb)==false, C(ub)==true
    while(ub - lb > 1){
        ll mid = ((lb + ub) >> 1);
        if(C(mid, lb_, i)){
            // (lb, mid]
            ub = mid;
        }else{
            // (mid, ub]
            lb = mid;
        }
    }
    return ub;
}

// Antsbook p.132
// maximum x (C(x) == true)
bool C2(ll d, ll x, ll i){
    return x/a[i] == d/a[i];
}

ll BinarySearchMin2(ll lb, ll ub, ll i){
    ll ub_ = ub;
    // 返り値の範囲：(lb, ub]
    // 条件：
    //   (lb, ub]で検証できること
    //   C(lb)==false, C(ub)==true
    while(ub - lb > 1){
        ll mid = ((lb + ub) >> 1);
        if(C2(mid, ub_, i)){
            // (lb, mid]
            ub = mid;
        }else{
            // (mid, ub]
            lb = mid;
        }
    }
    return ub;
}


