bool le(const std::vector<int> &A, intmax_t m) {
  for (size_t i=0; i<A.size(); ++i)
    m -= m % A[i];

  return m <= 2;
}

bool ge(const std::vector<int> &A, intmax_t m) {
  for (size_t i=0; i<A.size(); ++i)
    m -= m % A[i];

  return m >= 2;
}

int main() {
