    for (int i = K - 1; i >= 0; i --) {
        n = n + A[i] - 1;
    }
    return n;
}

bool ok(int N) {
    int n = N;
    for (int i = 0; i < K; i ++) {
        n = n / A[i] * A[i];
    }
    return n == 2;
}

int find_min() {
    int n = 2;
    for (int i = K - 1; i >= 0; i --) {
        int a = i > 0 ? A[i - 1] : 1;
        int q = n / a + (n % a ? 1 : 0);
        int nn = a * q;
        int r = nn - n;
        if (r >= A[i]) return -1;
        n = nn;
    }
    return n;
}

int find_max() {
    int n = 2;
    for (int i = K - 1; i >= 0; i --) {
        int a = i > 0 ? A[i - 1] : 1;
        int q = (A[i] + n - 1) / a;
        int nn = a * q;
        int r = nn - n;
        if (r < 0) return -1;
        n = nn;
    }
    return n;
}

