const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll k, as[MAX_N];


ll judge(ll val){
    rep(i, k)
        val -= val % as[i];
    return val;
}

void solve(){
    rep(i, k) in1(as[i]);
    if (as[k - 1] != 2){
        prl(-1); return;
    }

    ll lb, ub;
    ll right = INF, left = 1;
    while(right > left){
        // when seeking lower bound
        ll mid = (right + left) / 2;
        if (judge(mid) >= 2) right = mid;
        else left = mid + 1;
    }
    lb = right;

    right = INF, left = 1;
    while(right > left){
        // when seeking upper bound
        ll mid = (right + left + 1) / 2;
        if (judge(mid) <= 2) left = mid;
        else right = mid - 1;
    }
    ub = right;

    if (lb <= ub) prl2(lb, ub);
    else prl(-1);
}

int main(void){
    in1(k);
    // assert(k <= 100000);
    solve();
    return 0;
}

