    ll lb = A.front(); ll ub = A.front() * 2 - 1;
    ll crt = 0;
    auto lcomp = [&](ll mid){
        return (lb <= mid * crt);
    };
    auto ucomp = [&](ll mid){
        return (mid * crt  + crt - 1<= ub);
    };
    for(ll i = 1; i < A.size(); ++i){
        crt = A[i];
        if(crt  > ub)
            return puts("-1") * 0;
        ll tlb = minimize(0, 1e15, lcomp);
        ll tub = maximize(1, 1e15, ucomp);
        lb = crt * tlb; ub = tub * crt  + crt - 1;
    }
    cout << lb << " " << ub << endl;
}

