bool isOK(ll start, ll goal) {
    for(int i = 0; i < K; i++) {
        start -= start % A[i];
    }
    if(start >= goal)
        return true;
    else
        return false;
}

ll binary_search(int key) {
    ll ng = 1;        //「index = 0」が条件を満たすこともあるので、初期値は -1
    ll ok = longinf;  // 「index = a.size()-1」が条件を満たさないこともあるので、初期値は a.size()

    while(abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;

        if(isOK(mid, key))
            ok = mid;
        else
            ng = mid;
    }
    return ok;
}

