	vector<int> A = in(K);
	reverse(ALL(A));
	if (A[0] != 2) {
		cout << -1 << endl;
		return;
	}

	pii B(2,3);
	FOR(i, 1, K) {
		int x = A[i];
		B.first = ((B.first - 1) / x + 1)*x;
		if (B.first > B.second) {
			cout << -1 << endl;
			return;
		}
		B.second = B.second / x*x + (x - 1);
	}
	cout << B.first << " " << B.second << endl;;
}

