}
inline long long read()
{
	long long x=0,b=1;
	char c=nc();
	for(;!(c<='9'&&c>='0');c=nc())if(c=='-')b=-1;
	for(;c<='9'&&c>='0';c=nc())x=x*10+c-'0';
	return x*b;
}
inline void write(long long x)
{
	if(x==0)putchar('0');
	else
	{
		char buf[15];
		long long len=0;
		if(x<0)putchar('-'),x=-x;
		while(x)buf[++len]=x%10+'0',x/=10;
		for(long long i=len;i>=1;i--)putchar(buf[i]);
	}
	putchar(' ');
}
