ipair solve() {
    ipair res = make_pair(2, 2);
    for(int i = K - 1; i >= 0; --i) {
        //cout << res.first << ", " << res.second << endl;
        /*
            区間[res.first, res.second)でA[i]で割り切れるものをx_1, ..., x_kとする
            k = 0のとき，条件を満たすNは存在しない．
