void solve(){
	int n;
	cin >> n;
	for(int i =1;i<=n;i++){
		cin >> a[i];
	}
	int lo = 2,hi= 1e12;
	int ans = INF;
	for(;lo<=hi;){
		int k = (lo + hi)>>1ll;
		int cur = k;
		for(int i =1;i<=n;i++){
			cur -= (cur % a[i]);
		}
		if(cur == 2){
			ans = min(ans,k);
			hi = k-1;
		}
		else if(cur > 2) hi = k-1;
		else lo = k+1;
	}
	// cout << ans << endl;
	int x = ans;	
	lo = 2,hi = 1e12;
	ans = -1;
