			cur -= (cur % a[i]);
		}
		if(cur == 2){
			ans = max(ans,k);
			lo = k+1;
		}
		else hi = k-1;
	}
	int y = ans;
	if(x == INF || y == -1){
		cout << -1 << endl;
		return;
	}
	cout << x << " " << y << endl;
}
