bool go(lint &tl, lint &th, lint x) {
	lint l, r;
	l = 1, r = 1e9 + 5;
	//tl이상이면서 x의 배수인 가장 작은 수 
	//th이하이면서 x의 배수인 가장 큰 수 
	lint a = 1e9 + 6;
	lint b = 0;
	while(l<=r) {
		lint m = (l+r)/2;
		if(tl<=x*m) {
			a = min(a, m);
			r = m-1;
		}
		else {
			l = m+1;
		}
	}
	if(a==1e9+6)return false;
	l = 1, r = 1e9+5;
	while(l<=r) {
		lint m = (l+r)/2;
		if(x*m<=th) {
			b = max(b, m);
			l = m+1;
		}
		else {
			r = m-1;
		}
	}
	if(b==0)return false;
	if(a>b) {
		return false;
	}
	tl = a*x;
	th = b*x+(x-1);
	return true;
}

