	in >> N;
	A.resize(N);
	rep(i, N) { in >> A[i]; }

	if (A[N - 1] != 2)
	{
		out << -1 << std::endl;
		return 0;
	}
	min = 2;
	for (int i = N - 1; i >= 0; --i)
	{
		if (i != N - 1)
		{
			if (A[i] > min + (A[i + 1] - 1))
			{
				out << -1 << std::endl;
				return 0;
			}
		}
		if (A[i] >= min) min = A[i];
		if (A[i] < min) min = (min / A[i] + (min%A[i] == 0 ? 0 : 1))*A[i];
	}
	max = 2;
	for (int i = N - 1; i >= 0; --i)
	{
		if (A[i] >= max)
		{
			max += A[i] - 1;
		}
		else
		{
			max = max / A[i] * A[i];
			max += A[i] - 1;
		}
	}

	out << min << " " << max << std::endl;
	return 0;
}

