const ll MI = 2;
const ll MX = 1000000000000000000;

bool oklo(ll x) {
	for (int i = 0; i < k; ++i) {
		x -= x%t[i];
		if (x < 2) return false;
	}
	return (x >= 2);
}

bool okhi(ll x) {
	for (int i = 0; i < k; ++i) {
		x -= x%t[i];
		if (x < 2) return false;
	}
	return (x <= 2);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);
	cin >> k;
	for (int i = 0; i < k; ++i) {
		cin >> t[i];
	}
	ll lo = MI-1;
	for (ll a = (1LL<<62); a >= 1; a /= 2) {
		if (lo+a <= MX && !oklo(lo+a)) lo += a;
	}
	if (!oklo(lo+1)) {
		cout << "-1\n";
		return 0;
	}
	ll hi = lo+1;
	for (ll a = (1LL<<62); a >= 1; a /= 2) {
		if (hi+a <= MX && okhi(hi+a)) hi += a;
	}
	if (oklo(lo+1) && okhi(hi)) {
		cout << lo+1 << " " << hi << "\n";
	}
	else {
		cout << "-1\n";
	}
	return 0;
}

