int calc(const long long start, const vector<int> &a) {
        if (start < 0) return 0;
        int n = a.size();
        long long val = start;
        for (int i = 0; i < n; i ++) {
                val = (long long) (val / a[i]) * a[i];
        }
        if (val < 2) return 0;
        else if (val == 2) return 1;
        else return 2;
}

