#define int ll
template<class F>
auto  minimize(int imin,int imax,F &f){
    while(imax - imin > 1){
        int mid = imin + (imax - imin)/2;
        if(f(mid)) imax = mid;
        else imin = mid;
    }
    return imax;
}

/*
 [imin,imax) -> imin
 return maximum index such that v[index] <= value
 auto f(int mid) {return v[mid] <= value;}
 */
template<class F>
auto  maximize(int imin,int imax,F &f){
    while(imax - imin > 1){
        int mid = imin + (imax - imin)/2;
        if(f(mid)) imin = mid;
        else imax = mid;
    }
    return imin;
}

signed main(){
    ll K;
    cin >> K;
    vector<ll>A(K);
    for(auto & e : A) cin >> e;
    reverse(A.begin(),A.end());
    if(A.front() != 2) return puts("-1") * 0;
    ll lb = A.front(); ll ub = A.front() * 2 - 1;
    ll crt = 0;
    auto lcomp = [&](ll mid){
        return (lb <= mid * crt);
    };
    auto ucomp = [&](ll mid){
        return (mid * crt <= ub);
    };
    for(ll i = 1; i < A.size(); ++i){
        crt = A[i];
        if(crt  > ub)
            return puts("-1") * 0;
        ll tlb = minimize(0, 1e15, lcomp);
        ll tub = maximize(1, 1e15, ucomp);
        lb = crt * tlb; ub = crt * tub;
    }
    cout << lb << " " << ub + crt - 1 << endl;
}

