typedef long long ll;

struct Range {
  ll l, r;
  Range() {}
  Range(ll l, ll r): l(l), r(r) {}
};

int main() {
  int k;
  cin >> k;
  vector<ll> la(k);
  for (ll &a: la) { cin >> a; }
  Range range = Range(2, 2);
  for (int i = k-1; i >= 0; --i) {
    ll nl = ((range.l-1)/la[i]+1)*la[i];
    ll nr = (range.r/la[i])*la[i]+la[i]-1;
    // cerr << nl << " " << nr << endl;
    if (nl > range.r || nr < range.l) {
      cout << -1 << endl;
