typedef long long LL;
typedef pair<LL,LL> PLL;

LL k,x,y,arr[100009];

PLL doit(LL x,LL y,LL mod)
{
    LL z=(x-1)/mod;
    z=(z+1)*mod;
    if(z>y)
    {
        cout<<-1<<endl;
        exit(0);
    }
    x=z;
    z=y/mod;
    z=(z+1)*mod-1;
    y=z;
    return make_pair(x,y);
}

