void fail(){
	cout << -1 << endl;
	exit(0);
}

P f(ll a, ll l, ll r){
	if(r <= a) fail();

	P ret;
	ll ng = 0, ok = 2e9;
	while(abs(ng - ok) > 1){
		ll mid = (ng + ok) / 2;
		if(a * mid >= l) ok = mid;
		else ng = mid;
	}
	ret.first = a * ok;
	ok = 0, ng = 2e9;
	while(abs(ng - ok) > 1){
		ll mid = (ng + ok) / 2;
		if(a * mid < r) ok = mid;
		else ng = mid;
	}
	ret.second = a * ok;
	return ret;
}



