void bin_search() {


    ll l = 2;
    ll r = INF;
    ll mx = -1;
    ll mn = INF;

    while(l <= r) {

        ll mid = (l + r) / 2ll;

        if(check(mid) == 0) {r = mid - 1; mx = max(mx, mid); mn = min(mn, mid);}
        else if (check(mid) == 1) {r = mid - 1;}
        else {l = mid + 1;}

    }

    l = 2;
    r = INF;

    while(l <= r) {

        ll mid = (l + r) / 2ll;

        if(check(mid) == 0) {l = mid + 1; mx = max(mx, mid); mn = min(mn, mid);}
        else if (check(mid) == 1) {r = mid - 1;}
        else {l = mid + 1;}

    }

    if(mn == INF && mx == -1) {cout << -1;return;}

    cout << mn << ' ' << mx;


}

