  for (long i = 0; i < K; i++) {
    scanf("%ld", &as[i]);
  }

  // ls[i] : The minimum possible value of ns[i],
  //         before considering the requirement that ns[i]
  //         must be a multiple of as[i]
  // us[i] : Similarly, the maximum possible of ns[i]
  long ls[MAX_K + 1] = {}, us[MAX_K + 1] = {};
  ls[K] = 2;
  us[K] = 2;
  for (long i = K - 1; i >= 0; i--) {
    // find ld and ud the minimum and maximum values in the range
