    const long a = as[i], l = ls[i + 1], u = us[i + 1];
    const long ld = (l + a - 1) / a * a, ud = u / a * a;
    if (ld >= l && ld <= u && ud >= l && ud <= u) {
      ls[i] = ld;
      us[i] = ud + a - 1;
    } else {
      ls[0] = -1;
      us[0] = -1;
      break;
    }
  }
  if (ls[0] >= 0) {
    printf("%ld %ld\n", ls[0], us[0]);
