const int MAX_N=1e6+1;
LL A[MAX_N];
int K;

void fail() {
  cout<<-1<<endl;
  exit(0);
}

bool ok1(LL N) {
  LL n=N;
  REP(i,K) {
    LL g=n/A[i];
    n=g*A[i];
  }
  return n>=2;
}
bool ok2(LL N) {
  LL n=N;
  REP(i,K) {
    LL g=n/A[i];
    n=g*A[i];
  }
  return n<=2;
}

void solve_bs() {
  LL good=2e18,bad=0;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2;
    bool res=ok1(mid);
    (res?good:bad)=mid;
  }
  LL lb=good;

  good=1,bad=2e18;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2;
    bool res=ok2(mid);
    (res?good:bad)=mid;
  }
  LL hb=good;
  if(hb<lb) fail();
  cout<<lb<<" "<<hb<<endl;
}

void solve() {
  LL l=2,r=2;
  for(int i=K-1; i>=0; --i) {
    LL g1=(l+A[i]-1)/A[i],g2=r/A[i];
    SMAX(g1,1LL);
