    while (idx > 0 and A[idx - 1] == 2) idx--;
    */

    int64 ng = 0, ok = 2e9;
    while (ok - ng > 1) {
        int64 mid = (ng + ok) / 2;
        if (simulate(mid, A) >= 2) ok = mid;
        else ng = mid;
    }
    if (simulate(ok, A) != 2) {
        cout << -1 << endl;
        return 0;
    }

