bool	One(long A, long &MA, long &MI) {
	if (A>MA)
		return false;
	if (A*2<=MI)
		return false;
	MA /=A;
	MA *=A;
	MA +=A-1;
	MI=(MI+A-1)/A;
	MI *=A;
	return true;
}

