const LL Inf=1e18;

LL high(int T, int A) {
  LL good=-1,bad=Inf;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx<=T?good:bad)=mid;
  }
  return good;
}

LL low(int T, int A) {
  LL good=Inf,bad=-1;
  while(abs(good-bad)>1) {
    LL mid=(good+bad)/2LL;
    LL fx=mid-mid%A;
    (fx>=T?good:bad)=mid;
  }
  return good;
}

// $ g++ -std=c++11 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
vector<LL> solve(int N, vector<LL> A) {
  LL l=2,h=2;
  for(int i=N-1; i>=0; --i) {
    l=low(l,A[i]);
    h=high(h,A[i]);
    if(l>h) return {};
  }
  return {l,h};
}

