  ll r = INFLL;
  while (r - l > 1)
  {
    ll piv = l + (r - l) / 2;
    auto re = f(piv, A);
    if (re > 2)
      r = piv;
    else if (re < 2)
      l = piv;
    else
    {
      l = piv;
      r = piv;
      break;
    }
  }
  if (l == r)
  {
    if (f(l, A) != 2)
    {
      cout << -1 << endl;
      return 0;
    }
  }
  ll lf = f(l, A);
  ll rf = f(r, A);
  if (lf < 2 && rf > 2)
  {
    cout << -1 << endl;
    return 0;
  }
  else
  {
    ll p;
    if (lf == 2)
      p = l;
    else if (rf == 2)
      p = r;
    else
    {
      cout << -1 << endl;
      return 0;
    }
    ll m, M;
    l = 2;
    r = p;
    while (r - l > 1)
    {
      ll piv = l + (r - l) / 2;
      if (f(piv, A) == 2)
        r = piv;
      else
        l = piv;
    }
    OUT2(l, r);

    if (f(l, A) == 2)
      m = l;
    else
      m = r;
    l = p;
    r = INFLL;
    while (r - l > 1)
    {
      ll piv = l + (r - l) / 2;
      if (f(piv, A) == 2)
        l = piv;
      else
        r = piv;
    }
    OUT2(l, r);
    if (f(r, A) == 2)
      M = r;
    else
      M = l;
    cout << m << " " << M << endl;
  }

  return 0;
}

