			const LL mid = (lo + hi) / 2;
			if ((mid / A[i])*A[i] >= lb)hi = mid;
			else lo = mid;
		}
		LL nl = hi;
		//cout << nl << " " << nu << endl;
		if (nu == 0 || nl > nu) {
			cout << -1 << endl;
			return 0;
		}
		lb = nl;
		ub = nu;
	}
	cout << lb << " " << ub << endl;
	return 0;
}

