ll bp1(ll a1, ll a, ll x) {
    ll l = -1, r = INF;
    while (r - l > 1) {
        ll m = (l + r) / 2;
        if (m * a1 / a >= x / a)
            r = m;
        else
            l = m;
    }
    return r;
}

ll bp2(ll a1, ll a, ll x) {
    ll l = 0, r = INF;
    while (r - l > 1) {
        ll m = (l + r) / 2;
        if (m * a1 / a > x / a)
            r = m;
        else
            l = m;
    }
    return l;
}

