	while(ok-ng > 1){
		LL m = (ng + ok) / 2;
		LL tmp = m;
		for(int i=0; i<K; i++){
			tmp -= tmp % A[i];
		}
		if(tmp >= 2) ok = m;
		else ng = m;
	}
	LL tmp = ok;
	for(int i=0; i<K; i++){
		tmp -= tmp % A[i];
	}
	if(tmp != 2) return -1;
	else return ok;
}

LL low(){
	LL ok = -1;
	LL ng = 100000000000002LL;
	while(ng-ok > 1){
		LL m = (ng + ok) / 2;
		LL tmp = m;
		for(int i=0; i<K; i++){
			tmp -= tmp % A[i];
		}
		if(tmp <= 2) ok = m;
		else ng = m;
	}
	return ok;
}

