    reverse(A.begin(), A.end());
    ll low = 2, high = 2;
    for (int i = 0; i < K; i++)
    {
        if (high % A[i] != 0 && low % A[i] != 0)
        {
            if ((high / A[i]) - (low / A[i]) == 0)
            {
                cout << -1 << endl;
                return;
            }
        }

        low = ceil(low, A[i]) * A[i];
        high = (high / A[i]) * A[i] + A[i] - 1;
    }
    cout << low << " " << high << endl;
}

int main()
{
    long long K;
    scanf("%lld", &K);
    std::vector<long long> A(K);
    for (int i = 0; i < K; i++)
    {
        scanf("%lld", &A[i]);
    }
    solve(K, std::move(A));
    return 0;
}

