int calc(const int start, const vector<int> &a) {
        int n = a.size();
        int val = start;
        for (int i = 0; i < n; i ++) {
                val = (int) (val / a[i]) * a[i];
        }
        if (val < 2) return 0;
        else if (val == 2) return 1;
        else return 2;
}

