#include <bits/stdc++.h>
using namespace std;

int k;
vector<long long> v;

bool can(long long n) {
    for (int i = 0; i < k; i++) {
        n -= (n % v[i]);
    }
    return (n == 2);
}

int main() {
    cin >> k;
    v.assign(k, 0LL);
    for (int i = 0; i < k; i++) cin >> v[i];

    if (v[k-1] != 2) {
        cout << -1 << endl;
        return 0;
    }

    long long lo = 2;
    for (int i = k-1; i >= 0; i--) {
        long long t = v[i];
        if (lo % t == 0) continue;
        lo = ((lo/t)+1)*t;
    }

    if (!can(lo)) {
        cout << -1 << endl;
        return 0;
    }

    long long ans1, ans2;
    ans1 = lo;

    long long hi = 2e10;
    while (lo <= hi) {
        long long mid = (lo+hi)/2;
        if (can(mid)) {
            ans2 = mid;
            lo = mid+1;
        } else {
            hi = mid-1;
        }
    }

    cout << ans1 << ' ' << ans2 << endl;
}

