//[l,r)で最小のaの倍数
//存在しなければ-1
ll f_min(ll l, ll r, ll a)
{
  ll Min = CEIL(l, a) * a;
  return Min >= r ? -1 : Min;
}

//[l,r)で最大のaの倍数
//存在しなければ-1
ll f_max(ll l, ll r, ll a)
{
  ll Max = r - r % a;
  if (Max == r)
    Max -= a;
  return Max < l ? -1 : Max;
}

