const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll k, as[MAX_N];
pl ps[MAX_N];

void dfs(ll idx){
    ll p1 = ps[idx + 1].e1, p2 = ps[idx + 1].e2;
    // p[i + 1] <= p[i] <= p[i + 1] + a[i] - 1
    // p[i + 1] % a[i] == 0

    if (p1 % as[idx] != 0) p1 = p1 + (as[idx] - p1 % as[idx]);
    if (p2 % as[idx] != 0) p2 -= p2 % as[idx];
    if (idx == 0){
        ps[0] = {p1, p2 + as[0] - 1};
        return;
    }

    ll p_cur = p1;
    if (p1 % as[idx - 1] == 0) ps[idx].e1 = p1;
    else ps[idx].e1 = p1 + (as[idx - 1] - p1 % as[idx - 1]);
    if (p2 % as[idx - 1] == 0) ps[idx].e2 = p2;
    else ps[idx].e2 = p2 + (as[idx - 1] - p2 % as[idx - 1]);

    prl3(idx, ps[idx].e1, ps[idx].e2);
    if (idx - 1 >= 0) dfs(idx - 1);
}

void solve(){
    rep(i, k) in1(as[i]);
    if (as[k - 1] != 2){
        prl(-1); return;
    }

    ps[k] = {2, 2};
    dfs(k - 1);

    prl2(ps[0].e1, ps[0].e2);
}

int main(void){
    in1(k);
    // assert(k <= 100000);
    solve();
    return 0;
}

