#define REP(i, n) FOR(i, 0, n)

#define ALL(f,c,...) (([&](decltype((c)) cc) { return (f)(begin(cc), end(cc), ## __VA_ARGS__); })(c))

#define GENERIC(f) ([](auto&&... args) -> decltype(auto) { return (f)(forward<decltype(args)>(args)...); })

#define MEMSET(a,v) memset((a), (v), sizeof(a))

#define DBG(x) DPRINTLN('L', __LINE__, ':', #x, ':', (x))
// }}}

s64 K;
vector<s64> A;

void ng() {
    PRINTLN(-1);
    EXIT();
}

void solve() {
    ALL(reverse, A);
    if(A.front() != 2) ng();

    s64 lo = 2;
    s64 hi = 3;
    FOR(i, 1, K) {
        s64 lo_nex = div_ceil(lo,A[i]) * A[i];
        s64 hi_nex = div_floor(hi,A[i]) * A[i] + A[i] - 1;

        if(lo_nex > hi_nex) ng();
        if(lo_nex > hi) ng();
        if(hi_nex < lo) ng();

        lo = lo_nex;
        hi = hi_nex;
        DBG(make_pair(lo, hi));
    }

    PRINTLN(lo, hi);
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(K);
    RD(A, K);



    solve();

    EXIT();
}

