    pair<long long, long long> tmp;
    for (int i = A.size() - 2; i >= 0; i--) {
        if (A[i] > ret.second) {
            std::cout << -1 << std::endl;
            return;
        }
        tmp.first = ((ret.first-1)/A[i] + 1)*A[i];
        tmp.second = (ret.second/A[i] + 1)*A[i] - 1;
        if (tmp.first > ret.second) {
            std::cout << -1 << std::endl;
            return;
        }
        if (tmp.second+1-A[i] < ret.first) {
            std::cout << -1 << std::endl;
