int k;
ll a[1000000];
ll amax=-1;
int mind;

bool judge(int n){
  for(int i=0;i<k;i++){
    if (n % a[i]==0){
      continue;
    }else{
      n=n-n%a[i];
    }
    if (n < 2){
      return false;
    }
  }
  if (n==2){
    return true;
  }else{
    return false;
  }
}

int main(){
  cin>>k;
  for(int i=0;i<k;i++){
    cin>>a[i];
    if (a[i]>amax){
      amax=a[i];
      mind=i;
    }
  }
  int mi=amax;
  for(int i=mind-1;i>=0;i--){
    int tmp=2;
    while(a[i]*tmp<mi){
      tmp++;
    }
    mi=a[i]*tmp;
  }
  if (!judge(mi)){
    cout<<-1<<endl;
    return 0;
  }
  ull prev=mi, ma=mi*mi;
  while(judge(ma)){
    prev=ma;
    ma*=ma;
  }
  ll ub=ma, ul=ma/prev, mid=(ub+ul)/2;
  while(1){
    bool judge1=judge(mid);
    if (judge1 && !judge(mid+1)){
      ma=mid;
      break;
    }
    if (judge1){
      ul=mid;
    }else{
      ub=mid;
    }
    mid = (ub+ul)/2;
  }
  cout<<mi<<" "<<ma<<endl;
  return 0;
}

