const int N = 100005;
lint a[N];

bool go(lint &tl, lint &th, lint x) {
	lint l, r;
	l = 1, r = 1e9;
	//tl이상이면서 x의 배수인 가장 작은 수 
	//th이하이면서 x의 배수인 가장 큰 수 
	lint a = 1e9+1;
	lint b = 0;
	while(l<=r) {
		lint m = (l+r)/2;
		if(tl<=x*m) {
			a = min(a, m);
			r = m-1;
		}
		else {
			l = m+1;
		}
	}
	l = 1, r = 1e9;
	while(l<=r) {
		lint m = (l+r)/2;
		if(x*m<=th) {
			b = max(b, m);
			l = m+1;
		}
		else {
			r = m-1;
		}
	}
	//printf("=>%lld %lld %lld %lld\n", tl, th, a*x, b*x);
	if(a>b) {
		return false;
	}
	tl = a*x;
	th = b*x+(x-1);
	return true;
}

int main() {
	int k;
	scanf("%d", &k);

	bool ok = true;
	lint tl = 2, th = 2;

	for(int i=0; i<k; i++) {
		scanf("%lld", a+i);
	}

	for(int i=0; i<k; i++) {
		lint x;
		x = a[k-1-i];
		if(!go(tl, th, x)) {
			ok = false;
			break;
		}
	}
	if(!ok) {
		printf("%lld", -1LL);
	}
	else {
		printf("%lld %lld\n", tl, th);
	}
	return 0;
}

