using namespace std;

typedef long long ll;

const ll INF = 1000000000000000000;
//              123456789012345678

#define SMALLER 1
#define LARGER 2

vector<int> A;

ll get ( ll cnt ) {
  for ( auto x : A ) {
    cnt = cnt - ( cnt % x );
  }

  return cnt;
}

ll Find ( ll L , ll R , int Predicate ) {

  while ( L + 1 < R ) {

    ll med = ( L + R ) / 2;

    ll res = get ( med );

    if ( Predicate == SMALLER ) {
      if ( res < 2 ) L = med;
      else R = med;
    }
    else { // LARGER
      if ( res > 2 ) R = med;
      else L = med;
    }

  }

  if ( Predicate == SMALLER ) {
    return L;
  }
  else {
    return R;
  }

}

