	rep(i, k){
		n /= (ll)a.at(i);
		n *= (ll)a.at(i);
	}
	if(n > 2) return 1;
	else if(n == 2) return 0;
	else return -1;
}

int b_serch(ll l, ll r, vector<int> &a, int k){
	while(abs(r - l) > 1){
		ll mid = (l+r)/2;
		if(func(mid, a, k) >= 0){
			r = mid;
		}else{
			l = mid;
		}
	}
	return r;
}

int b_serch2(ll l, ll r, vector<int> &a, int k){
	while(abs(r - l) > 1){
		ll mid = (l+r)/2;
		if(func(mid, a, k) <= 0){
			l = mid;
		}else{
			r = mid;
		}
	}
	return l;
}

