pair<ll, ll> get(ll cur, int modNow, int modPre) {
    ll low = cur, high = cur + modNow - 1;

    ll hh = (high / modPre) * modPre;
    if (hh < low) return nil;

    ll waoef = ((low + modPre - 1) / modPre) * modPre;

    return make_pair(waoef, hh);
}

