#define MAX_K (100000)
#define INF (1000000000000000000L)

long calc_final(const long *as, long k, long n) {
  long ret = n;
  for (int i = 0; i < k; i++) {
    ret = ret / as[i] * as[i];
  }
  return ret;
}

long calc_lb(long b, long e, const long *as, long k, long thresh) {
  if (e - b <= 1) {
    if (calc_final(as, k, b) >= thresh) {
      return b;
    } else {
      return -1;
    }
  }
  const long m = (b + e - 1) / 2, num = calc_final(as, k, m);
  if (num >= thresh) {
    return calc_lb(b, m + 1, as, k, thresh);
  } else {
    return calc_lb(m + 1, e, as, k, thresh);
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  long K, as[MAX_K];
  scanf("%ld", &K);
  for (int i = 0; i < K; i++) {
    scanf("%ld", &as[i]);
  }

  // solve
  const long ans_min = calc_lb(2, INF, as, K, 2);
  const long ans_max = calc_lb(2, INF, as, K, 3) - 1;
  if (calc_final(as, K, ans_min) == 2 && calc_final(as, K, ans_max) == 2) {
    printf("%ld %ld\n", ans_min, ans_max);
  } else {
    printf("-1\n");
  }

  return 0;
}

