int main()
{
    int K; cin >> K;
    vector<int> As(K); for (auto &Ai : As) cin >> Ai;
    // 試合を逆順に辿る：O(K)
    int min = 2, max = 2;
    for (int i = K - 1; i >= 0; --i)
    {
        int Ai = As[i];
        // [min, max]の範疇で考える
        // 最大想定人数であっても，1組も作れない場合，Nは存在しない
        if (max < Ai)
        {
            cout << -1 << endl;
            return 0;
        }
        // 組を作る前の最小人数は，[min, max]に含まれるAiの倍数の最小値
        min = min <= Ai ? Ai : (min + Ai - 1) / Ai * Ai;
        // 組を作る前の最大人数は，[min, max]に含まれるAiの倍数の最大値＋Ai-1
        max = max / Ai * Ai + Ai - 1;
    }
    cout << min << ' ' << max << endl;
}

