bool check(long long x, vector<long long> &a) {
	long long n = x;
	for (auto aaa : a) {
		x = x / aaa * aaa;
	}
	return x == 2;
}

int main() {
	int k;
	cin >> k;

	vector<long long> a(k, 0);
	for (int i = 0; i < k; i++) {
		cin >> a[i];
	}

	if (a.back() != 2) {
		cout << -1 << endl;
		return 0;
	}

	long long mini = a.back();

	for (int i = k - 2; i >= 0; i--) {
		if (a[i] >= 2 * mini) {
			cout << -1 << endl;
			return 0;
		}
		mini = max(mini, a[i]);
		if (mini % a[i] > 0) {
			mini = mini - (mini % a[i]) + a[i];
		}
	}
	if (!check(mini, a)) {
		cout << -1 << endl;
		return 0;
	}

	long long lower = mini;
	long long upper = 9e18;

	while (upper - lower > 1) {
		long long mid = (lower + upper) / 2;
		if (check(mid, a)) {
			lower = mid;
		} else {
			upper = mid;
		}
	}

	long long maxi = lower;
	cout << mini << " " << maxi << endl;
	return 0;
}

