bool read() {
    if (scanf("%d", &n) != 1)
        return false;

    for (int i = 0; i < n; ++i)
        scanf("%d", a + i);

    return true;
}

bool f(ll x) {
    for (int i = 0; i < n; ++i)
        x = (x / a[i]) * a[i];

    return x == 2;
}

void solve() {
    ll L = 2, R = 2;

    for (int i = n - 1; i >= 0; --i) {
        ll l = L, r = 228ll * inf;

        for (; l < r; ) {
            ll m = (l + r) / 2;

            if ((m / a[i]) * a[i] < L)
                l = m + 1;
            else
                r = m;
        }

        L = l;
        l = R, r = 228ll * inf;

        for (; l < r; ) {
            ll m = (l + r + 1) / 2;

            if ((m / a[i]) * a[i] <= R)
                l = m;
            else
                r = m - 1;
        }

        R = l;

        if (L > R) {
            printf("-1\n");
            return ;
        }
    }

    if (!f(L) || !f(R))
        printf("-1\n");
    else
        printf("%lld %lld\n", L, R);
}

