  for(int i = 2; i <= 10000000; i++){
    ll n = i;
    for(int j = 0; j < k; j++){
      n -= n % a[j];
    }
    if(n == 2){
      mi = min(mi, (ll)i);
      ma = max(ma, (ll)i);
    }
  }
  cout << to_string(mi) + " " + to_string(ma) << endl;
