    cin >> a[i];
  }

  if(a[k - 1] != 2){
    cout << -1 << endl;
    return 0;
  }

  ll min = 2;
  bool exist = true;
  for(int i = k - 1; i - 1 >= 0; i--){
    ll cand;
    if(a[i - 1] >= min){
      cand = a[i - 1];
    }
    else{
      if(min % a[i - 1] == 0){
        cand = min;
      }
      else{
        cand = a[i - 1] * (min / a[i - 1] + 1);
      }
    }
    if(min != a[i] * (cand / a[i])){
      exist = false;
      break;
    }
    min = cand;
  }

  if(!exist){
    cout << -1 << endl;
    return 0;
  }
  ll b = a[0];
  for(int i = 0; i < k; i++){
    if(a[i] != 1){
      b = a[i];
    }
  }
  cout << to_string(min) + " " + to_string((b * (min / b + 1) - 1)) << endl;

  if(DEBUG){
    check(k, a);
  }

  return 0;
}

