ll BinarySearch(ll ng, ll ok, function<bool(ll)> IsOK)
{
    while (abs(ng - ok) > 1)
    {
        const ll mid = (ng + ok) / 2;
        if (IsOK(g(mid))) ok = mid;
        else ng = mid;
    }
    return ok;
}

