int main(){
  int K,i,n,maxn,min,max,num;
  vector<int> A;

  cin >> K;
  A = vector<int>(K, 0);
  maxn = 0;
  min = 0;
  for (i = 0; i < K; i++){
    cin >> A[i];
  }
  for (i = 0; i < K; i++){
    maxn += (A[i] - 1);
  }
  for (n = 2; n < maxn; n++){
    num = n;
    for (i = 0; i < K; i++){
      num -= num % A[i];
      if(num < 2){
        break;
      }
    }
    if(num == 2){
      min = n;
      break;
    }
  }
  if(min == 0){
    cout << -1 << endl;
    return -1;
  }
  for (n = maxn; n > min; n--){
    num = n;
    for (i = 0; i < K; i++)
    {
      num -= num % A[i];
      if(num < 2){
        break;
      }
    }
    if(num == 2){
      max = n;
      break;
    }
  }
  cout << min << " " << max << endl;
}

