	rep(i,1,k)	cin>>a[i];
	ll x=2;
	rrep(i,k,2)
	{
		ll p=x/a[i],y=p*a[i],z=(p+1)*a[i];
		// (n[i]/a[i+1]) *a[i+1] =n[i+1]	
		// p=n[i]/a[i+1] = n[i+1]/a[i+1]
		//p为第i轮过后的人被分为多少组.
		// n[i]= p*a[i+1] +r   (0<=r<a[i+1])
