void check(int k, ll a[]){
  ll ma = -1, mi = 10000000;
  for(int i = 2; i <= 10000000; i++){
    ll n = i;
    for(int j = 0; j < k; j++){
      n -= n % a[j];
    }
    if(n == 2){
