    cin >> a[i];
  }

  ll min = 2;
  bool exist = true;
  for(int i = k - 1; i - 1 >= 0; i--){
    ll cand;
    if(a[i - 1] >= min){
      cand = a[i - 1];
    }
    else{
      if(min % a[i - 1] == 0){
        cand = min;
      }
      else{
        cand = a[i - 1] * (min / a[i - 1] + 1);
      }
    }
    if(min != a[i] * (cand / a[i])){
      exist = false;
      break;
    }
    min = cand;
  }

  if(!exist){
