#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
#define REP(i,n) for (ll i = 0; i < (n); ++i)

ll binary_search(
    ll lo, ll hi, function<bool(ll)> is_ok,
    bool maximize
){
    while(lo < hi){
        if(maximize){
            const ll mid = (lo + hi + 1) / 2;
            if(is_ok(mid)){
                lo = mid;
            }else{
                hi = mid - 1;
            }
        }else{
            const ll mid = (lo + hi) / 2;
            if(is_ok(mid)){
                hi = mid;
            }else{
                lo = mid + 1;
            }
        }
    }
    return lo;
}

void solve(long long K, std::vector<long long> A){
    // max
    ll ans_max = 2;
    for(ll i = K - 1; i >= 0; --i){
        if(ans_max % A.at(i) != 0){
            cout << -1 << endl;
            return;
        }
        ll nxt_max = ans_max + A.at(i) - 1;
        if(i > 0){
            nxt_max -= nxt_max % A.at(i - 1);
            if(nxt_max < ans_max){
                cout << -1 << endl;
                return;
            }
        }
        ans_max = nxt_max;
    }

    ll ans_min = binary_search(
        0, ans_max,
        [&](ll mid) -> bool {
            REP(i, K){
                mid -= mid % A.at(i);
            }
            return mid == 2;
        },
        false
    );

    cout << ans_min << ' ' << ans_max << endl;
}

