#define REP(i, n) for(int i=0; i<n; i++)

ll A[100100];
int K;

ll amin = INT_MAX;
ll amax = -1;

bool judge(ll n, bool lower){
    REP(i,K){
        n -= n%A[i];    
    }
    if(lower && n <= 2) return true;
    if(!lower && n >= 2) return true;
    return false;
}

int main(){
    cin >> K;
    ll amax = -1;
    REP(i,K){
        ll a;
        cin >> a;
        A[i] = a;
        amax = max(amax, a);
    }

    ll N = 2 + K*amax;

    ll left, right;
    left = 2;
    right = N;
    while(right - left >= 1){
        ll mid = (left+right)/2; 
        bool ok = judge(mid, true);
        if(ok) left = mid;
        else right = mid-1;
    }
    ll high = right;

    left = 2;
    right = N;
    while(right - left >= 1){
        ll mid = (left+right)/2; 
        bool ok = judge(mid, false);
        if(ok) right = mid;
        else left = mid+1;
    }
    ll low = right;

    if(high < low)
        cout << -1 << endl;
    else
        printf("%lld %lld\n", low, high);
    return 0;
}

