void search(int n){
	if(dp[n + 1].empty()){
		return;
	}
	for(auto&& c : dp[n + 1]){
		//ラウンドn終了時に残りc人である可能性があるなら開始時の人数を全てdp[n]に
		ll num = c;
		ll div = c / a[n];
		while(num < a[n] * (div + 1)){
			if(n == 0){
				dp[n].insert(num);
			}else if(num >= a[n-1] && num%a[n-1] == 0){
				dp[n].insert(num);
			}
			num++;
		}
	}
}

