bool find_negative_roop(V<P<P<int,int>,int>> a,V<int> b){
  V<int> d(b.sz,1),e;
  fo(i,3*b.sz){
    fo(j,a.sz){
      P<P<int,int>,int> c=a[j];
      if(b[c.ff]!=inf&&b[c.fs]>b[c.ff]+c.se){
        b[c.fs]=b[c.ff]+c.se;
        if(i>=b.sz-1&&d[c.ff]){
          d[c.ff]=0;
          e.pb(c.ff);
        }
        if(i>=b.sz-1&&d[c.fs]){
          d[c.fs]=0;
          e.pb(c.fs);
        }
      }
    }
  }
  if(e.sz==0)
  return 0;
  Union f(b.sz);
  fo(i,e.sz-1){
    f.unite(e[i],e[i+1]);
  }
  fo(j,b.sz){
  fo(i,a.sz){
    if(f.same(a[i].ff,e[0])){
      f.unite(e[0],a[i].fs);
    }
  }
  }
  if(f.same(e[0],b.sz-1))
    return 1;
  return 0;
}
//(親,現在地,現在の距離,最大距離,最大距離となる頂点,隣接リスト)
void tyokkei_init(int a,int b,int c,int &d,int &e,V<V<int>> &f){
  if(c>d){
    d=c;
    e=b;
  }
  fo(i,f[b].sz){
    if(f[b][i]==a)
      continue;
    tyokkei_init(b,f[b][i],c+1,d,e,f);
  }
}
//aは隣接リスト
int kinotyokkei(V<V<int>> &a){
  int b=0,c=0,d=0;
  tyokkei_init(-1,b,0,d,c,a);
  b=c,c=0,d=0;
  tyokkei_init(-1,b,0,d,c,a);
  return d;
  //直径となる2点はbとc
}
//aとbの距離、cは隣接リスト
int tree_kyori(int a,int b,V<V<int>> &c){
  if(a==b)
    return 0;
  Q<int> e;
  e.push(a);
  V<int> d(c.sz,inf);
  d[a]=0;
  while(!d.empty()){
    int f=e.front();
    e.pop();
    fo(i,c[f].sz){
      if(d[c[f][i]]==inf){
        d[c[f][i]]=d[f]+1;
        if(c[f][i]==b)
          return d[c[f][i]];
        e.push(c[f][i]);
      }
    }
  }
}
