using namespace std;

bool flag = 0;

int exch(int a,int b){
	if(a < b) {
		d cur = (d)b / (d)a;
		a = a * ((int)cur + 1);
		if(a >= 2 * b) flag = 1;
		return a;
	}
	else {
		if(a >= 2 * b) flag = 1;
		else return a;
	}
}

int special;
int A[MAXN];
int judge(int a,int b){
	if(a < b) {
		d cur = (d)b / (d)a;
		a = a * ((int)cur + 1);
		if(a == b) special /= 2;
		if(a >= 2 * b) return 0;
		return 1;
	}

	else {
		if(a == b) special /= 2;
		if(a >= 2 * b) return 0;
		else return 1;
	}
}



int main(){
	int K;
	scanf("%d",&K);
	for(int i = 1;i <= K;i++) scanf("%d",&A[i]);
	int cur = A[K];
	for(int i = K - 1;i >= 1;i--){
		cur = exch(A[i],cur);
		if(i == 2) special = cur;
		if(flag){
			printf("-1");
			return 0; 
		}
	}
	if(judge(special,cur)){
		printf("%d %d",cur,special * 2);	
	}
	return 0;
}

