int binary_search_min(bool func(ll),ll max,int min){

    int mid;
    while(max!=min){
        mid = (max+min)/2;
        if(func(mid)){
            max = mid;
        }else{
            min = mid+1; 
        }
    }
    return min;
}
int binary_search_max(bool func(ll),long long max,int min){

    ll mid;
    while(max!=min){
        mid = (max+min)/2+1;
        if(func(mid)){
            min = mid;
        }else{
            max = mid-1; 
        }
      //  cout << min <<endl;
    }
    return min;
}

