//関数
long ijo(long x,long a){//x以上で最小のaの倍数。a>=2
    if(x%a==0){
        return x;
    }else{
        return x-x%a+a;
    }
}

long ika(long x,long a){//x以下で最小のaの倍数。a>=2
    if(x%a==0){
        return x-x%a;
    }
}



