void solve(void)
{
  int K;
  cin>>K;
  vector<int> vec(K);
  for (int i = 0; i < K; i++)
  {
    cin>>vec[i];
  }
  reverse(ALL(vec));
  if(vec[0] != 2)
  {
    cout<<-1<<endl;
      return;
  }
  int L = 2,R = 3;

  for (int i = 0; i < K; i++)
  {

    int A = vec[i];
    // DEBUG(A,R);
    if(L == R)
    {
      cout<<-1<<endl;
      return;
      break;
    }
    L = ceil(double(L)/double(A))*A;
    R = floor(double(R-1)/double(A))*A + A ;

  }
  cout<<L<<" "<<R-1<<endl;






  return;
}

