int K;
long long int A[110000];

bool check1(long long int num){

	long long int ret = num;

	for(int i = 0; i < K; i++){
		ret -= (ret % A[i]);
	}

	if(ret >= 2){
		return true;
	}
	return false;
}

bool check2(long long int num){

	long long int ret = num;

	for(int i = 0; i < K; i++){
		ret -= (ret % A[i]);
	}

	if(ret > 2){
		return true;
	}
	return false;
}

long long int bin_search1(long long int lef, long long int rig){
	long long int middle = (lef + rig) / 2;
	if(rig - lef <= 1){
		if(check1(rig)){
			return rig;
		}else{
			return lef;
		}
	}
	if(check1(middle)){
		rig = middle;
	}else{
		lef = middle;
	}
	return bin_search1(lef, rig);
}

long long int bin_search2(long long int lef, long long int rig){
	long long int middle = (lef + rig) / 2;
	if(rig - lef <= 1){
		if(check2(rig)){
			return rig;
		}else{
			return lef;
		}
	}
	if(check2(middle)){
		rig = middle;
	}else{
		lef = middle;
	}
	return bin_search2(lef, rig);
}

int main(){

	cin >> K;

	for(int i = 0; i < K; i++){
		cin >> A[i];
	}

	long long int ans1 = bin_search1(1LL, 1000000000000000LL);
	long long int ans2 = bin_search2(1LL, 1000000000000000LL) - 1;

	bool flag = true;

	long long int ret = ans1;

	for(int i = 0; i < K; i++){
		ret -= (ret % A[i]);
	}

	if(ret != 2){
		flag = false;
	}

	ret = ans2;

	for(int i = 0; i < K; i++){
		ret -= (ret % A[i]);
	}

	if(ret != 2){
		flag = false;
	}

	if(flag){
		cout << ans1 << " " << ans2 << endl;
	}else{
		cout << "-1" << endl;
	}

	return 0;
}

