ll rem(ll val) {
    for(int i=1; i<=k; i++) {
        if(val % a[i] == 0) continue;
        else val -= val % a[i];
    }
    return val;
}

ll solveMax() {
    ll lo = 0, hi = 1e14, res = -1;
    int cnt = 500;

    while(cnt--) {
        ll mid = (lo + hi) / 2;
        if(rem(mid) == 2) res = mid;
        if(rem(mid) <= 2) lo = mid;
        else hi = mid;
    }

    return res;
}

ll solveMin() {
    ll lo = 0, hi = 1e14, res = -1;
    int cnt = 500;

    while(cnt--) {
        ll mid = (lo + hi) / 2;
        if(rem(mid) == 2) res = mid;
        if(rem(mid) < 2) lo = mid;
        else hi = mid;
    }

    return res;
}

