    cin>>k;

    for(int i=1; i <= k; i++) {
        cin>>a[i];
    }

    ll mx = solveMax(), mn = solveMin();

    if(mx == -1 || mn == -1) cout<<-1<<endl;
    else cout<<mn<<" "<<mx<<endl;
    return 0;
}

