typedef long long int ll;
typedef pair<ll, ll> pll;

#define FOR(i, n, m) for (ll(i) = (m); (i) < (n); ++(i))
#define REP(i, n) FOR(i, n, 0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll)1e15;

int N;
ll A[100005];

bool check(ll n)
{
    REP(i, N)
    {
        ll p = n / A[i];
        n = A[i] * p;
    }
    return n == 2;
}

int main()
{
    cin >> N;
    REP(i, N)
    {
        cin >> A[i];
    }
    //! とりあえず満たすものを1つ求める
    ll t = 2;
    REP(i, N)
    {
        //! t<=k<2*tを満たす最小のA[N-1-i]の倍数
        ll p = t / A[N - 1 - i];
        if (A[N - 1 - i] * (p + 1) > 2 * t)
        {
            cout << -1 << endl;
            return 0;
        }
        if (A[N - 1 - i] * (p + 1) < 2 * t)
            t = A[N - 1 - i] * (p + 1);
        else
            t = A[N - 1 - i] * p;
    }
    if (!check(t))
    {
        cout << -1 << endl;
        return 0;
    }

    //! 最小値と最大値を二分探索で見つける
    ll min = t;
    {
        ll ng = 0;
        while (abs(min - ng) > 1)
        {
            ll mid = (min + ng) / 2;
            if (check(mid))
            {
                min = mid;
            }
            else
            {
                ng = mid;
            }
        }
    }
    ll max = t;
    {
        ll ng = INF;
        while (abs(max - ng) > 1)
        {
            ll mid = (max + ng) / 2;
            if (check(mid))
            {
                max = mid;
            }
            else
            {
                ng = mid;
            }
        }
    }
    cout << min << " " << max << endl;
    return 0;
}

