#include <bits/stdc++.h>

using namespace std;

int findLoc(int ppl, const vector<int> &vals) {
	for (auto e: vals) {
		ppl = ppl - (ppl % e);
		if (ppl < 2) break;
	}
	if (ppl > 2) return 1;
	else if (ppl == 2) return 0;
	else return -1;
}

void solve(int ppl, const vector<int> &vals) {
	int worst = ppl;
	int best = ppl;
	while (findLoc(worst, vals) == 0) {
		worst--;
	}
	while (findLoc(best, vals) == 0) {
		best++;
	}
	cout << worst+1 << ' ' << best-1;
}

int main() {
	int K;
	cin >> K;
	vector<int> vals(K);
	for (auto &v: vals) {
		cin >> v;
	}
	auto l = 2u;
	auto r = 0x7FFFFFFFu;
	while (l <= r) {
		int mid = (l+r)/2;
		auto where = findLoc(mid, vals);
		if (where == 1) {
			r = mid-1;
		} else if (where == -1) {
			l = mid+1;
		} else {
			solve(mid, vals);
			return 0;
		}
	}
	cout << -1;
}

