  for (int i = 0; i < k; i++) {
    Read(a[i]);
    if (a[i] > a[maxi]) {
      maxi = i;
    }
  }

  ll lcm = 1;
  for (int i = 0; i < maxi; i++) {
    ll t = gcd(lcm, a[i]);
    lcm = (a[i] / t) * lcm;
  }

  ll u = ceil(a[maxi] / (double)lcm);
  ll x = lcm * u;

  ll y = x;
  for (int i = 0; i < k; i++) {
    if (y < a[i]) {
      y = 0;
    } else {
      y = y - (y % a[i]);
    }
  }

