  for (int i = maxi; i < k - 1; i++) {
    if (a[i] < a[i + 1]) {
      Print(-1);
      return 0;
    }
  }

  ll max_ = x;
  for (ll m = x + a[maxi] + 2 * lcm; m > x; m--) {
    ll w = m;
    for (int i = 0; i < k; i++) {
      if (w < a[i]) {
