#include  <cmath>
using namespace std;
using ll = int64_t;


ll reverse_game_max(ll i, const vector<ll>& as, ll n_i) {
  i--;
  if (n_i % as[i] != 0 ) {
    return -1;
  }
  if (i == 0) {
    ll num = n_i + as[0] - 1;
    return num;
  } else {
    for (ll j=as[i]-1; j>=0; j--) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_max(i, as, n_i + j);
      }
    }
    return -1;
  }
}

ll reverse_game_min(ll i, const vector<ll>& as, ll n_i) {
  i--;
  if (n_i % as[i] != 0 ) {
    return -1;
  }
  if (i == 0) {
    return n_i;
  } else {
    for (ll j=0; j<as[i]; j++) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_min(i, as, n_i + j);
      }
    }
    return -1;
  }
}

ll main() {
  ll k;
  cin >> k;
  if (k < 1 || pow(10, 5) < k) {
    cout << "-1";
    return 0;
  }
  vector<ll> a(k);
  for (auto & z : a) {
    cin >> z;
  }
  for (auto & z : a) {
    if (z < 2 || pow(10, 9) < z ) {
      cout << "-1";
      return 0;
    }
  }

  ll mini = reverse_game_min(k, a, 2);
  auto maxi = reverse_game_max(k, a, 2);
  if (mini < 0 || maxi < 0)
    cout << "-1";
  else
    cout << reverse_game_min(k, a, 2) << " " << reverse_game_max(k, a, 2);

  return 0;
}

