long long K, A[100000];

long long ans_min = 10000000000000000, ans_max = -1;


void solve(long long n, long long step, bool up){
    //printf("n = %lld, step = %lld\n", n, step);
    if(step == 1){
        if(n < ans_min){
            ans_min = n;
        }
        if(n+A[0]-1 > ans_max){
            ans_max = n+A[0]-1;
        }
        return;
    }
    long long d = (n + (A[step-2]-1))/A[step-2];
    if((!up) && d >= 1 && A[step-2]*d < n +A[step-1] ){
        solve(A[step-2]*d, step-1, false);
    }
    d = (n + A[step-1] - 1)/A[step-2];
    if(up && d >= 1){
        solve(A[step-2]*d, step-1, true);
    }
    /*for(int d = (n/A[step-1])*A[step-1]/A[step-2]; A[step-2] * d < (n/A[step-1] + 1)*A[step-1]; d++){
        if(A[step-2]*d >= (n/A[step-1])*A[step-1]){
            solve(A[step-2]*d, step-1);
        }
        }*/
}

int main(){
    cin >> K;
    for(int k = 0; k < K; k++){
        cin >> A[k];
    }

    if(A[K-1] > 2){
        cout << -1 << endl;
        return 0;
    }
    solve(2, K, true);
    solve(2, K, false);
    if(ans_max != -1){
        cout << ans_min << " " << ans_max << endl;
    }else{
        cout << -1 << endl;
    }
}

