using namespace std;

const int MAXK = 1E5;
int a[MAXK];

long long numGroups(long long A, long long B, long long k, bool upper)
{
    long long ans = 0;
    for (long long jump = 1E9; jump > 0; jump /= 2)
    {
        if (upper)
            while ((ans + jump) * B / A <= k)
                ans += jump;
        else
            while ((ans + jump) * B / A < k)
                ans += jump;
    }
    if (!upper)
        ans++;
    if (ans * B / A == k)
        return ans;
    return 0;
}

int main()
{
    int k;
    cin >> k;
    for (int i = 0; i < k; i++)
    {
        cin >> a[i];
    }
    if (a[k - 1] != 2)
        cout << -1 << endl;
    else
    {
        bool poss = true;
        long long bigGroups = 1;
        long long smallGroups = 1;
        for (int i = k - 2; i >= 0; i--)
        {
            bigGroups = numGroups(a[i + 1], a[i], bigGroups, true);
            smallGroups = numGroups(a[i + 1], a[i], smallGroups, false);
            if (bigGroups == 0)
                poss = false;
        }
        if (poss)
            cout << smallGroups * a[0] << " " << bigGroups * a[0] + (a[0] - 1) << endl;
        else
            cout << -1 << endl;
    }
    return 0;
}

