int K;
int a[MAXN];

pair <int, int> solve() {
    if (a[K - 1] != 2)
        return {-1, -1};

    int l = 2;
    int r = 3;
    for (int i = K - 2; i >= 0; i--) {
        // a[i] * dl >= l
        int dl = (l + a[i] - 1) / a[i];
        // a[i] * dr <= r
        int dr = r / a[i];
        if (dl == 0)
            dl = 1;
        if (dl > dr || dr == 0)
            return {-1, -1};
        l = dl * a[i];
        r = dr * a[i] + a[i] - 1;
    }
    return {l, r};
}

