                el = el * a[i-1];
                ll ell = (lb + a[i-1] - 1) / a[i-1];
                ell = ell * a[i-1];
                if(ell >= lb && ell <= rb && el <= rb && el >= lb){
                        L = min(el , ell);
                        R = max(el , ell);
                }else if(ell >= lb && ell <= rb) {
                        L = ell;
                        R = ell;
                }else if(el >= lb && el <= rb) {
                        L = el;
                        R = el;
                }else {
                        cout << "-1\n"; return 0;
                }
        }
        R = R + a[1] - 1;
        cout << L << " " << R << endl;
        return 0;
}

