	per(i,k-1){
		ll tmp=(res+a[i]-1)/a[i]*a[i];
		if(tmp/a[i+1]!=res/a[i+1])
			return -1;
		res=tmp;
	}
	return res;
}

string solve(vi a)
{
	ll mn=solve_min(a);
	if(mn==-1) return "-1";

	int k=a.size();
	ll mx=3;
	per(i,k-1)
		mx=mx/a[i]*a[i]+a[i]-1;
	return to_string(mn)+" "+to_string(mx);
}

