  reverse(v.begin(), v.end());

  long long n = 1;
  for (auto x : v) {
    n = next(n, x);
  }
  reverse(v.begin(), v.end());

  return n;
}

long long get_max(long long n, vector<int> &v) {
  long long lo = n, hi = 10LL * 1000 * 1000 * 1000;
  while (hi - lo > 1) {
    long long x = (lo + hi) / 2;
    bool good = check(x, 2, v);

    if (good) {
      lo = x;
    } else {
      hi = x;
    }
  }

  return lo;
}

