bool valid(const std::vector<int> &A, intmax_t m) {
  for (size_t i=0; i<A.size(); ++i)
    m -= m % A[i];

  return m == 2;
}

int main() {
  size_t K;
  scanf("%zu", &K);

  std::vector<int> A(K);
  for (size_t i=0; i<K; ++i)
    scanf("%d", &A[i]);

  if (A.back() != 2)
    return !printf("-1\n");

  intmax_t lb=1, ub=1e18;
  while (ub-lb > 1) {
    intmax_t mid=(lb+ub)>>1;
    (valid(A, mid)? lb:ub) = mid;
  }

  intmax_t max=lb;
  lb = 1;
  ub = max;
  while (ub-lb > 1) {
    intmax_t mid=(lb+ub)>>1;
    (valid(A, mid)? ub:lb) = mid;
  }

  intmax_t min=ub;
  if (min > max || max < 2)
    return !printf("-1\n");

  assert(valid(A, min) && valid(A, max));

  printf("%jd %jd\n", min, max);
}

