ll k;
ll a[100005];



ll solve1() {
	int i = k - 1;
	ll ret = 2;
	for (;; --i) {
		if (i < 0) return -1;
		if (a[i] == 2) {
			--i; break;
		}
	}
	for (; i >= 0; --i) {
		ll x = a[i];
		ll r = (ret + x - 1) / x * x;
		if (r / a[i+1] * a[i + 1] != ret) return -1;
		ret = r;
	}
	return ret;
}


ll solve2(ll r) {
	if (r == -1) return -1;
	return r+a[0]-1;
}
int main() {
	cin >> k;
	rep(i, k) cin >> a[i];

	ll r1 = solve1();
	ll r2 = solve2(r1);

	if (r1 == -1) {
		cout << -1 << endl;
		return 0;
	}
	cout << r1<<" "<<r2 << endl;


	//for (;;)getchar();

	return 0;
}

