    }
    if(a[k - 1] != 2){
        cout << -1 << endl;
        return 0;
    }
    reverse(a.begin(), a.end());
    ll mi = 2, ma = 3;
    FOR(i, 1, (int)k){
        // mi の更新　割る
        if(mi <= a[i]){
            mi = a[i];
        }else{
            ll tmp = mi / a[i];
            if(mi % a[i]) tmp++;
            mi = a[i] * tmp;
        }
        // maの更新 
        if(ma < a[i]){
            cout << -1 << endl;
            return 0;
        }
        ma = (ma / a[i] + 1) * a[i] - 1;
    }
    cout << mi << " " << ma << endl;
}

