const int maxn=100010;
const int inf=2e9;
int f[maxn],g[maxn],A[maxn];
int main() {
	int n=read();
	rep(i,1,n) A[i]=read();
	f[n]=g[n]=2;
	if(2%A[n]) {puts("-1");return 0;}
	dwn(i,n,1) {
		int l,r,x=inf,y=-inf,k=A[i-1],vx,vy;
		if(i==1) {
			f[i-1]=f[i];
			g[i-1]=g[i]+A[i]-1;
			continue;
		}
		l=f[i];r=f[i]+A[i]-1;
		vx=((l-1)/k+1)*k;vy=r/k*k;
		if(vx<=vy) x=min(x,vx),y=max(y,vy);
		l=g[i];r=g[i]+A[i]-1;
		vx=((l-1)/k+1)*k;vy=r/k*k;
		if(vx<=vy) x=min(x,vx),y=max(y,vy);
		if(x>y) {puts("-1");return 0;}
		f[i-1]=x;g[i-1]=y;
	}
	printf("%d %d\n",f[0],g[0]);
	return 0;
}

