int valid(int n, vector<int> const &a)
{
    rep(i,0,sz(a))
    {
        if (n < 2)
            return -1;
        n -= n%a[i];
    }
    if (n == 2)
        return 0;
    return 1;
}

int bsMin(int st, int end, vector<int> const &a)
{
    while (st < end)
    {
        int mid = st + (end - st) / 2;
        if (valid(mid, a) == 0)
            end = mid;
        else if (valid(mid, a) == 1)
            end = mid - 1;
        else if (valid(mid, a) == -1)
            st = mid + 1;
    }
    return st;
}

int bsMax(int st, int end, vector<int> const &a)
{
    while (st < end)
    {
        int mid = st + (end - st + 1) / 2;
        if (valid(mid, a) == 0)
            st = mid;
        else if (valid(mid, a) == 1)
            end = mid - 1;
        else if (valid(mid, a) == -1)
            st = mid + 1;
    }
    return st;
}

