int main(){
  ll n; cin >> n;
  ll a[n];
  for(ll i=0;i<n;i++) cin >> a[i];
  ll minres[n+1], maxres[n+1];
  minres[n]=2; maxres[n]=2;
  if(a[n-1] != 2){
    cout << -1 << endl;
    return 0;
  }
  for(ll i=n-1;i>=1;i--){
    // compute minres[i]
    ll x;
    if(minres[i+1] %a[i-1]==0) x = minres[i+1]/a[i-1];
    else x = minres[i+1]/a[i-1] + 1;
    if(a[i-1]*x >= minres[i+1]+a[i]){
      cout << -1 << endl;
      return 0;
    }else{
      minres[i] = a[i-1]*x;
    }
    // compute maxres[i]
    ll y;
    if((maxres[i+1]+a[i]) %a[i-1]==0) y = (maxres[i+1]+a[i])/a[i-1] - 1;
    else y = (maxres[i+1]+a[i])/a[i-1];
    maxres[i] = a[i-1]*y;
  }
  minres[0] = minres[1];
  maxres[0] = maxres[1]+a[0]-1;
  cout << minres[0] << " " << maxres[0] << endl;
}

