    for (int i = 0; i < k; i++) {
        n -= (n % v[i]);
    }
    return (n == 2LL);
}

int main() {
    cin >> k;
    v.assign(k, 0LL);
    for (int i = 0; i < k; i++) cin >> v[i];

    if (v[k-1] != 2LL) {
        cout << -1 << endl;
        return 0;
    }

    long long lo = 2LL;
    for (int i = k-1; i >= 0; i--) {
        long long t = v[i];
        if (lo % t == 0) continue;
        lo = ((lo/t)+1LL)*t;
    }

    if (!can(lo)) {
        cout << -1 << endl;
        return 0;
    }

    long long ans1, ans2;
    ans1 = lo;

    long long hi = 1000000000000LL;
    while (lo <= hi) {
        long long mid = (lo+hi)/2LL;
        if (can(mid)) {
            ans2 = mid;
            lo = mid+1LL;
        } else {
            hi = mid-1LL;
        }
    }

    cout << ans1 << ' ' << ans2 << endl;
}

