	return (x / k + 1) * k; 
}

void Solve() {
	int n;
	cin >> n;

	vector<int> a(n+1);

	for (int i = 1; i <= n; ++i) {
		cin >> a[i];
	}

	int64 minv = 2, maxv = 2;

	for (int i = n; i >= 1; --i) {
		minv = FirstMultipleGreaterThan(minv - 1, a[i]);
		maxv = FirstMultipleGreaterThan(maxv, a[i]) - 1;
		if (minv > maxv) {
			cout << -1 << "\n";
			return;
		}
	}

	cout << minv << " " << maxv << "\n";
}

int main() {
	int tests = 1;
	for (;tests; --tests) {
		Solve();
	}
}

