            tmp -= tmp%A[i]; 
        }
        if(tmp<=2) minnl = mid;
        else minnr = mid;
    }

    ll maxnl = 0, maxnr = MAXINF;
    while(maxnr-maxnl > 1){
        ll mid = (maxnr+maxnl) / 2;

        ll tmp = mid;
        REP(i, K){
            tmp -= tmp%A[i]; 
        }
        if(tmp>=2) maxnr = mid;
        else maxnl = mid;
    }

    if(maxnr > minnl){
        pr(-1);
        return 0;
    }
    pr(maxnr, minnl);
}

