ll reverse_game_max(ll i, const vector<ll>& as, ll n_i) {
  i--;
  if (n_i % as[i] != 0 ) {
    return -1;
  }
  if (i == 0) {
    ll num = n_i + as[0] - 1;
    return num;
  } else {
    for (ll j=as[i]-1; j>=0; j--) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_max(i, as, n_i + j);
      }
    }
    return -1;
  }
}

ll reverse_game_min(ll i, const vector<ll>& as, ll n_i) {
  i--;
  if (n_i % as[i] != 0 ) {
    return -1;
  }
  if (i == 0) {
    return n_i;
  } else {
    for (ll j=0; j<as[i]; j++) {
      if ((n_i + j) % as[i-1] == 0) {
        return reverse_game_min(i, as, n_i + j);
      }
    }
    return -1;
  }
}

