bool isok1(ll x, vector<int> &A) {
    int K = A.size();
    for (int i = 0; i < K && x >= 2; ++i)
        x -= x % A[i];
    return x >= 2;
}

ll misearch(vector<int> &A) {
    ll ok = 1e15, ng = 1;
    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        (isok1(mid, A) ? ok : ng) = mid;
    }
    return ok;
}

bool isok2(ll x, vector<int> &A) {
    int K = A.size();
    for (int i = 0; i < K && x > 2; ++i)
        x -= x % A[i];
    return x <= 2;
}

ll masearch(vector<int> &A) {
    ll ok = 1, ng = 1e15;
    while (abs(ok - ng) > 1) {
        ll mid = (ok + ng) / 2;
        (isok2(mid, A) ? ok : ng) = mid;
    }
    return ok;
}

