	if(ans == -1) {
		cout << -1 << endl;
		return 0;
	}
	l = ans;
	r = 2e16;
	ll ans2 = 0;
	while(l <= r) {
		ll md = (l+r)/2LL;
		ll cnt = f(md);
		if(cnt == 2) ans2 = md;
		if(cnt > 2) {
			r=md-1;
		}
		else { l=md+1; }
	}	
	cout << ans << ' ' << ans2 << endl;
}

