    ll lo = kl, hi = 1e17;
    while(1){
        if(hi-lo==1){
            if(possible(lo)) return lo;
            if(possible(hi)) return hi;
            return -1;

        }
        ll mid = (hi+lo)>>1;
        if(possible(mid)) hi = mid;
        else lo = mid;
    }
}

ll upper_bound(){
