bool solve(ll a, t2 &range)
{
    ll rmin = get<0>(range);
    ll rmax = get<1>(range);

    if ((rmin % a) && (rmax % a) && (rmin / a == rmax / a)) {
        return false;
    }

    ll next_rmin = ((rmin % a) ? ((rmin / a + 1LL) * a) : rmin);
    ll next_rmax = ((rmax % a) ? ((rmax / a) * a) : rmax) + (a - 1LL);
    if (next_rmin > next_rmax) {
        return false;
    }

    range = t2(next_rmin, next_rmax);
}

int _main()
{
    ll acnt; llin(acnt);
    V<ll> alist; llina(alist, acnt);

    reverse(ALL(alist));
    t2 range = t2(2LL, 2LL);

    for (auto a : alist) {
        bool success = solve(a, range);
        if (!success) {
            cout << -1 << endl;
            return 0;
        }
    }

    cout << get<0>(range) << " " << get<1>(range) << endl;

    return 0;
}

