using namespace std;
pii rec(int n, int* arr) {
    if (debug) cout << n << ' ' << arr[0] << endl;
    if (n == 1 && arr[0] == 2) {
        pii initial = make_pair(2, 3);
        return initial;
    }
    pii bad = make_pair(-1, -1);
    pii minmax = rec(n-1, arr+1);
    if (minmax.first == -1) {
        return bad;
    }

    if (debug) cout << n << ' ' << arr[0] << ' ' << minmax.first << ' ' << minmax.second << endl;
    int head = arr[0];
    int lower = minmax.first;
    if (lower % head) {
        int diff = head - (lower % head);
        if (diff >= arr[1]) return bad;
        lower += diff;
    }
    int upper = minmax.second;
    if (upper % head) upper -= upper % head;
    if (lower > minmax.second || upper < minmax.first) {
        return bad;
    }
    upper += head - 1;
    minmax = make_pair(lower, upper);
    return minmax;
}

int main(void)
{
    int k;
    cin >> k;
    int* a = new int[k];
    REP(i,k) READ(a[i]);

    if (a[k-1] != 2) {
        cout << "-1" << endl;
        return 0;
    }

    pii answer = rec(k, a);

    if (answer.first == -1) {
        cout << "-1" << endl;
    } else {
        cout << answer.first << ' ' << answer.second << endl;
    }

    delete[] a;
    return 0;
}

