LL minn(LL min, LL n) {
	if (min%n >= 1) {
		return min - min % n + n;
	}
	else {
		return min;
	}
}

LL maxn(LL max, LL n) {
	if (max%n >= 1) {
		return max - max % n;
	}
	else {
		return max;
	}
}

