#define MAX_K (100000)
#define INF (1000000000000000000L)

#define ROUNDUP(n, k) ((((n) + (k)-1) / (k)) * (k))

using namespace std;

void solve(long *as, int k, long cur, long *m, long *M) {
  if (k == 0) {
    *m = min(*m, cur);
    *M = max(*M, cur + as[0] - 1);
    return;
  }
  const long a_cur = as[k], a_prev = as[k - 1];
  // prev is one of cur, cur + 1, ..., cur + a_cur - 1
  // and is divisible by a_prev
  for (long i = ROUNDUP(cur, a_prev); i < cur + a_cur; i += a_prev) {
    solve(as, k - 1, i, m, M);
  }
}

int main(int argc, char *argv[]) {
  // read inputs
  long K, as[MAX_K];
  scanf("%ld", &K);
  for (int i = 0; i < K; i++) {
    scanf("%ld", &as[i]);
  }

  // solve
  long m = INF, M = -INF;
  solve(as, K - 1, 2, &m, &M);
  if (m < INF && M > -INF) {
    printf("%ld %ld\n", m, M);
  } else {
    printf("-1\n");
  }

  return 0;
}

