typedef long long ll;

const int MAXK = 1e5+1;
int A[MAXK], K;
bool prop;
ll middle(ll x, ll y) {
    return (x+y)/2;
}

bool p(ll x, int maximizing = 0) {
    FOR(i,0,K) {
        x /= A[i];
        x *= A[i];
    }
    if (maximizing) return x <= 2 && prop;
    return x >= 2 && prop;
}

bool good(ll x) {
    FOR(i,0,K) {
        x /= A[i];
        x *= A[i];
    }
    return x == 2 && prop;
}

int main() {
    ri(K);
    FOR(i,0,K) ri(A[i]);
    prop = (A[K-1] == 2);
    // find minimum
    ll lo=1, hi=1e14;
    while (lo < hi) {
        ll mid = middle(lo,hi);

        if (p(mid)) {
            hi = mid;
        } else {
            lo = mid+1;
        }
    }
    ll minim=-1;
    if (good(lo)) minim = lo;

    // find maximum
    lo=2, hi=1e14+1;
    while(lo<hi-1) {
        ll mid = middle(lo,hi);
        if (p(mid, 1)) {
            lo = mid;
        } else {
            hi = mid-1;
        }
    }
    ll maxim = lo;
    if (good(hi)) maxim = hi;
    if (minim == -1) {
        printf("-1\n");
    } else {
        printf("%lld %lld\n", minim, maxim);
    }

}

