LL bigmod(LL b,LL p,LL m)
{
    if( p == 0 ) return 1;
    LL ret = bigmod(b,p/2,m);
    ret = ( ret * ret ) % m;
    if( p & 1 ) ret = ( ret * b ) % m;
    return ret;
}

LL n,ara[1000005];

void solve()
{
    if( ara[n] != 2 ) return;
    LL l = 2, r = 3;
    for(int i = n - 1; i >= 1; i--)
    {
        LL mx = r / ara[i];
        LL mn = l / ara[i];
        if( l % ara[i] ) mn++;
        if( mn > mx ) return;
        LL new_l = ara[i] * mn;
        LL new_r = ara[i] * mx + ara[i] - 1;
        l = new_l;
        r = new_r;
    }
    printf("%lld %lld\n",l,r);
    exit(0);
}

