const LLONG MOD = 1000000007;

int main()
{
    int K; cin >> K;
    vector<int> As(K); for (auto &Ai : As) cin >> Ai;
    // 試合を逆順に辿る：O(K)
    int min = 2, max = 2;
    for (int i = K - 1; i >= 0; --i)
    {
        int Ai = As[i];
        // [min, max]にAiの倍数が含まれない場合は失敗
        if (max - min < Ai && (min % Ai) < (max % Ai))
        {
            cout << -1 << endl;
            return 0;
        }
        // 組を作る前の最小人数は，[min, max]に含まれるAiの倍数の最小値
        min = (min + Ai - 1) / Ai * Ai;
        // 組を作る前の最大人数は，[min, max]に含まれるAiの倍数の最大値＋Ai-1
        max = max / Ai * Ai + Ai - 1;
    }
