#include <bits/stdc++.h>

using namespace std;

int findLoc(long long ppl, const vector<int> &vals) {
	for (auto e: vals) {
		ppl = ppl - (ppl % e);
		if (ppl < 2) break;
	}
	if (ppl > 2) return 1;
	else if (ppl == 2) return 0;
	else return -1;
}

void solve(long long ppl, const vector<int> &vals) {
	// int worst = ppl;
	// int best = ppl;

	auto l = ppl;
	auto r = 0x7FFFFFFFFFFF;
	while (l <= r) {
		auto mid = (l+r)/2;
		auto where = findLoc(mid, vals);
		if (where == 1) {
			r = mid-1;
		} else if (where == 0) {
			l = mid+1;
		}
	}
	auto best = (l+r)/2;

	l = 2;
	r = ppl;
	while (l <= r) {
		auto mid = (l+r)/2;
		auto where = findLoc(mid, vals);
		if (where == 0) {
			r = mid-1;
		} else if (where == -1) {
			l = mid+1;
		}
	}
	auto worst = 1 + ((l+r)/2);
	cout << worst << ' ' << best;
}

int main() {
	int K;
	cin >> K;
	vector<int> vals(K);
	for (auto &v: vals) {
		cin >> v;
	}
	long long l = 2;
	long long r = 0x7FFFFFFFFFFF;
	while (l <= r) {
		auto mid = (l+r)/2;
		auto where = findLoc(mid, vals);
		if (where == 1) {
			r = mid-1;
		} else if (where == -1) {
			l = mid+1;
		} else {
			solve(mid, vals);
			return 0;
		}
	}
	cout << -1;
}

