ll ans;

ll a[100000];
ll ans1, ans2;
void solve(){
  int n=ini;
  REP(i,n)a[i]=ini;
  ll ml,mr,Ml,Mr;
  ml=mr=Ml=Mr=2;
  RREP(i,n) {
    ll x=a[i];
    // calc min
    ll c=(ml/x)*x;
    if(c<ml) c+=x;
    if(ml<=c&&c<=mr){
      ml=c;mr=c+x-1;
    } else {
      c = (Ml/x)*x;
      if(c<Ml) c+=x;
      if(Ml<=c&&c<=Mr) {
        ml=c;mr=c+x-1;
      } else {
        ans1=-1;
        return;
      }
    }

    // calc max
    c=(Mr/x)*x;
    if(Ml<=c) {
      Ml=c;Mr=c+x-1;
    }else{
      c=(mr/x)*x;
      if(ml<=c){
        Ml=c;Mr=c+x-1;
      }else {
        ans1=-1;
        return;
      }
    }
  }
  ans1=ml;
  ans2=Mr;
}
int main() {
  solve();
  if(ans1<0) {
    cout << -1 << endl;
  }else{
    cout << ans1 << " " << ans2 << endl;
  }
}

