long long roundDown(long long a, long long b) {
	return a - (a % b);
}

long long roundUp(long long a, long long b) {
	if(a % b == 0) {
		return a;
	} else {
		return roundDown(a, b) + b;
	}
}

int main(void) {
	int K;
	vector<long long> A;
	cin >> K;
	for(int i = 0; i < K; ++i) {
		long long t;
		cin >> t;
		A.push_back(t);
	}
	long long dpmax = 2;
	long long dpmin = 2;
	for(int i = K - 1; i >= 0; --i) {
		//A[i]が区間[dpmin, dpmax]に含まれているかどうか
		if(roundUp(dpmin, A[i]) <= roundDown(dpmax, A[i])) {
			dpmin = roundUp(dpmin, A[i]);
			dpmax = roundDown(dpmax, A[i]) + A[i] - 1;
		} else {
			cout << "-1\n";
			return 0;
		}
	}
	cout << dpmin << ' ' << dpmax << '\n';
	return 0;
}

