ll M(ll s, ll e, ll t){
    if(s < t) return -1;
    ll k = e % t;
    if(s <= e - k) return e-k;
    else -1;
}

ll N(ll s, ll e, ll t){
    if(s < t) return -1;
    ll k = s % t;
    if(e >= s + ((t-k)%t)) return s + ((t-k)%t);
    else -1;
}

