// check(low) -> NG, check(high) -> OK
ll bisectionl(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return high;
	ll mid = (high + low) / 2;
	if (check(mid)) return bisectionl(low, mid, check);
	else            return bisectionl(mid, high, check);
}
// check(low) -> OK, check(high) -> NG
ll bisectionr(ll low, ll high, std::function<bool(ll)> check) {
	if (high - low == 1) return low;
	ll mid = (high + low) / 2;
	if (check(mid)) return bisectionr(mid, high, check);
	else            return bisectionr(low, mid, check);
}

