int64_t K;
const int64_t MAX_K = 1e5 + 10;
int64_t A[MAX_K] = {};
const int64_t INF = 1e15;

int64_t calc(int64_t N) {
    for (int i = 1; i <= K; i++) {
        N -= N%A[i];
    }
    return N;
}

int main(int argc, char **argv) {
    std::cin >> K;
    for (int i = 1; i <= K; i++) {
        std::cin >> A[i];
    }
    auto cs = binary_search(2, INF, [&](int64_t n){
        return calc(n) <= 2;
    });
    cs = binary_search(cs, [&](int64_t n){
        return 2 <= calc(n);
    });
    if (cs.valid) {
        std::cout << cs.begin << " " << cs.end << std::endl;
    } else {
        std::cout << -1 << std::endl;
    }
}

