    ll lb = 2, ub = 2;
    ll crt = 0;
    auto lcomp = [&](ll mid){
        return (lb <= mid * crt);
    };
    auto ucomp = [&](ll mid){
        return (mid * crt <= ub);
    };
    for(ll i = 0; i < A.size(); ++i){
        crt = A[i];
        ll tlb = minimize(0, 1e15, lcomp);
        ll tub = maximize(0, 1e15, ucomp);
        lb = crt * tlb; ub = tub * crt  + crt - 1;
    }
    if(lb > ub) return puts("-1") * 0;
    cout << lb << " " << ub << endl;
}

