long binary_search_min(long maxval){
	long middle,minv = loINF;
	long l = 0;
	long r = maxval;
	long ans;
	long iter = 0;
	while (l <= r){
		middle = (l + r) / 2;
		ans = simulate(middle);
		#ifdef DEBUG
		 dump(middle);
		 dump(ans);
		#endif

		if (ans == 2) minv = min(middle,minv); 
		if(ans >= 2) r = middle;
		else l = middle+1;
	}

	return minv;
}

long binary_search_max(long maxval){
	long middle,maxv = -1;
	long l = 0;
	long r = maxval;
	long ans;
	long iter = 0;
	while (l <= r){
		middle = (l + r) / 2;
		ans = simulate(middle);

		if (ans == 2) maxv = max(middle,maxv);

		if(ans <= 2) l = middle + 1;
		else r = middle;
	}

	return maxv;
}


