void dfs(int t, int num)
{
	if(t==0){
		maxans=max(num,maxans);
		minans=min(num,minans);
		flag=1;
		return ;
	}
	if(num%a[t]==0)
		for(int i=0; i<a[t]; i++)
			dfs(t-1, i+num);
	return ;
}

