pair<int, int> solve(int mi, int ma, int i){
    // cout << mi << " " << ma << endl;
    if (i < 0){
        return make_pair(mi, ma-1);
    }
    if(mi < 0 or ma < 0){ return make_pair(-1, -1); }
    int nmi, nma;
    nmi = mi/a[i] + (mi%a[i]? 1 : 0);
    // nmi = ceil((float)mi / a[i]);
    nma = (ma-1) / a[i];
    if(nmi > nma){ return make_pair(-1, -1); }
    return solve(nmi*a[i], (nma+1)*a[i], i-1);
}
