int main() {

    LL K;
    cin >> K;

    vector<LL> A(K);
    for (int i = 0; i < K; i++) cin >> A[i];

    reverse(A.begin(), A.end());

    if (A[0] != 2) {
        cout << -1;
        return 0;
    }

    LL minV = A[0];
    for (int i = 0; i < K - 1; i++) {
        LL d = minV + (A[i] - 1);
        LL f = (minV / A[i + 1]) * A[i + 1];
        if (minV % A[i + 1]) f += A[i + 1];
        if (f > d) {
            cout << -1;
            return 0;
        }
        minV = f;
    }

    LL maxV = 2 * A[0] - 1;
    for (int i = 0; i < K - 1; i++) {
        LL t = maxV / A[i + 1];
        LL d = t * A[i + 1];
        maxV = d + A[i + 1] - 1;
    }


    cout << minV << " " << maxV << endl;


    return 0;
}

