int min_multiple(int l,int r,int k)
{
	if (l%k==0)  return l;
	else
	{
		int kk=((l/k)+1)*k;
		if (kk<=r)  return kk;
		else return -1;
	}
}

int max_multiple(int l,int r,int k)
{
	if (r%k==0)  return r;
	else
	{
		int kk=(r/k)*k;
		if (kk>=l)  return kk;
		else return -1;
	}
}

