ll maxValue = 2 + maxK*maxAi;

ll simulate(ll x) {
	for (ll i = 0; i < K; i++) {
		x /= A[i];
		x *= A[i];
	}
	return x;
}

ll searchMax() {
	//simulate(x)<=2となる最大値
	ll min = 0, max = maxValue, x = (min + max) / 2, gx;
	while (1) {
		if (simulate(x) <= 2) { 
			min = x;
			x = (min + max) / 2;
		}
		else {
			max = x;
			x = (min + max) / 2;
		}
		if ((max - min) <= 1) {
			if (simulate(max) <= 2)return max;
			else return min;
		}
	}
}

ll searchMin() {
	//simulate(x)>=2となる最小値
	ll min = 0, max = maxValue, x = (min + max) / 2, gx;
	while (1) {
		if (simulate(x) >= 2) {
			max = x;
			x = (min + max) / 2;
		}
		else {
			min = x;
			x = (min + max) / 2;
		}
		if ((max - min) <= 1) {
			if (simulate(min) >= 2)return min;
			else return max;
		}
	}
}


int main() {
	cin >> K;
	for (ll i = 0; i < K; i++) {
		cin >> A[i];
	}

	ansMax = searchMax();
	ansMin = searchMin();

