ll go1 (ll val, ll a, ll l, ll r) {
	ll bot = 0, top = 1e18;
	ll res = -1;
	while (bot <= top) {
		ll mid = (bot + top)>>1;

		if ( (mid - mid%a) >= val) {
			res = mid;
			top = mid - 1;
		} else {
			bot = mid + 1;
		}
	}

	ll ans = (res - res%a);
	if (ans < l or ans > r)
		res = -1;

	if (res == -1) {
		cout << -1 << endl;
		exit(0);
	}

	return res;
}

ll go2 (ll val, ll a, ll l, ll r) {
	ll bot = 0, top = 1e18;
	ll res = -1;
	while (bot <= top) {
		ll mid = (bot + top)>>1;
		if ( (mid - mid%a) <= val) {
			res = mid;
			bot = mid + 1;
		} else {
			top = mid - 1;
		}
	}

	ll ans = (res - res%a);
	if (ans < l or ans > r)
		res = -1;

	if (res == -1) {
		cout << -1 << endl;
		exit(0);
	}

	return res;
}

