pair<ll,ll> solveMany(ll a, ll l, ll r) {
	ll cl = (
		(l%a==0)?l/a:(l/a+1)
		);
	ll cr = r/a;
	return (cl<=cr?
			make_pair(cl*a,cr*a+a-1)
			:
			bad);
}

