        lo = 0;
        for (int j = 0; j < 100; j++) {
            ma = (hi + lo) / 2;
            ll tmp = ma;
            for (int i = 0; i < k; i++) {
                ll remain = tmp % a[i];
                tmp -= remain;
            }
            if (tmp > 2) {
                hi = ma;
            }
            else {
                lo = ma;
            }
        }
        if (mi < ma) {
            out << mi << ' ' << ma << '\n';
        }
        else {
