#include <stdio.h>
#include <stdlib.h>

#define MAX_N (100000)
#define INF (2000000000)

int calc_final(const int *as, int n, int k) {
  int ret = k;
  for (int i = 0; i < n; i++) {
    ret = ret / as[i] * as[i];
  }
  return ret;
}

int main(int argc, char *argv[]) {
  // read inputs
  int N, as[MAX_N];
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    scanf("%d", &as[i]);
  }

  // solve
  // calc min
  int b = 2, e = INF, num;
  int ans_min = -1;
  while (e - b > 1) {
    const int m = (b + e - 1) / 2;
    num = calc_final(as, N, m);
    if (num >= 2) {
      e = m + 1;
    } else {
      b = m + 1;
    }
  }
  if (num == 2) {
    ans_min = b;
  } else {
    ans_min = -1;
  }
  // calc max
  b = 2, e = INF, num;
  int ans_max = -1;
  while (e - b > 1) {
    const int m = (b + e - 1) / 2;
    num = calc_final(as, N, m);
    if (num >= 3) {
      e = m + 1;
    } else {
      b = m + 1;
    }
  }
  if (calc_final(as, N, b - 1) == 2) {
    ans_max = b - 1;
  } else {
    ans_max = -1;
  }
  if (ans_min > 0 && ans_max > 0) {
    printf("%d %d\n", ans_min, ans_max);
  } else {
    printf("-1\n");
  }

  return 0;
}

