void solve() {
    ll n;
    cin >> n;
    vll a(n);
    for(ll i = 0; i < n; i++) cin >> a[i];
    reverse(a.begin(), a.end());
    if(a[0] != 2) {
        cout << -1 << endl;
        return;
    }
    vll l(n + 1), r(n + 1);
    l[0] = r[0] = 2;
    for(ll i = 0; i < n; i++) {
        l[i + 1] = ((l[i] - 1) / a[i] + 1) * a[i];  // min multiple between l[i] and r[i]
