ii solve(int K, vi& a) {
    int lo = 2, hi = 2;
    reverse(ALL(a));
    for (int mod : a) {
        // [lo, hi]
        if (hi < mod) return ii(-1,-1);
        int nlo = lo - (lo % mod);
        if (nlo < lo) nlo += mod;
        if (nlo > hi) return ii(-1,-1);

        int nhi = hi - (hi % mod);
        if (nhi < nlo) return ii(-1,-1);

        lo = nlo; hi = nhi + (mod-1);
    }
    return ii(lo, hi);
}

