long binary_search_min(long maxval){
	long middle,minv = loINF;
	long l = 0;
	long r = maxval;
	long ans;
	long iter = 0;
	while (iter < MAX_ITER){
		iter++;
		middle = (l + r) / 2;
		ans = simulate(middle);

		if (ans == 2){
			if (middle < minv){
				minv = middle;
				r = middle;
			}
			else l = middle;
		}

		if(ans > 2) r = middle;
		else {
			 l = middle;
		}
	}

	return minv;
}

long binary_search_max(long maxval){
	long middle,maxv = -1;
	long l = 0;
	long r = maxval;
	long ans;
	long iter = 0;
	while (iter < MAX_ITER){
		iter++;
		middle = (l + r) / 2;
		ans = simulate(middle);

		if (ans == 2){
			if (middle > maxv){
				maxv = middle;
				l = middle;
			}
			else r = middle;
		}

		if(ans > 2) r = middle;
		else {
			 l = middle;
		}
	}

	return maxv;
}


