LL n , ara[ N ];


LL can( LL tot ) {
    for( int i = 1; i <= n; i++ ) {
        if( tot <= 0 ) 0;
        if( tot%ara[i] == 0 ) continue;
        else tot -= (tot%ara[i]);
    }
    return tot;
}
LL BS1( ) {
    LL lo = 1 , hi = inf;
    LL ret = -1;
    while( lo <= hi ) {
        LL mid = (lo+hi)/2;
        if( can(mid) >= 2 ) {
            ret = mid;
            hi = mid-1;
        }
        else lo = mid+1;
    }
    return ret;
}
LL BS2( ) {
    LL lo = 1 , hi = inf;
    LL ret = -1;
    while( lo <= hi ) {
        LL mid = (lo+hi)/2;
        if( can(mid) <= 2 ) {
            ret = mid;
            lo = mid+1;
        }
        else hi = mid-1;
    }
    return ret;
}
