        for (int i = 0; i < n; i ++) {
                scanf("%d", &a[i]);
        }
        int lb = 0, ub = 1e9;
        int ok = -1;
        int cnt = 100;
        while (cnt --) {
                int mid = (lb + ub) / 2;
                int get = calc(mid, a);
                if (get == 0) {
                        lb = mid;
                } else if (get == 2) {
                        ub = mid;
                } else {
                        ok = mid;
                        break;
                }
        }
        if (!~ok) {
                return !printf("-1\n");
        }
        int milb = 0, miub = ok + 1;
        while (miub - milb > 1) {
                int mid = (milb + miub) / 2;
                //printf("%d %d %d\n", milb, mid, miub);
                int get = calc(mid, a);
                assert(get != 2);
                if (get == 0) {
                        milb = mid;
