                }
        }
        int malb = ok, maub = 1e9 + 10;
        while (maub - malb > 1) {
                int mid = (malb + maub) / 2;
                int get = calc(mid, a);
                assert(get != 0);
                if (get == 1) {
                        malb = mid;
                } else {
                        maub = mid;
