ll ans1, ans2;

ll G(ll n) {
  REP(i, K) { n = (n/A[i])*A[i]; }
  return n;
}

ll BinSearch1(ll i, ll j) {
  while (i+1 != j) {
    ll k = (i+j)/2;
    if (G(k) >= 2) {
      j = k;
    } else {
      i = k;
    }
  }
  return j;
}

ll BinSearch2(ll i, ll j) {
  while (i+1 != j) {
    ll k = (i+j)/2;
    if (G(k) <= 2) {
      i = k;
    } else {
      j = k;
    }
  }
  return i;
}

