foo :: [Int] -> Int -> Int
foo a x = foldl' (\a b -> a `div` b * b) x a

binarySearch :: (Int -> Bool) -> Int -> Int -> Int
binarySearch f l r
  | r - l == 1 = r
  | otherwise = let m = div (l + r) 2
                in if f m then binarySearch f l m
                          else binarySearch f m r

#include <cstdio>
const int K = 100050;
int A[K];
int main() {
  int k;
  scanf("%d", &k);
  for (int i = 0; i < k; ++i) scanf("%d", &A[i]);
  if (A[k - 1] != 2) return puts("-1") & 0;
  int l = 2, r = 2;
  for (int i = k - 1; ~i; --i) {
    l = (l + A[i] - 1) / A[i] * A[i];
    r = r / A[i] * A[i] + A[i] - 1;
    if (r < l) return puts("-1") & 0;
  }
  printf("%d %d\n", l, r);
  return 0;
}

