long long int miin(long long int a,long long int b,long long int n){
  int i,x,s=-1;
  if(a%n==0){
    return a;
  }else{
    x=a + n - a%n;
    if(x <= b){
      return x;
    }else{
      return s;
    }
  }
}

long long int maax(long long int a,long long int b,long long int n){
  int i,x,s=-1;
  if(b%n==0){
    return b;
  }else{
    x=b - b%n;
    if(x >= a){
      return x;
    }else{
      return s;
    }
  }
}

