	for (i = 0; i < siACnt; i++) {
		fscanf(szpFpI, "%d", &si1Array[i]);
	}
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);

	// 最終
	if (si1Array[siACnt - 1] != 2) {
		return -1;
	}

	// 最終前～１回目
	slMin = 2;
	slMax = 3;
	for (i = siACnt - 2; i >= 0; i--) {

		// 最小
		long long llMin = (slMin + si1Array[i] - 1) / si1Array[i] * si1Array[i];
		if (llMin > slMax) {
			return -1;
		}

		// 最大
		long long llMax = slMax / si1Array[i] * si1Array[i] + si1Array[i] - 1;
		if (llMax < slMin) {
			return -1;
		}

		// 更新
		slMin = llMin;
		slMax = llMax;
	}

	return 0;
}

