int update(int data, int *min, int *max, int A, int is_updated);

int main()
{
    int K, *data, i, j, min_N = 2, max_N = 2, is_updated = 0;

    scanf("%d", &K);
    data = (int *)malloc(sizeof(int) * K);
    for (i = 0; i < K; i++){
        scanf("%d", &data[i]);
    }

    for (i = K - 1; i >= 0; i--) {
        for (j = min_N; j <= max_N; j++){
            if (j % data[i] == 0) {
                is_updated = update(j, &min_N, &max_N, data[i], is_updated);
            }
        }
        if (is_updated == 0){
            printf("-1\n");
            return 0;
        }
        is_updated = 0;
    }

    printf("%d %d\n", min_N, max_N);

    free(data);
    return 0;
}

int update(int data, int *min, int *max, int A, int is_updated)
{
    if (is_updated == 1){
        if (data + A - 1 >= *max)
            *max = data + A - 1;
        if (*min >= data)
            *min = data;
    }else{
        *max = data + A - 1;
        *min = data;
    }
    return 1;
}

