        for (a in A) {
            res = res / a * a
        }

        return res
    }

    val INF = 2L + A.size * A.max()!!

    var l = 0L
    var u = INF

    while (u - l > 1) {
        val c = (l + u) / 2

        if (calc(c) >= 2) {
            u = c
        } else {
            l = c
        }
    }

    val a = u

    l = 0L
    u = INF

    while (u - l > 1) {
        val c = (l + u) / 2

        if (calc(c) <= 2) {
            l = c
        } else {
            u = c
        }
    }

    val b = l

    if (a > b) {
        println(-1)
    } else {
        println("$a $b")
    }
}

