	public void run() {

		try {
			//String S = sc.next().trim();
			int N = sc.nextInt();
			long[] A = new long[N];
			for (int i = 0; i < N; i++) {
				A[i] = sc.nextLong();
			}
			//out.println(Arrays.toString(A));

			if (A[N - 1] != 2) {
				out.println(-1);
				return;
			}

			long from = A[N - 1];
			long to = 2 * A[N - 1] - 1;

			for (int i = N - 2; i >= 0; i--) {
				long base = (long) (to / A[i]);
				if (from <= base * A[i] && base * A[i] <= to) {
					from = base * A[i];
					to = (base + 1) * A[i] - 1;
				} else {
					out.println(-1);
					return;
				}
			}

			out.println(from + " " + to);

		} catch (ArithmeticException ae) {
			//ae.printStackTrace();
			throw new RuntimeException();
