public class Main {
  private static long divCeil(long a, long b) {
    if (a % b == 0) {
      return a / b;
    } else {
      return a / b + 1;
    }
  }

  private static String solve(long[] a) {
    long min = 2;
    long max = 2;

    for (int i = a.length - 1; i >= 0; i--) {
      if (max < a[i]) {
        return "-1";
      }
      min = divCeil(min, a[i]) * a[i];
      max = (max / a[i] + 1) * a[i] - 1;
      if (max < min) {
        return "-1";
      }
//      System.err.printf("%d %d\n", min, max);
    }
    return String.format("%d %d", min, max);
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int k = reader.nextInt();
    long[] a = reader.nextLongArray(k);
    out.println(solve(a));
  }

