import java.io.*;
import java.util.*;

public class Main {
    FastScanner in;
    PrintWriter out;

    void solve() {
        int n = in.nextInt();
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
        }
        int from = 2, to = 2;
        for (int i = n - 1; i >= 0; i--) {
            int cur = a[i];
            int minOne = from / cur * cur;
            if (minOne < from) {
                minOne += cur;
            }
            int maxOne = to / cur * cur;
            if (minOne > maxOne) {
                out.println(-1);
                return;
            }
            from = minOne;
            to = maxOne + (cur - 1);
        }
        out.println(from + " " + to);
    }

    void run() {
        try {
            in = new FastScanner(new File("Main.in"));
            out = new PrintWriter(new File("Main.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

