            max = Math.max(max, a[i]);
        }

        if (a[k - 1] > 2) {
            out.print(-1);
            return;
        }

        int l = 2;
        int r = 2;

        for (int i = k - 1; i >= 0; i--) {
            int x = l / a[i];

            if (l % a[i] != 0) {
                x++;
            }

            if (x * a[i] < l || x * a[i] > r) {
                out.print(-1);
                return;
            }

            int y = r / a[i];

            l = x * a[i];
            r = y * a[i] + (a[i] - 1);
        }
