                // 成功 jがk-1のときにgが1の場合
                if (j == k - 1 && g == 1) {
                    success = true;
                }
                // もう絶対に成功しない
                if (j == k - 1 && 2 <= g) {
                    failed = true;
                }
            }
            if (success) {
                if (i < nMin) {
                    nMin = i;
                } else if (nMax < i) {
                    nMax = i;
                }
            }
            if (failed) {
                break;
            }
        }
        if (nMin == A_MAX_INT) {
            System.out.println("-1");
        } else {
            System.out.println(nMin + " " + nMax);
        }
    }
}

