    static class TaskB {
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int k = in.nextInt();
            long[] arr = IntStream.range(0, k).mapToLong(i -> in.nextLong()).toArray();
            long l = 2, r = 2;
            boolean flag = true;
            for (int i = k - 1; i >= 0; i--) {
