            System.err.println("Time = " + (t2 - t1));
        } catch (Exception e) {
            e.printStackTrace(System.err);
            System.exit(-1);
        }
    }

    public int check(int[] a, long start) {
        long current = start;
        for (int i = 0; i < a.length; i++) {
            if (current % a[i] != 0) {
                current = (current / a[i]) * a[i];
            }
        }
        if (current == 2) {
            return 1;
        } else {
            return -1;
        }
    }

    public void solve() throws IOException {
        int k = readInt();
        int[] a = new int[k];
        long max = -1;
        for (int i = 0; i < k; i++) {
            a[i] = readInt();
            max = Math.max(max, a[i]);
        }

        if (a[k - 1] > 2) {
            out.print(-1);
            return;
        }
        long left = max;
        long right = 1000 * 1000 * 1000 * 1000 * 1000 * 1000 + 1;
        long m1 = -1;
        long m2 = -1;

        long found = -1;

        for (int zz = 0; zz < 150; zz++) {
            m1 = left + (right - left) / 3;
            m2 = right - (right - left) / 3;
            int check1 = check(a, m1);
            int check2 = check(a, m2);
            if (check1 < check2) {
                left = m1;
                found = m2;
            } else {
                if (check1 > check2) {
                    found = m1;
                }
                right = m2;
            }
        }

        if (found == -1) {
            out.print(-1);
            return;
        }

        left = found;
        right = 1000 * 1000 * 1000 * 1000 * 1000 * 1000 + 1;
        long foundMax = -1;

        for (int zz = 0; zz < 150; zz++) {
            long mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                left = mid;
            } else {
                right = mid;
            }
        }

        if (check(a, left) == 1 && check(a, left + 1) == -1) {
            foundMax = left;
        }

        long foundMin = -1;

        left = max;
        right = found;

        for (int zz = 0; zz < 150; zz++) {
            long mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                right = mid;
            } else {
                left = mid;
            }
        }

        if (check(a, right) == 1 && check(a, right - 1) == -1) {
            foundMin = right;
        }

        out.print(foundMin + " " + foundMax);


    }
}

