public void solve() {
	int num = ni();
	long a[] = nl(num);
	reverse(a);
	long l = 2;
	long r = 3;
	for(int i = 0; i < num; i ++) {
		l = divceil(l, a[i]) * a[i];
		r = (divfloor(r - 1, a[i]) + 1) * a[i];
	}
	if(r <= l) exit(-1);
	prtln(l, r - 1);
}

	}
}

