    public long check(int[] a, long start) {
        long current = start;
        for (int i = 0; i < a.length; i++) {
            if (current % a[i] != 0) {
                current = (current / a[i]) * a[i];
            }
        }
        return current;
    }

    public void solve() throws IOException {
        int k = readInt();
        int[] a = new int[k];
        long max = -1;
        for (int i = 0; i < k; i++) {
            a[i] = readInt();
            max = Math.max(max, a[i]);
        }

        if (a[k - 1] > 2) {
            out.print(-1);
            return;
        }

        long left = max;
        long right = Long.MAX_VALUE - 100;

        for (int zz = 0; zz < 150; zz++) {
            long mid = (left + right) / 2;
            long result = check(a, mid);
            if (result > 2) {
                right = mid - 1;
            } else {
                left = mid;
            }
        }

        long mmax = (right + left) / 2;


        left = max;
        right = Long.MAX_VALUE - 100;

        for (int zz = 0; zz < 150; zz++) {
            long mid = (left + right) / 2;
            long result = check(a, mid);
            if (result < 2) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }

        long mmin = (right + left) / 2;

        if (check(a, mmin - 1) == 2) {
            mmin--;
        }
        if (check(a, mmax + 1) == 2) {
            mmax++;
        }

        if (mmax < mmin) {
            out.print(-1);
            return;
        }
        out.print(mmin + " " + mmax);
    }
