        }

        int smallest = prevRoundChildren;
        int largest = smallest + a[0] - 1;
        System.out.println(smallest + " " + largest);
    }

    private static int smallestMultiply(int g, int v) {
        int m = 1;
        while (m * g < v) {
            m++;
        }
        return m;
    }

