			else if(a[i] < a[i+1]){
				a[i] *= (a[i+1]/a[i])+1;
			}

			if(i != 0){
				min += a[i] - a[i+1];
				max += a[i] - a[i+1];
			}
		}

		if(k != 1){
			min += a[0] - a[1] + 2;
			max += a[0] - a[1] + b + 1;
		}
		else {
			if(a[0] == 1){
				min = 2;
				max = 2;
			}
			else {
				min = 2;
				max = 3;
			}
		}

		System.out.println(min+" "+max);

	}

