	public void solve() throws IOException {
		for(int i=K-1; i>0; i--) {
			int Anow = A[i];
			int Apre = A[i-1];
			if(i==K-1) {
				minN = Anow;
				maxN = Anow*2-1;
			}else{
				maxN += Anow-1;
			}

			if(Apre > maxN) {
				minN = -1;
				maxN = -1;
				return;
			}

			minN = ((minN/Apre)+((minN%Apre==0)?0:1))*Apre;
			maxN = (maxN/Apre)*Apre;
		}

		maxN += A[0] - 1;
	}



