/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        IceRinkGame solver = new IceRinkGame();
        solver.solve(1, in, out);
        out.close();
    }

    static class IceRinkGame {
        long maxN;
        long minN;
        int[] A;
        Set<IceRinkGame.State> cache;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int K = in.nextInt();
            A = new int[K];
            for (int i = 0; i < K; i++) {
                A[i] = in.nextInt();
            }
            minN = Long.MAX_VALUE;
            maxN = Long.MIN_VALUE;

            if (A[K - 1] != 2) {
                out.println(-1);
                return;
            }
            cache = new HashSet<>();
            find(K - 1, A[K - 1]);

            if (minN == Long.MAX_VALUE) {
                out.println(-1);
            } else {
                out.println(minN + " " + maxN);
            }
        }

        private void find(int idx, long N) {
            if (cache.contains(new IceRinkGame.State(idx, N))) return;
            if (idx == 0) {
                maxN = Math.max(maxN, N + A[idx] - 1);
                minN = Math.min(minN, N);
            } else {
//            long start = N - (N % A[idx - 1]);
                long start = ((N + A[idx - 1] - 1) / A[idx - 1]) * A[idx - 1];
                long end = N + A[idx];
                for (long nn = start; nn < end; nn += A[idx - 1]) {
                    find(idx - 1, nn);
                }
            }

            cache.add(new IceRinkGame.State(idx, N));
        }

        static class State implements Comparable<IceRinkGame.State> {
            int idx;
            long N;

            public State(int idx, long N) {
                this.idx = idx;
                this.N = N;
            }


            public int compareTo(IceRinkGame.State o) {
                if (this.N == o.N) {
                    return Integer.compare(this.idx, o.idx);
                }
                return Long.compare(this.N, o.N);
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

