class Solver {

	public int[] solve(int[] a) {
		int[] r = new int[] { 2, 2 };
		for (int i = a.length - 1; i >= 0 && r[0] <= r[1]; i--)
			r = solve(a[i], r);
		return r;
	}

	public int[] solve(int a, int[] r) {
		return new int[] { (r[0] + a - 1) / a * a, (r[1]) / a * a + a - 1 };
	}
}

