    }

    public static long[] step(long[] range, long n){
        long[] ans = new long[]{-1, -1};
        long al = range[0] / n;
        long bl = range[0] % n;
        long ar = range[1] / n;
        long br = range[1] % n;

        if(ar - al == 0 && bl != 0){
            return ans;
        }

        if(bl == 0){
            ans[0] = range[0];
            ans[1] = ar*n + n-1;
        }else{
            ans[0] = al*n + n;
            ans[1] = ar*n+n-1;
        }

        return ans;
    }
}



