class Main{
	private void solve(){
		int n=gInt(),in[]=ints(n).toArray();
		long min=2,max=2;
		for(int i:rrep(n-1,0)) {
			if(in[i]>max) {
				System.out.println(-1);
				return;
			}
			min=((min-1)/in[i]+1)*in[i];
			max=min+in[i]-1;
		}
