public class Main {
	public static long solveMax(int K, long[] A){
		long childrenMax = 2;
		for(int k=K-1;k>=0;k--){
			childrenMax = (childrenMax/A[k])*A[k] + A[k]-1;
		}
		return childrenMax;
	}
	public static long solveMin(int K, long[] A){
		long childrenMin = 2;
		for(int k=K-1;k>=0;k--){
			childrenMin = ((childrenMin+A[k]-1)/A[k])*A[k];
		}
		return childrenMin;
	}


    public static void main(String[] args) {
