        int K = sc.nextInt();
        long[] A = new long[K];
        for(int k=0;k<K;k++)A[k]=sc.nextLong();

        long M = solveMax(K,A);
        long m = solveMin(K,A);
        if(M>=m) System.out.println(m+" "+M);
        else System.out.println("-1");


    }
}

