        else {
            long min = 2, max = 2;
            for (int i = k - 1; i >= 0; i--) {
                long x = min % a[i] == 0 ? min : min + (a[i] - (min % a[i])),
                        y = max % a[i] == 0 ? max : max - (max % a[i]);
                if (x > max || y < min) {
                    out.println(-1);
                    out.flush();
                    out.close();
                    return;
                }
                min = x;
                max = y + a[i] - 1;
            }
