        }
        if (A[N-1] != 2) {
            System.out.println(-1);
            return;
        }
        long min = 2;
        long max = 3;
        for (int i = N - 2; 0 <= i; i--) {
            if (max < A[i]) {
                System.out.println(-1);
                return;
            }
            long from = min / A[i];
            if (min % A[i] != 0) {
                from += 1;
            }
            long to = max / A[i];
            long next_min = from * A[i];
            long next_max = to * A[i] + A[i] - 1;
            if (max < next_min) {
                System.out.println(-1);
                return;
            }
            min = next_min;
            max = next_max;
        }
        System.out.printf("%d %d\n", min, max);
    }
