    static final long CONST_INF = Long.MAX_VALUE / 4;

    public long[][] warshallFloyd(int n, int[][] edges) {
        long[][] graph = new long[n][n];
        for (int i = 0; i < n; i++) {
            Arrays.fill(graph[i], CONST_INF);
            graph[i][i] = 0;
        }
        int m = edges.length;
        for (int i = 0; i < m; i++) {
            int f = edges[i][0] - 1;
            int t = edges[i][1] - 1;
            long cost = edges[i][2];
            graph[f][t] = cost;
            graph[t][f] = cost;
        }
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    graph[i][j] = Math.min(graph[i][j], graph[i][k] + graph[k][j]);
                }
            }
        }
        return graph;
    }


    private static class GPair implements Comparable<GPair> {
        long k;
        long v;

        public GPair(int k, int v) {
            this.k = k;
            this.v = v;
        }

        public GPair(long k, long v) {
            this.k = k;
            this.v = v;
        }

        public int compareTo(GPair pair) {
