        ArrayList<Long> li = new ArrayList<>();
        for(int i = 0; i < k; i++){
            li.add(sc.nextLong());
        }
        Collections.reverse(li);
        long prev = 2;
        long now = 0;
        boolean pos = true;
        for(int i = 0; i < k; i++){
            now = li.get(i);
            if(now == 1L){
                pos = false;
                break;
            }
            if(now == prev){
                continue;
            }else if(now < prev){
                long pow = prev/now;
                if(prev % now != 0) pow++;
                now *= pow;
            }
            else if(now > prev){
                if(now >= prev*2L){
                    pos = false;
                    break;
                }
            }
            prev = now;
            //pw.println(now);
        }
        pw.println(pos ? now +" " + (now+li.get(k-1)-1) : -1);
        pw.flush();
    }

    static class GeekInteger {
        public static void save_sort(int[] array) {
            shuffle(array);
            Arrays.sort(array);
        }

        public static int[] shuffle(int[] array) {
            int n = array.length;
            Random random = new Random();
            for (int i = 0, j; i < n; i++) {
                j = i + random.nextInt(n - i);
                int randomElement = array[j];
                array[j] = array[i];
                array[i] = randomElement;
            }
            return array;
        }

    }
