        } catch (Exception e) {
            e.printStackTrace(System.err);
            System.exit(-1);
        }
    }

    public int check(int[] a, int start) {
        int current = start;
        for (int i = 0; i < a.length; i++) {
            if (current % a[i] != 0) {
                current = (current / a[i]) * a[i];
            }
        }
        if (current == 2) {
            return 1;
        } else {
            return -1;
        }
    }

    public void solve() throws IOException {
        int k = readInt();
        int[] a = new int[k];
        int max = -1;
        for (int i = 0; i < k; i++) {
            a[i] = readInt();
            max = Math.max(max, a[i]);
        }

        if (a[k - 1] > 2) {
            out.print(-1);
            return;
        }
        int left = max;
        int right = 1000 * 1000 * 1000 + 1;
        int found = -1;

        for (int z = 0; z < 100; z++) {
            int mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                found = mid;
                right = mid;
            } else {
                left = mid;
            }
        }

        left = max;
        right = 1000 * 1000 * 1000 + 1;

        for (int z = 0; z < 100; z++) {
            int mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                found = mid;
                left = mid;
            } else {
                right = mid;
            }
        }

        if (found == -1) {
            out.print(-1);
            return;
        }

        for (int i = 0; i < k; i++) {
            if (a[i] != 1) {
                out.print((found - a[i] + 1) + " " + found);
                return;
            }
        }
        out.print(found + " " + found);
    }
