public class Main {
    private static final int mod = 1000000007;
    private static int K;
    private static int [] A;

    private static long f(long n){
        for(int x : A)
            n -= n%x;
        return n ;
    }

    public static void main(String[] args) throws Exception{
        IO io = new IO(null,null);
        K = io.getNextInt();
        A = new int[K];
        for (int i = 0;i < K;i++)
            A[i] = io.getNextInt();

        if (f(Long.MAX_VALUE) < 2) io.println(-1);
        else {
            long s = 2,e = Long.MAX_VALUE;
            while (s < e) {
                long m = s + (e-s)/2;
                if (f(m) >= 2) e = m;
                else s = m + 1;
            }
            long l = s;
            if (f(l) != 2) {
                io.println(-1);
                io.close();
                System.exit(0);
            }
            e = Long.MAX_VALUE;
            while (s < e) {
                long m = s + (e-s+1)/2;
                if (f(m) == 2) s = m;
                else e = m-1;
            }
            io.println(l + " " + e);
        }
        io.close();
    }
}



