public class Main {

    public static String numberN(int K, int[] A) {
        for (int i = 0; i < K - 1; i++) {
            if (A[i] / 2 > A[i+1]) {
                return "-1";
            }
        }
        int min = A[K-1];
        for (int i = K - 2; i >= 0; i--) {
            if (A[i] >= min) {
                min = A[i];
            } else {
                min = A[i] * (A[i+1] / A[i] + 1);
            }
        }
        int max = min + A[0] - 1;
        return min + " " + max;
    }

