        for (int i = k - 1; i >= 0; i--) {
            min = ceilDiv(min, a[i]) * a[i];
            max = max / a[i] * a[i] + a[i] - 1;
        }

        if (min <= max) {
            stdout.printf("%d %d%n", min, max);
        } else {
            stdout.println(-1);
        }

    }

    private long ceilDiv(long x, long y) {
        if (x % y == 0) {
            return x / y;
        } else {
            return x / y + 1;
        }
    }

