            max = Math.max(max, a[i]);
        }

        if (a[k - 1] > 2) {
            out.print(-1);
            return;
        }
        int left = max;
        int right = 1000 * 1000 * 1000 + 1;
        int found = -1;

        for (int z = 0; z < 100; z++) {
            int mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                found = mid;
                right = mid;
            } else {
                left = mid;
            }
        }

        left = max;
        right = 1000 * 1000 * 1000 + 1;

        for (int z = 0; z < 100; z++) {
            int mid = (left + right) / 2;

            if (check(a, mid) == 1) {
                found = mid;
                left = mid;
            } else {
                right = mid;
            }
        }

        if (found == -1) {
            out.print(-1);
            return;
        }
        int size = found + 100;
        for (int i = found + 1; i <= size; i++) {
            if (check(a, i) == 1) {
                found = i;
