                if (i < nMin) {
                    nMin = i;
                }
                if (nMax < i) {
                    nMax = i;
                }
            }
            if (failed) {
                break;
            }
        }
        if (nMin == A_MAX_INT) {
            System.out.println("-1");
        } else {
            System.out.println(nMin + " " + nMax);
        }
    }
}

