	static int INF = 1 << 30;

	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int k = in.nextInt();
			long[] an = in.nextLongArray(k);

			long min = 0;
			long max = 100;

			long left = 0, right = max;
			long mid = (left + right) / 2;

			long v = 0;
			while (left < right) {
				v = g(mid, an);
				if (v >= 2) {
					right = mid;
				} else {
					left = mid + 1;
				}
				mid = (left + right) / 2;
			}
			if (g(mid, an) != 2) {
				out.println(-1);
				return;
			}
			min = mid;

			left = 0;
			right = max;
			mid = (left + right) / 2;

			while (left < right) {
				v = g(mid, an);
				if (v <= 2) {
					left = mid;
				} else {
					right = mid - 1;
				}
				mid = (left + right) / 2;
				if (right == (left + 1)){
					mid++;
				}
			}
			if (g(mid, an) != 2) {
				out.println(-1);
				return;
			}
			max = mid;

			out.println(min + " " + max);


		}

		static long g(long x, long[] an) {
			for (int i = 0; i < an.length; i++) {
				x = f(x, an[i]);
			}
			return x;
		}

		static long f(long x, long p) {
			return x - x % p;
		}
	}

