		for(int j=K-1;j>=0;j--) {
			if(a[j]>max) {
				success = false;
				System.out.println(-1);
				break;
			}
			int cmin;
			int cmax;
			if(a[j]>=min) {
				cmin = a[j];
			}else {
				int mod = min%a[j];
				cmin = (min/a[j]);
				if(mod>0)
					cmin++;
				cmin *= a[j];
			}
			cmax = cmin+(a[j]-1);
			if(cmax<min&&cmin>max) {
				success = false;
				System.out.println(-1);
				break;
			}

			max = cmax;
			min = cmin;
		}
		if(success) {
			System.out.println(min+" "+max);
		}
	}
}

