    public struct Pair
    {
        public long Min, Max;

        public Pair(long min, long max)
        {
            Min = min;
            Max = max;
        }
    }

    public static void Solve()
    {
        var k = I;
        var a = Repeat(k, () => L).ToArray();

        if (a[k - 1] != 2)
        {
            Console.WriteLine(-1);
            Exit(0);
        }

        var max = new long[k + 1];
        max[k] = 2;

        for (var i = k - 1; i >= 0; i--)
        {
            if (a[i] > max[i + 1])
            {
                Console.WriteLine(-1);
                Exit(0);
            }

            max[i + 1] = max[i + 1] / a[i] * a[i];
            max[i] = max[i + 1] + a[i] - 1;
        }

        var min = new Pair[k];
        min[k - 1] = new Pair(2, 2);

        for (var i = k - 2; i >= 0; i--)
        {
            var nmin = DivCeil(min[i + 1].Min, a[i]) * a[i];
            var nmax = (min[i + 1].Max + a[i + 1] - 1) / a[i] * a[i];

            min[i] = new Pair(nmin, nmax);
        }

        if (min[0].Min > max[0]) min[0].Min--;
        Assert(min[0].Min <= max[0]);

        Console.WriteLine($"{min[0].Min} {max[0]}");
    }

