    static void solve(int K,long[] A)
    {
        Array.Reverse(A);
        long min = A[0];
        long max = A[0] * 2 - 1;
        for (int i = 1; i < K; i++)
        {
            max = max / A[i] * A[i] + A[i] - 1;
            if (min % A[i] == 0);
            else min = min / A[i] * A[i] + A[i];
            if (min > max)
            {
                WriteLine(-1);
                return;
            }
        }
        WriteLine($"{min} {max}");
    }
