            while (ub - lb > 1)
            {
                var mid = (lb + ub) / 2;
                if (A[i] * mid <= lmax) lb = mid;
                else ub = mid;
            }
            max = A[i] * ub - 1;

            (lb, ub) = (0, 1000000000);
