            {
                var mid = (lb + ub) / 2;
                if (A[i] * mid < lmin) lb = mid;
                else ub = mid;
            }
            min = A[i] * ub;

            if (max / A[i] * A[i] > lmax || max / A[i] * A[i] < lmin ||
                min / A[i] * A[i] > lmax || min / A[i] * A[i] < lmin)
            {
                WriteLine(-1);
                return;
            }
        }
        WriteLine($"{min} {max}");
