    class Solver
    {
        private int k;
        private long[] a;

        public void Solve()
        {
            Cin(out k);
            Cin(out a);

            if (a[k - 1] != 2)
            {
                Console.WriteLine(-1);
                return;
            }

            long min = 2;
            long max = 3;
            for (int i = k - 2; i >= 0; i--)
            {
                var c = a[i];
                long newMin = min + (c - min % c) % c;
                if (min < newMin) min = newMin;

                long newMax = max + (c - max % c) - 1;
                if (newMax > max) max = newMax;

                if (min > max)
                {
                    Console.WriteLine(-1);
                    return;
                }
            }

            Console.WriteLine("" + min + " " + max);
        }
    }
