                Console.WriteLine(-1);
                return;
            }

            var preMax = max;
            var preMin = min;
            max = (max / x) * x + (x - 1);

            if (x >= min)
            {
                min = x;
            }
            else
            {
                min = (min / x + 1) * x;
                if((min/x)*x > preMax)
                {
                    min = (preMax / x) * x;
                }
            }
        }

        Console.WriteLine($"{min} {max}");
    }
}

