	public class Program
	{
		static void Main(string[] args)
		{
			int k = int.Parse(Console.ReadLine());
			long[] a = Console.ReadLine().Split(' ').Select(long.Parse).ToArray();

			long max = 2;
			long min = 2;
			for (long i = k - 1; i >= 0; --i) {
				if (i == 0) {
					max += a[i] - 1 - max % a[i];
				} else {
					if (a[i - 1] / a[i] > 1) {
						Console.WriteLine(-1);
						return;
					}

					long cur = a[i];
					long prev = a[i - 1];
					if (prev >= max + cur) {
						Console.WriteLine(-1);
						return;
					}

					long tempMin = prev * (min / prev);
					if (min % prev != 0) {
						tempMin += prev;
					}

					long temp = max + cur - 1;
					long tempMax = prev * (temp / prev);

					if (tempMin > temp || tempMax < min) {
						Console.WriteLine(-1);
						return;
					}

					min = tempMin;
					max = tempMax;
				}
			}

			Console.WriteLine($"{min} {max}");
		}
	}
}

