    [DebuggerDisplay("({Min}, {Max}) ({Value})")]
    public struct State
    {
        public long Min, Max, Value;

        public State(long min, long max)
        {
            Assert(min <= max);
            Min = min;
            Max = max;
            Value = -1;
        }

        public State(long value)
        {
            Min = -1;
            Max = -1;
            Value = value;
        }
    }

    public static void Solve()
    {
        var k = I;
        var a = Repeat(k, () => L).ToArray();

        if (a[k - 1] != 2)
        {
            Console.WriteLine(-1);
            Exit(0);
        }

        var n = new State[k + 1];
        n[k] = new State(2, 2);

        for (var i = k - 1; i >= 0; i--)
        {
            if (a[i] > n[i + 1].Max)
            {
                Console.WriteLine(-1);
                Exit(0);
            }

            n[i + 1] = new State(n[i + 1].Max / a[i] * a[i]);
            n[i] = new State(n[i + 1].Value, n[i + 1].Value + a[i] - 1);
        }

        var min = n[0].Min;
        var max = n[0].Max;
        Array.Clear(n, 0, n.Length);
        n[k] = new State(2, 2);

        for (var i = k - 1; i >= 0; i--)
        {
            if (n[i + 1].Value == -1)
            {
                var tmp = DivCeil(n[i + 1].Min, a[i]) * a[i];
                if (tmp > n[i + 1].Max)
                {
                    if ((n[i + 2].Value += a[i + 1]) > n[i + 1].Max)
                    {
                        Console.WriteLine($"{min} {max}");
                        Exit(0);
                    }
                    i += 2;
                    continue;
                }
                n[i + 1].Value = tmp;
            }
            n[i] = new State(n[i + 1].Value, n[i + 1].Value + a[i] - 1);
        }

        min = n[0].Min;
        Console.WriteLine($"{min} {max}");
    }

