using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;
class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int[] A = re.ia();
        if(A[N-1] != 2){
            sb.Append("-1\n");
            return;
        }
        int min = 2;
        int max = 3;
        for(int i=N-2;i>=0;i--){
            if(A[i] > max){
                sb.Append("-1\n");
                return;
            }
            min = (min-1) / A[i] * A[i] + A[i];
            max = max / A[i] * A[i];
            if(max < min){
                sb.Append("-1\n");
                return;
            }
            max += A[i]-1;
        }
        sb.Append(min+" "+max+"\n");
    }
}
