public static class Program
{
    public static void Solve()
    {
        var k = I;
        var a = Repeat(k, () => L).ToArray();

        if (a[k - 1] != 2)
        {
            Console.WriteLine(-1);
            Exit(0);
        }

        var n = new long[k + 1];
        n[k] = 2;

        for (var i = k - 1; i >= 0; i--)
        {
            if (a[i] > n[i + 1])
            {
                Console.WriteLine(-1);
                Exit(0);
            }

            n[i + 1] = n[i + 1] / a[i] * a[i];
            n[i] = n[i + 1] + a[i] - 1;
        }

        var max = n[0];
        var ok = max;
        var ng = 1L;

        Func<long, bool> Predicate = x =>
        {
            Repeat(k, i => { x -= x % a[i]; });
            return x == 2;
        };

        while (ok - ng > 1)
        {
            var mid = ng + (ok - ng) / 2;
            if (Predicate(mid)) ok = mid;
            else ng = mid;
        }

        var min = ok;
        Console.WriteLine($"{min} {max}");
    }

