    static void program(TextReader input)
    {
        var k = int.Parse(input.ReadLine());
        var data = input.ReadLine().Split(' ').Select(long.Parse).ToList();
        var res = k > 1 ? data[1] : 2;
        long start = (long)Math.Ceiling((double)res / data[0]);

        var n = start * data[0];
        var pos = true;
        for(var i = 0; i < k; i++)
        {
            n = n - (n % data[i]);
            if(n%data[i] != 0)
            {
                pos = false;
            }
        }
        if (n != 2)
        {
            pos = false;
        }
        Console.WriteLine(pos ?(start * data[0] + " " + ((start + 1) * data[0] - 1)) : "-1");
    }

