class Program
{

static long k = long.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
static long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);

	static void Main()
	{

    long minAnswer = SearchMin(0, 1000000000000000000);
		long maxAnswer = Search(0, 1000000000000000000); 
    if(minAnswer <= 1) Console.WriteLine(-1);
    else Console.WriteLine(minAnswer + " " + maxAnswer);
	}

  static long Search(long min, long max)//二分探索法で最大値を求める
  {
    while (true)
    {
      long mid = min + (max - min) / 2;
      if(CheckMin(mid)) min = mid;//さらに大きくても成り立つかも
      else max = mid;

      if(max - min <= 1)
      {
        if(CheckMin(max)) 
        {
          return max;//最大値で成り立つかの確認を優先
        }
        else
        {
          return min;
        }
      break;
      }  
    }
  }

  static long SearchMin(long min, long max)//二分探索法で最小値を求める
  {
    while (true)
    {
      long mid = min + (max - min) / 2;
      if(Check(mid)) max = mid;//さらに小さくても成り立つかも
      else min = mid;

      if(max - min <= 1)
      {
        if(Check(min)) 
        {
          return min;//最小値で成り立つかの確認を優先
        }
        else
        {
          return max;
        }
      break;
      }  
    }
  }

  static bool Check(long testNum)
  {
    for(long i = 0; i < k; i++)
    {
      if(testNum < nums[i]) return false;
      long memo = testNum % nums[i];
      testNum -= memo;
    }
    if(testNum < 2) return false;
    return true;
  }

  static bool CheckMin(long testNum)
  {
    for(long i = 0; i < k; i++)
    {
      if(testNum < nums[i]) return true;
      long memo = testNum % nums[i];
      testNum -= memo;
    }
    if(testNum <= 2) return true;
    return false;
  }


}

