class Program
{
    private int K;
    private int[] A;
    private void Scan()
    {
        var sc = new Scanner();
        K = sc.NextInt();
        A = new int[K];
        for (int i = 0; i < K; i++)
        {
            A[i] = sc.NextInt();
        }
    }

    public void Solve()
    {
        Scan();
        int max = 2, min = 2;
        for (int i = K - 1; i >= 0; i--)
        {
            if (((min + A[i] - 1) / A[i]) * A[i] > max)
            {
                Console.WriteLine(-1);
                return;
            }
            max = (max / A[i]) * A[i] + A[i] - 1;
            min = ((min + A[i] - 1) / A[i]) * A[i];
        }
        Console.WriteLine($"{min} {max}");
    }

    static public void Main()
    {
        new Program().Solve();
    }
}

