public class Solver
{
	private long K;
	private long[] A;

	public Solver()
	{
		K = GetInt();
		A = new long[K];
		for(int i = 0; i < K; i++)
			A[i] = GetLong();
	}

	public void Solve()
	{
		long max = 2 + K * A.Max();
		Func<long, long> eval = alive;
		long lb = LowerBound(0, max, 2, eval);
		long ub = UpperBound(0, max, 2, eval);

		Console.WriteLine((lb <= ub) ? $"{lb} {ub}" : "-1");
	}

	private long alive(long x)
	{
		long res = x;
		for(int i = 0; i < K; i++)
			res = res - (res % A[i]);
		return res;
	}
}


public static class MyBinarySearch
{
	public static int LowerBound<T>(T[] array, T key, Comparison<T> comp)
	{
		int len = array.Length;
		if(comp(array[len - 1], key) < 0)
			return -1;

		int left = 0;
		int right = len - 1;
		while(right > left)
		{
			int mid = (left + right) / 2;
			if(comp(array[mid], key) >= 0)
				right = mid;
			else
				left = mid + 1;
		}

		return left;
	}

	public static int LowerBound<T>(List<T> list, T key, Comparison<T> comp)
	{
		return LowerBound(list.ToArray(), key, comp);
	}

	public static long LowerBound(long left, long right, long target, Func<long, long> eval)
	{
		while(right > left)
		{
			long mid = (left + right) / 2;
			if(eval(mid) >= target)
				right = mid;
			else
				left = mid + 1;
		}

		return left;
	}

	public static long UpperBound(long left, long right, long target, Func<long, long> eval)
	{
		while(right > left)
		{
			long mid = (left + right) / 2;
			if(eval(mid) <= target)
				left = mid + 1;
			else
				right = mid;
		}

		return left - 1;
	}
}


