                    if (x[i] * 2 <= x[i - 1]) flag = false;
                    if (min[i] / x[i - 1] == (max[i] + 1) / x[i - 1]) flag = false;
                    min[i - 1] = ((min[i] - 1) / x[i - 1] + 1) * x[i - 1];
                    max[i - 1] = (max[i] / x[i - 1] + 1) * x[i - 1] - 1;
                }
                Console.WriteLine(flag ? min[0] + " " + max[0] : "-1");
            }
            else
            {
                Console.WriteLine(-1);
            }
        }
    }
}

