class MainClass
{
    public static void Main(string[] args)
    {
        long K = long.Parse(Console.ReadLine());
        string[] s = Console.ReadLine().Split(' ');
        long[] a = new long[K];

        for (long i = 0; i < K;i++)
        {
            a[i] = long.Parse(s[i]);
        }

        long max = a[K - 1] * 2 - 1;
        long min = a[K - 1];

        if(min != 2)
        {
            Console.WriteLine("-1");
            return;
        }
        if(K==1)
        {
            Console.WriteLine("{0} {1}", min, max);
            return;
        }

        for(long i = K-2; i >= 0; i--)
        {
            long j = a[i];

            bool mi = true;

            while(true)
            {
                if (j >= min && mi)
                {
                    min = j;
                    mi = false;
                } 
                if (j > max)
                {
                    max = j - 1;

                    if (max <= min)
                    {
                        Console.WriteLine("-1");
                        return;
                    }

                    break;
                }



                j += a[i];
            }

        }

        Console.WriteLine("{0} {1}", min, max);
        return;

    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
class Program
{

static long k = long.Parse(Console.ReadLine());//int.Parseは文字列を整数に変換。
static long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);

	static void Main()
	{

    long minAnswer = SearchMin(0, 1000000000000000000);
		long maxAnswer = Search(0, 1000000000000000000); 
    if(minAnswer <= 1) Console.WriteLine(-1);
    else Console.WriteLine(minAnswer + " " + maxAnswer);
	}

  static long Search(long min, long max)//二分探索法で最大値を求める
  {
    while (true)
    {
      long mid = min + (max - min) / 2;
      if(Check(mid)) min = mid;//さらに大きくても成り立つかも
      else max = mid;

      if(max - min <= 1)
      {
        if(Check(max)) 
        {
          return max;//最大値で成り立つかの確認を優先
        }
        else
        {
          return min;
        }
      break;
      }  
    }
  }

  static long SearchMin(long min, long max)//二分探索法で最小値を求める
  {
    while (true)
    {
      long mid = min + (max - min) / 2;
      if(CheckMin(mid)) max = mid;//さらに小さくても成り立つかも
      else min = mid;

      if(max - min <= 1)
      {
        if(CheckMin(min)) 
        {
          return min;//最小値で成り立つかの確認を優先
        }
        else
        {
          return max;
        }
      break;
      }  
    }
  }

  static bool Check(long testNum)
  {
    for(long i = 0; i < k; i++)
    {
      if(testNum < nums[i]) return false;
      long memo = testNum % nums[i];
      testNum -= memo;
    }
    if(testNum < 2) return false;
    return true;
  }

  static bool CheckMin(long testNum)
  {
    for(long i = 0; i < k; i++)
    {
      if(testNum < nums[i]) return true;
      long memo = testNum % nums[i];
      testNum -= memo;
    }
    if(testNum <= 2) return true;
    return false;
  }


}

