using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using static System.Console;
namespace AtCoder.AGC020
{
    class IceRinkGame
    {
        public static void Main()
        {
            var k = int.Parse(ReadLine().Trim());
            var a = ReadLine().Trim().Split(' ').Select(_ => int.Parse(_)).Reverse();
            int min_rest = 2, max_rest = 2;
            foreach(var ar in a)
            {
                var temp = MinChildren(ar, min_rest, max_rest);
                max_rest = MaxChildren(ar, min_rest, max_rest);
                min_rest = temp;
            }
            if (min_rest == -1) WriteLine(-1);
            else WriteLine($"{min_rest} {max_rest}");
        }
        //脱落する人数は高々Ai - 1人
        //突破する人数はN * Ai人
        static int MinChildren(int group, int min_rest, int max_rest)
        {
            if (min_rest == -1) return -1;
            if (min_rest % group == 0) return min_rest;
            return (min_rest / group != max_rest / group) ? group * (min_rest / group + 1) : -1;
        }
        static int MaxChildren(int group, int min_rest, int max_rest)
        {
            if (min_rest == -1) return -1;
            return max_rest / group * group + group - 1;
        }

    }
}

