class Solution
{
    static void Main(string[] args)
    {
        int n = int.Parse(Console.ReadLine());
        int[] a = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
        int l = 2, r = 2;

        for (int i = a.Length - 1; i >= 0; i--)
        {
            l = (l / a[i] * a[i] == l ? l / a[i] : l / a[i] + 1) * a[i];
            r = r / a[i] * a[i] + a[i] - 1;

            if (r / a[i] * a[i] < l)
            {
                Console.WriteLine(-1);
                return;
            }
        }

        Console.WriteLine($"{l} {r}");
    }
}

