class MainClass : Scanner
{
    static void Main()
    {
        int K = RInt();
        long[] A = RLongs();
        Array.Reverse(A);
        long min = A[0];
        long max = A[0] * 2 - 1;
        for (int i = 1; i < K; i++)
        {
            long lmax = max;
            long lmin = min;
            var (lb, ub) = (0, 1000000000);
            while (ub - lb > 1)
            {
                var mid = (lb + ub) / 2;
                if (A[i]*mid<=lmax) lb = mid;
                else ub = mid;
            }
            max = A[i] * ub - 1;

            (lb, ub) = (0, 1000000000);
            while (ub - lb > 1)
            {
                var mid = (lb + ub) / 2;
                if (A[i]*mid<lmin) lb = mid;
                else ub = mid;
            }
            min = A[i] * ub;

            if (max / A[i] * A[i] > lmax|| max / A[i] * A[i] <lmin||
                min / A[i] * A[i] > lmax|| min/A[i]*A[i] < lmin)
            {
                WriteLine(-1);
                return;
            }
        }
        WriteLine($"{min} {max}");
    }
}

