import "fmt"

func main() {
	var K int

	fmt.Scanf("%d", &K)

	A := make([]int64, K)

	for i := 0; i < K; i++ {
		fmt.Scanf("%d", &A[i])
	}

	if A[K-1] != 2 {
		fmt.Println(-1)
	}

	check := 0
	for i := 0; i < K; i++ {
		if A[check] < A[i] {
			check = i
		}
	}

	count := A[check]
	for i := check + 1; i < K; i++ {
		count -= count % A[i]
	}

	if count > 2 {
		fmt.Println(-1)
		return
	}

	min := int64(2)
	max := int64(3)
	for i := K - 2; i >= 0; i-- {
		if min <= A[i] {
			min = A[i]
		} else {
			min = ((min + (A[i] - 1)) / A[i]) * A[i]
		}
		max = (max/A[i])*A[i] + (A[i] - 1)
	}

	fmt.Printf("%d %d\n", min, max)
}

