func main() {
	var k int
	fmt.Scan(&k)
	as := make([]int, k)
	for i := 0; i < k; i++ {
		fmt.Scan(&as[i])
	}

	mn, mx := 2, 3
	for i := k - 1; i >= 0; i-- {
		a := as[i]
		amin := a
		if amin < mn {
			amin = ((mn + (a - 1)) / a) * a
		}
		mn = amin
		mx = (amin + a) - 1
	}

	if check(mn, as) && check(mx, as) {
		fmt.Println(mn, mx)
	} else {
		fmt.Println(-1)
	}
}

func check(n int, as []int) bool {
	for i := 0; i < len(as); i++ {
		n -= n % as[i]
	}
	return n == 2
}

