func out(x ...interface{}) {
	fmt.Println(x...)
}

var sc = bufio.NewScanner(os.Stdin)

func getInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func getString() string {
	sc.Scan()
	return sc.Text()
}

// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func main() {
	sc.Split(bufio.ScanWords)

	K := getInt()
	a := make([]int, K)
	for i := 0; i < K; i++ {
		a[i] = getInt()
	}
	for i := 0; i < K/2; i++ {
		a[i], a[K-1-i] = a[K-1-i], a[i]
	}

	if a[0] != 2 {
		out(-1)
		return
	}
	// out(a)
	mi := 2
	for i := 1; i < K; i++ {
		if a[i] > mi*2 {
			out(-1)
			return
		}
		if a[i] >= mi {
			mi = a[i]
		} else {
			mi = a[i] * 2
		}
	}

	ma := 3
	for i := 0; i < K; i++ {
		if ma > a[i]*2 {
			ma = a[i]*3 - 1
		} else {
			ma = max(ma, a[i]*2-1)
		}
	}

	out(mi, ma)
}

