	K := ReadInt()
	A := ReadInts(K)

	if A[K-1] != 2 {
		fmt.Println(-1)
		return
	}

	l, r := 2, 3
	for i := K - 2; i >= 0; i-- {
		l = (l + A[i] - 1) / A[i] * A[i]
		r = r/A[i]*A[i] + A[i] - 1
		if l > r {
			fmt.Println(-1)
			return
		}
	}
	fmt.Printf("%d %d\n", l, r)
}

var reader = bufio.NewReader(os.Stdin)

func Scan(a ...interface{}) {
	if _, err := fmt.Fscan(reader, a...); err != nil {
		panic(err)
	}
}
func ReadInt() (i int)       { Scan(&i); return }
