// set up IO functions
func init() {
	// for non-interactive
	SetInput(os.Stdin)
	SetOutput(os.Stdout)

	// Enable below when interactive.  Its ok to leave above intact.
	// SetInteractive(os.Stdout, os.Stdin)
}

func main() {
	defer Flush()

	K := readi()
	A := make([]int64, K)
	for i := range A {
		A[i] = readll()
	}

	x, y, ok := solve(K, A)
	if !ok {
		println(-1)
	} else {
		println(x, y)
	}
}

func solve(K int, A []int64) (int64, int64, bool) {
	B := make([]int64, K)
	for i := range A {
		j := len(A) - i - 1
		B[j] = A[i]
	}

	var v1 int64
	v1 = 2
	for i := range B {
		a := B[i]
		if v1 <= a {
			v1 = a
		} else {
			if v1%a != 0 {
				v1 = (v1/a)*a + a
			}
		}
	}

	if !check(v1, A) {
		return 0, 0, false
	}

	l := int64(1)
	r := v1
	for l+1 < r {
		m := (l + r) / 2
		//eprintln("minv", l, m, r)
		if check(m, A) {
			r = m
		} else {
			l = m
		}
	}
	minv := r

	l = v1
	r = math.MaxInt64 - l - 1
	for l+1 < r {
		m := (l + r) / 2
		//eprintln("maxv", l, m, r)
		if check(m, A) {
			l = m
		} else {
			r = m
		}
	}
	maxv := l

	return minv, maxv, true
}

func check(v int64, A []int64) bool {
	for _, a := range A {
		//eprintln("Check", v, a, v-v%a)
		v -= v % a
	}
	return v == 2
}

