// min, max, asub, absなど基本関数
func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func asub(a, b int) int {
	if a > b {
		return a - b
	}
	return b - a
}

func abs(a int) int {
	if a >= 0 {
		return a
	}
	return -a
}

func check(m int, k int, a []int) int {
	n := m
	for i := 0; i < k; i++ {
		n = n - n%a[i]
	}
	return n
}

func checkmax(k, ma int, a []int) int {
	l := 0
	r := 2001001001
	for l+1 != r {
		m := (l + r) / 2
		ret := check(m, k, a)
		// out(m, ret)
		if ret > 2 {
			r = m
		} else {
			l = m
		}
	}
	// out(l, r)
	if check(r, k, a) == 2 {
		return r
	}
	if check(l, k, a) == 2 {
		return l
	}
	return -1
}

func checkmin(k, ma int, a []int) int {
	l := 0
	r := 2001001001
	for l+1 != r {
		m := (l + r) / 2
		ret := check(m, k, a)
		// out(m, ret)
		if ret >= 2 {
			r = m
		} else {
			l = m
		}
	}
	// out(l, r)
	if check(l, k, a) == 2 {
		return l
	}
	if check(r, k, a) == 2 {
		return r
	}
	return -1
}

