	K := getInt()
	a := make([]int, K)
	mx := 0
	for i := 0; i < K; i++ {
		a[i] = getInt()
		mx = max(mx, a[i])
	}

	mi := checkmin(K, mx, a)
	ma := checkmax(K, mx, a)
	if mi != -1 && ma != -1 {
		out(mi, ma)
	} else {
		out(-1)
	}
}

