	k := getNextInt(scanner)
	aa := make([]int64, k)

	for i := k - 1; i >= 0; i-- {
		aa[i] = getNextInt64(scanner)
	}

	dpmn := make([]int64, k+1)
	dpmx := make([]int64, k+1)

