	dpmn[0] = 2

	for i := 0; i < k; i++ {
		dpmx[i] -= dpmx[i] % aa[i]
		dpmx[i+1] = dpmx[i] + aa[i] - 1
		if dpmx[i+1] < aa[i] {
			fmt.Fprintln(writer, -1)
			writer.Flush()
			return
		}
		dpmn[i+1] = ((dpmn[i]-1)/aa[i] + 1) * aa[i]
	}
	if dpmn[k] > dpmx[k] {
