	iferr(e)
	return v
}
func (s *scanner) pre() {
	if s.p >= len(s.buf) {
		s.readLine()
		s.p = 0
	}
}
func (s *scanner) readLine() {
	s.buf = make([]byte, 0)
	for {
		l, p, e := s.r.ReadLine()
		iferr(e)
		s.buf = append(s.buf, l...)
		if !p {
			break
		}
	}
}

