func main() {

  var n int
  fmt.Scan(&n)
  var list []int
  var result = 0
  for i:= 0 ; i< n; i++ {
    var val int
    fmt.Scan(&val)
    if val > n {
      result = -1
      break
    }
    list = append(list,val)
  }

  if result == -1 {
    fmt.Print(result)
  }else {
    var g = lcm(list[1],list[2])
    for i := 3; i< n ; i++ {
      g = lcm(g,list[i])
    }
    if g == 2 {
      result = 2
    }else {
      result = g / 2
    }
    fmt.Print(result,result+list[0]-1)
  }

}

func gcd(a, b int) int {
    if b == 0 {
        return a
    }
    return gcd(b, a%b)
}

func lcm(a, b int)int {
    return a * b / gcd(a, b);
}

