func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if len(os.Args) > 1 {
		fp, _ = os.Open(os.Args[1])
		if len(os.Args) > 2 {
			wfp, _ = os.Open(os.Args[2])
		}
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	k := getNextInt(scanner)
	aa := make([]int64, k)

	for i := k - 1; i >= 0; i-- {
		aa[i] = getNextInt64(scanner)
	}

	dpmn := make([]int64, k+1)
	dpmx := make([]int64, k+1)

	dpmx[0] = 2
	dpmn[0] = 2

	for i := 0; i < k; i++ {
		dpmx[i] -= dpmx[i] % aa[i]
		dpmx[i+1] = dpmx[i] + aa[i] - 1
		if dpmx[i+1] < aa[i] {
			fmt.Fprintln(writer, -1)
			writer.Flush()
			return
		}
		dpmn[i+1] = ((dpmn[i]-1)/aa[i] + 1) * aa[i]
	}
	fmt.Fprintln(writer, fmt.Sprintf("%d %d", dpmn[k], dpmx[k]))

	writer.Flush()
}

