export class Reader {
    lines: string[];
    currentLine: number;

    constructor() {
        this.lines = fs.readFileSync("/dev/stdin", "utf8").trim().split("\n");
        this.currentLine = 0;
    }

    readLine(): string {
        return this.lines[this.currentLine++];
    }

    readInt(): number {
        return Number(this.readLine());
    }

    readInts(): number[] {
        return this.readLine().split(" ").map(Number);
    }
}

function div(a: number, b: number): number {
	return Math.floor(a/b);
}


function solve(): number[] {
	let reader = new Reader();
	let answer = 0;
	let K = reader.readInt();
	let A = reader.readInts();
	/**
	 * 4
	 * 3 | 4 | 3 | 2 |
	 *   4,5  3-5   2,3   2
	 6   6   4   3   2
	 8   6   .   .   .
	                 2
	S[i+1]=S[i]-S[i]%A[i]
	S[i+1]%A[i] == 0
	S[i]=S[i+1]...S[i+1]+(A[i]-1)

	S[N+1] = 2
	S[N] = 2-3 must be divisble by 3 = 3
	S[N-1] = 3-5 must be divisible by 4 = 4
	4-7
	each S represented by possible range and divisible numbers in the range.
	 */
	let start = 2, end = 2;
	let N = 2;
	for(let i=K-1; i>=0; i--) {
		if (div(end, A[i]) == div(start-1, A[i])) {
			return [-1];
		}
		N = (div(end, A[i]))*A[i];
		[start, end] = [N, N+(A[i]-1)];
	}
	return [N, N+A[0]-1];
}

