import * as fs from 'fs';

export class Reader {
    lines: string[];
    currentLine: number;

    constructor() {
        this.lines = fs.readFileSync("/dev/stdin", "utf8").trim().split("\n");
        this.currentLine = 0;
    }

    readLine(): string {
        return this.lines[this.currentLine++];
    }

    readInt(): number {
        return Number(this.readLine());
    }

    readInts(): number[] {
        return this.readLine().split(" ").map(Number);
    }
}

function div(a: number, b: number): number {
	return Math.floor(a/b);
}

function solveHigh(A: number[], K: number): number {
	let start = 2, end = 2;
	let N = 2;
	for(let i=K-1; i>=0; i--) {
		if (div(end, A[i]) == div(start-1, A[i])) {
			return -1;
		}
		N = (div(end, A[i]))*A[i];
		[start, end] = [N, N+(A[i]-1)];
	}
	return N+A[0]-1;
}


function solveLow(A: number[], K: number): number {
	let start = 2, end = 2;
	let N = 2;
	for(let i=K-1; i>=0; i--) {
		if (div(end, A[i]) == div(start-1, A[i])) {
			return -1;
		}
		if (start%A[i] == 0) {
			N = start;
		} else {
			N = (div(start, A[i])+1)*A[i];
		}
		[start, end] = [N, N+(A[i]-1)];
	}
	return N;
}


function solve(): number[] {
	let reader = new Reader();
	let answer = 0;
	let K = reader.readInt();
	let A = reader.readInts();
	let low = solveLow(A, K),
		high = solveHigh(A, K);
	if (high == -1)
		return [-1];
	return [low, high];
}

