auto solve( long[] as )
{
	auto mi = 2L;
	auto ma = 2L;
	foreach_reverse( a; as )
	{
		auto di = cast( long )( a * ( cast( real ) mi / a ).ceil );
		auto da = cast( long )( a * ( cast( real ) ma / a ).floor + a - 1 );
		if( ma < di ) return "-1";
		mi = di;
		ma = da;
	}
	return format( "%s %s", mi, ma );
}

