{
	auto mi = 2L;
	auto ma = 2L;
	foreach_reverse( a; as )
	{
		auto di = cast( long )( a * ( cast( float ) mi / a ).ceil );
		auto da = cast( long )( a * ( cast( float ) ma / a ).floor + a - 1 );
