import numpy as np

def slove(k, a):
    a = np.array(a, dtype=np.uint32)

    if a[-1] > 3 or a[-2] > 3:
        return -1

    b = a[1:]
    b = np.append(b, 0)
    b *= 2
    diff = a - b

    if (diff[:-1] > 0).any():
        return -1

    minNum = a[0]
    while (minNum < a.max()):
        minNum *= 2

    maxNum = minNum + a[0] - 1

    return ("{0} {1}".format(minNum, maxNum))


