def slove(k, a):
    a = np.array(a, dtype=np.int64)
    if a[-1] > 3 or a[-2] > 3:
        return -1

    diff = a[:-1] - (2*a[1:])

    if (diff >= 0).any():
        return -1

    minNum = a[0]
    while (minNum < a.max()):
        minNum += minNum

    maxNum = minNum + a[0] - 1

    return ("{0} {1}".format(minNum, maxNum))


