def is_prime(num):
    if(num < 2):
        return 1
    if(num == 2 or num == 3 or num == 5):
        return num
    if(num % 2 == 0):
        return 2
    if(num % 3 == 0):
        return 3
    if(num % 5 == 0):
        return 5

    # 疑似素数(2でも3でも5でも割り切れない数字)で次々に割っていく
    prime = 7
    step = 4
    num_sqrt = math.sqrt(num)
    while prime <= num_sqrt:
        if num % prime == 0:
            return prime
        prime += step
        step = 6 - step

    return num

