from fractions import gcd
def calc(n, N, p, q):
    n, N = n*q//gcd(n, q), N*q//gcd(N, q)
    L, R = 0, 10**9
    while L+1 < R:
        M = (L+R)//2
        if n <= p*M:
            R = M
        else:
            L = M
    if n+(q-1) < p*R:
        n = -1
    else:
        n = p*R
    L, R = 0, 10**9
    while L+1 < R:
        M = (L+R)//2
        if N+q <= p*M:
            R = M
        else:
            L = M
    if p*L < N:
        N = -1
    else:
        N = p*L
    return n, N

