def slove(k, a):
    if int(a[-1]) > 3 or int(a[-2]) > 3:
        return -1

    num = 0
    index = -2
    for i in range(k-1):
        if i != k-2:
            if 2*int(a[index]) < int(a[index-1]):
                return -1
        if int(a[index]) > 2:
            tmp = int(a[index])
            if tmp > num:
                num = tmp
            else:
                while (tmp < num):
                    tmp *= 2
                num = tmp
        index -= 1

    if num == 0:
        minNum = 2
        maxNum = 3
    else:
