def calc_min_max(a_lis, min_val=None, max_val=None):
    if not a_lis:
        return min_val, max_val
    a, *next_a_lis = a_lis
    if min_val is None:
        if a != 2:
            return -1
        return calc_min_max(next_a_lis, min_val=2, max_val=3)
    if max_val < a:
        return -1
    new_min_val = ((min_val + a - 1) // a) * a
    new_max_val = (max_val // a) * a + a - 1
    return calc_min_max(next_a_lis, min_val=new_min_val, max_val=new_max_val)


