def solve(rounds):
    mx, mn = 3, 2
    if rounds[-1] != 2:
        return (-1,)
    for r in reversed(rounds[:-1]):
        if mx < r:
            return (-1,)
        mn = ceil(mn / r) * r
        mx = mx // r * r + r - 1
    if mn > mx:
        return (-1,)
    return mn, mx


