fn solve(aa: &Vec<i64>) -> Option<(i64, i64)> {
  let mut l = 2;
  let mut r = 2;
  for &a in aa.iter().rev() {
    let next_l = (l + a - 1) / a * a;
    let next_r = r / a * a + a - 1;
    if next_l > next_r {
      return None;
    }
    l = next_l;
    r = next_r;
  }
  Some((l, r))
}

