fn solve(mut a: Vec<u64>) -> Option<(u64, u64)> {
    if a.pop() != Some(2) {
        return None;
    }
    let (mut min, mut max) = (2, 3);
    for s in a.into_iter().rev() {
        if s > max {
            return None;
        }
        if min % s > 0 {
            min += s - min % s;
        }
        max = cmp::max(min, max);
        max = cmp::max(max, max + s - (max % s) - 1);
    }
    Some((min, max))
}

