fn ceil(x: i64, a: i64) -> i64 {
    let y = x/a;
    if x%a == 0 {
        a*y
    } else {
        a*(y+1)
    }
}
fn floor(x: i64, a: i64) -> i64 {
    let y = x/a;
    a*y
}
fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        k:usize,
        a:[i64;k]
    }

    let mut b_lo = 2;
    let mut b_hi = 2;

    for i in (0..k).rev() {
        assert!(b_lo <= b_hi);
        let ai = a[i];
        b_lo = ceil(b_lo, ai);
        if b_lo > b_hi {
            println!("-1");
            return
        }
        b_hi = floor(b_hi, ai) + ai - 1;
    }

    println!("{} {}", b_lo, b_hi);
}

