fn find_min_num(num_man_in_groups: &[u32], last_num_man: u32) -> Option<u32> {
    let len = num_man_in_groups.len();
    if len == 0 {
        return Some(last_num_man);
    }

    let last = *num_man_in_groups.last().unwrap();
    if last_num_man % last > 0 {
        return None;
    }

    for last_drop in 0..last {
        let ret = find_min_num(
            num_man_in_groups.get(0..len - 1).unwrap(),
            last_num_man + last_drop,
        );
        if let Some(_) = ret {
            return ret;
        }
    }

    None
}

fn find_max_num(num_man_in_groups: &[u32], last_num_man: u32) -> Option<u32> {
    let len = num_man_in_groups.len();
    if len == 0 {
        return Some(last_num_man);
    }

    let last = *num_man_in_groups.last().unwrap();
    if last_num_man % last > 0 {
        return None;
    }

    for last_drop in (0..last).rev() {
        let ret = find_max_num(
            num_man_in_groups.get(0..len - 1).unwrap(),
            last_num_man + last_drop,
        );
        if let Some(_) = ret {
            return ret;
        }
    }

    None
}

fn main() {
    // 00:04:00
    let num_rounds = read::<u32>();
    let num_man_in_groups = read_cols::<u32>();
    let last_num_man = 2;

    assert_eq!(num_rounds as usize, num_man_in_groups.len());

    let min = find_min_num(num_man_in_groups.as_slice(), last_num_man);
    if min.is_none() {
        println!("-1");
        return;
    }

    let max = find_max_num(num_man_in_groups.as_slice(), last_num_man);
    println!("{} {}", min.unwrap(), max.unwrap());
}

