    let num_rounds = read::<u32>();
    let num_man_in_groups = read_cols::<u32>();
    let last_num_man = 2;

    assert_eq!(num_rounds as usize, num_man_in_groups.len());

    match find(num_man_in_groups.as_slice(), last_num_man) {
        Some((min, max)) => println!("{} {}", min, max),
        None => println!("-1"),
    };
}

