fn lower_bound<F>(l: usize, r: usize, criterion: F) -> usize
where
    F: Fn(usize) -> bool,
{
    let mut l = l;
    let mut r = r;
    while r - l > 1 {
        let mid = l + (r - l) / 2;
        if criterion(mid) {
            r = mid;
        } else {
            l = mid;
        }
    }
    if criterion(l) {
        l
    } else {
        r
    }
}

fn solve() {
    let k = get!(usize);
    let a = get!([usize]);

    let mut mx = 2;
    let mut mn = 2;
    for i in (0..k).rev() {
        if mx % a[i] > 0 && mn % a[i] > 0 && mx/a[i] == mn/a[i] {
            println!("-1");
            return;
        }
        mx = if mx % a[i] == 0 {
            mx+a[i]-1
        } else {
            let crit = |val: usize| {
                val/a[i] == mx/a[i]
            };
            let mxt = lower_bound(mn,mx+1,crit);
            mxt+a[i]-1
        };
        mn = if mn % a[i] == 0 {
            mn
        } else {
            let crit = |val: usize| {
                val/a[i] > mn/a[i]
            };
            let mnt = lower_bound(mn,mx+1,crit);
            mnt
        };
    }
    println!("{} {}", mn, mx);
}

