use std::cmp::*;
use std::io::*;

fn check(mut x: usize, a: &Vec<usize>, f: bool) -> bool {
    for i in 0..a.len() {
        if x < a[i] {
            return false;
        }
        let rem = x % a[i];
        x -= rem;
    }
    if f {
        x >= 2
    } else {
        x <= 2
    }
}

fn main() {
    let mut s: String = String::new();
    std::io::stdin().read_to_string(&mut s).ok();
    let mut itr = s.trim().split_whitespace();
    let n: usize = itr.next().unwrap().parse().unwrap();
    let a: Vec<usize> = (0..n)
        .map(|_| itr.next().unwrap().parse().unwrap())
        .collect();

    let mut l = 0;
    let mut r = 1 << 60;
    while r - l > 1 {
        let mid = (l + r) >> 1;
        if check(mid, &a, true) {
            r = mid;
        } else {
            l = mid;
        }
    }
    if l == 0 {
        println!("-1");
        return;
    }
    let ans = r;

    l = 0;
    r = 1 << 60;
    while r - l > 1 {
        let mid = (l + r) >> 1;
        if check(mid, &a, false) {
            l = mid;
        } else {
            r = mid;
        }
    }
    if l == 0 {
        println!("-1");
        return;
    }
    println!("{} {}", ans, l);
}

use std::io;

fn main() {
    let mut buf: String = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    buf = String::new();
    io::stdin().read_line(&mut buf).unwrap();
    let iter = buf.trim().split_whitespace();
    let mut nums: Vec<i64>  = Vec::new();
    for i in iter {
        nums.push(i.parse::<i64>().unwrap());
    }
    nums.reverse();
    let mut n_max = 2;
    let mut n_min = 2;
    for n in nums {
        if n_max % n != 0 {
            n_max -= n_max % n;
        }
        if n_min % n != 0 {
            n_min += n - n_min % n;
        }
        if n_min == 0 { n_min = n; }
        if n_max == 0 { println!("-1"); return; }
        n_max += n - 1;
    }
    println!("{} {}", n_min, n_max);
}

