trait IteratorExt: Iterator {
    fn toVec(self) -> Vec<Self::Item>;
}

impl<T: Iterator> IteratorExt for T {
    fn toVec(self) -> Vec<Self::Item> {
        self.collect()
    }
}

trait CharExt {
    fn toNum(&self) -> usize;
    fn toAlphabetIndex(&self) -> usize;
    fn toNumIndex(&self) -> usize;
}
impl CharExt for char {
    fn toNum(&self) -> usize {
        return *self as usize;
    }
    fn toAlphabetIndex(&self) -> usize {
        return self.toNum() - 'a' as usize;
    }
    fn toNumIndex(&self) -> usize {
        return self.toNum() - '0' as usize;
    }
}

trait VectorExt {
    fn joinToString(&self, s: &str) -> String;
}
impl<T: ToString> VectorExt for Vec<T> {
    fn joinToString(&self, s: &str) -> String {
        return self
            .iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(s);
    }
}

trait StringExt {
    fn get_reverse(&self) -> String;
}
impl StringExt for String {
    fn get_reverse(&self) -> String {
        self.chars().rev().collect::<String>()
    }
}

trait UsizeExt {
    fn pow(&self, n: usize) -> usize;
}
impl UsizeExt for usize {
    fn pow(&self, n: usize) -> usize {
        return ((*self as u64).pow(n as u32)) as usize;
    }
}

fn main() {
    input! {
       N: usize,
       a:[usize;N],
    }

    let mut ans: usize = 0;
    let mut tmp = vec![(0, 0); N];
    tmp[N - 1] = (a[N - 1], a[N - 1]);
    for i in (0..N - 1).rev() {
        let b = a[i];
        let (c, d) = tmp[i + 1];
        let e = ((c + b - 1) / b) * b;
        let f = e + b - 1;
        tmp[i] = (e, f);
    }
    mydbg!(tmp);
    for i in 0..N - 1 {
        let (b, c) = tmp[i];
        let (d, e) = tmp[i + 1];
        let f = a[i + 1];
        if (b / f) * f > e {
            mydbg!(b, c, d, e, f);
            echo!(-1);
            return;
        } else if (b / f) * f < d {
            echo!(-1);
            return;
        }
    }

    echo!(vec![tmp[0].0, tmp[0].1].joinToString(" "));
}

