  let _ = get::val::<usize>();
  let xs = get::vec::<usize>();

  let mut ans = 2;
  for &x in xs.iter().rev() {
    //dump!(ans);
    if x == ans {continue}
    if x > ans && (x%ans != x-ans) {println!("-1"); return}
    if x > ans {ans = x; continue}
