}

fn dfs(val: usize, round: usize, a: &Vec<usize>) -> Option<(usize, usize)> {
    if val % a[round] != 0 {
        return None;
    }
    if round == 0 {
        return Some((val+a[0]-1, val));
    }

    let mut mx = 0;
    let mut mn = std::usize::MAX;
    for i in 0..a[round] {
        if let Some((mxt,mnt)) = dfs(val+i,round-1,a) {
            mx = max!(mx, mxt);
            mn = min!(mn, mnt);
        }
    }
    if mx == 0 {
        None
    } else {
        Some((mx,mn))
    }
}

fn solve() {
    let k = get!(usize);
    let a = get!([usize]);

    let res = dfs(2, k-1, &a);
    if let Some((mx,mn)) = res {
        println!("{} {}",mn,mx);
    } else {
        println!("-1");
    }
}

