fn solve(mut a: Vec<u64>) -> Option<(u64, u64)> {
    let (mut min, mut max) = match a.pop() {
        Some(1) => (2, 2),
        Some(2) => (2, 3),
        _ => return None,
    };
    for s in a.into_iter().rev() {
        if s > max {
            return None;
        }
        if min % s > 0 {
            min += s - min % s;
        }
        max = cmp::max(max, max + s - (max % s) - 1);
    }
    Some((min, max))
}

