fn f(x: usize, a: &[usize]) -> usize {
    let mut rest = x;
    for &v in a.iter() {
        rest = rest / v * v;
    }
    rest
}
fn solve() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let k: usize = sc.read();
    let a: Vec<usize> = sc.vec(k);
    let min_val = {
        let mut left = 0;
        let mut right = 1usize << 60;
        let mut result = None;
        while right - left > 1 {
            let med = (right + left) / 2;
            let tmp = f(med, &a);
            if tmp >= 2 {
                right = med;
            } else {
                left = med;
            }
            if tmp == 2 {
                if result.is_none() {
                    result = Some(med);
                } else {
                    if result.unwrap() >= med {
                        result = Some(med);
                    }
                }
            }
        }
        result
    };
    let max_val = {
        let mut left = 0;
        let mut right = 1usize << 60;
        let mut result = None;
        while right - left > 1 {
            let med = (right + left) / 2;
            let tmp = f(med, &a);
            if tmp <= 2 {
                left = med;
            } else {
                right = med;
            }
            if tmp == 2 {
                if result.is_none() {
                    result = Some(med);
                } else {
                    if result.unwrap() <= med {
                        result = Some(med);
                    }
                }
            }
        }
        result
    };
    if min_val.is_none() || max_val.is_none() {
        println!("{}", -1);
        return;
    }
    println!("{} {}", min_val.unwrap(), max_val.unwrap());
}

fn main() {
    std::thread::Builder::new()
        .stack_size(64 * 1024 * 1024) // 64MB
        .spawn(|| solve())
        .unwrap()
        .join()
        .unwrap();
}

