use std::cmp::Ordering;

fn binary_search_by<F>(mut f: F) -> usize
    where
        F: FnMut(usize) -> Ordering,
{
    use std::cmp::Ordering::*;
    let mut size = std::usize::MAX;
    let mut base = 0usize;
    while size > 1 {
        let half = size / 2;
        let mid = base + half;
        let cmp = f(mid);
        base = if cmp == Greater { base } else { mid };
        size -= half;
    }
    let cmp = f(base);
    base + (cmp == Less) as usize
}

fn solve<R: BufRead, W: Write>(mut input: R, mut output: W) {
    let mut buf = String::new();
    input.read_line(&mut buf).unwrap();
    let _: usize = buf.trim_right().parse().unwrap();
    buf.clear();
    input.read_line(&mut buf).unwrap();
    let a: Vec<usize> = buf.split_whitespace().map(|x| x.parse().unwrap()).collect();
    let eval = |x| a.iter().fold(x, |acc, &x| acc / x * x);
    let lo = binary_search_by(|x| if eval(x) >= 2 { Ordering::Greater } else { Ordering::Less });
    let up = binary_search_by(|x| if eval(x) > 2 { Ordering::Greater } else { Ordering::Less });
    if lo == up {
        writeln!(output, "-1").unwrap();
    } else {
        writeln!(output, "{} {}", lo, up - 1).unwrap();
    }
}

fn main() {
    let stdin = io::stdin();
    let stdout = io::stdout();
    solve(stdin.lock(), stdout.lock());
}

