fn solve(k: usize, arr: &[u64]) -> Option<(u64, u64)> {
    let (mut minimum, mut maximum) = (2, 2);
    for i in (0..k).rev() {
        minimum += (arr[i] - minimum % arr[i]) % arr[i];
        if minimum > maximum {
            return None;
        }
        maximum += arr[i] - maximum % arr[i] - 1;
    }
    Some((minimum, maximum))
}

